window.POEM_DB=window.POEM_DB||{};POEM_DB["song_049"]={"n":"韩维","dyn":"宋","poems":[{"t":"谒孔先生","f":"五言古诗","c":["月出高树枝，影动酒樽处。","树深月色薄，稍以灯火助。","主人喜我过，斟酌亦云屡。","于时幸无累，所谈非近务。","凉风自远生，清景澹吾虑。","方期西山秋，历览陪杖屦。"]},{"t":"太后阁六首 其三","f":"五言绝句","c":["平晓开朱户，轻寒御练衣。","宫童移钿扇，庆寿早朝归。"]},{"t":"太后阁六首 其二","f":"五言绝句","c":["玉律生阳早，金铺上日迟。","枝间双鹊语，应是报春祺。"]},{"t":"太后阁六首 其一","f":"五言绝句","c":["正阃成王化，开宫奉母仪。","身当四海养，寿祝万年期。"]},{"t":"太皇太后阁六首 其五","f":"七言绝句","c":["长乐钟残宝殿开，鸣梢移仗问安来。","欲知纯孝通天地，和气氤氲绕御杯。"]},{"t":"太皇太后阁六首 其六","f":"七言绝句","c":["残冰未放沟声滑，小雨频催柳色新。","昼漏渐长无一事，坐披黄老味天真。"]},{"t":"太后阁六首 其五","f":"七言绝句","c":["綵仗朝来散玉京，绮窗新网结初晴。","静呼宫女教调曲，闲引皇孙看学行。"]},{"t":"太后阁六首 其四","f":"七言绝句","c":["金花镂胜随春燕，綵仗萦丝逐土牛。","迎得韶华入中禁，和风次第遍神州。"]},{"t":"太后阁六首 其六","f":"七言绝句","c":["九奏清新称玉斝，八珍和旨奉兰羞。","须知天子娱亲意，不为乘春事燕游。"]},{"t":"太皇太后阁六首 其四","f":"七言绝句","c":["镂成宝字题宫户，剪出名花趁御筵。","人世不知春色早，忽惊歌吹下中天。"]},{"t":"太皇太后阁六首 其一","f":"五言绝句","c":["位历三朝重，风行四海深。","坐将仁厚意，潜助发生心。"]},{"t":"太皇太后阁六首 其二","f":"五言绝句","c":["铜霤消残冻，朱楼拂早霞。","传声回步辇，来赏小桃花。"]},{"t":"太皇太后阁六首 其三","f":"五言绝句","c":["视膳回天仗，含饴乐圣辰。","定应彤管笔，书美系王春。"]},{"t":"夫人阁四首 其一","f":"五言绝句","c":["腊雪馀香径，朝晖上绮甍。","翠生兰蕙色，和入管弦声。"]},{"t":"夫人阁四首 其二","f":"五言绝句","c":["重锦褰妆幕，轻罗换舞衣。","钗头双燕子，先向社前飞。"]},{"t":"皇后阁五首 其四","f":"七言绝句","c":["紫兰红蓼簇春盘，晓逐金壶下太官。","朝遍三宫归已晚，日华明丽雪消残。"]},{"t":"皇后阁五首 其五","f":"七言绝句","c":["葭灰已逐阳和动，绣缕初随日景加。","欲助君王修俭德，不将宫样织新花。"]},{"t":"皇后阁五首 其二","f":"五言绝句","c":["春色平明到，微风弄綵幡。","稍回宫柳弱，更助壁椒温。"]},{"t":"皇后阁五首 其一","f":"五言绝句","c":["后德侔姬国，嫔风协舜家。","进贤阳为长，修教月增华。"]},{"t":"皇后阁五首 其三","f":"五言绝句","c":["暖日晖晖动，清渠决决流。","六宫修岁事，拂拭采桑钩。"]},{"t":"春贴子皇帝阁六首 其五","f":"七言绝句","c":["晴日渐消宫瓦雪，和风微散御炉烟。","千官拜舞皇恩罢，綵胜金幡下九天。"]},{"t":"春贴子皇帝阁六首 其六","f":"七言绝句","c":["早莺啼滑知寒薄，午马休迟觉昼长。","四海欢康几务暇，箫韶时奉万年觞。"]},{"t":"春贴子皇帝阁六首 其一","f":"五言绝句","c":["和气生金殿，微风转画旗。","年年好春色，先是帝家知。"]},{"t":"春贴子皇帝阁六首 其四","f":"五言绝句","c":["昼漏新添刻，春寒早放班。","恩随宽大诏，一日遍人间。"]},{"t":"春贴子皇帝阁六首 其二","f":"五言绝句","c":["迎气来归胙，宜春祝降祥。","皇心勤治切，应喜寸阴长。"]},{"t":"春贴子皇帝阁六首 其三","f":"五言绝句","c":["醇醴浮金斝，柔蔬饤玉盘。","尝新兼介寿，齐奉两宫欢。"]},{"t":"夫人阁四首 其四","f":"七言绝句","c":["宫娃拂晓已催班，拜谢春幡列御前。","不待东风报花信，红酥綵缕斗芳妍。"]},{"t":"又和史院晚出","f":"七言绝句","c":["新雨稍添清禁润，斜阳初下直庐明。","方惭饱食无裨补，更作长廊百步行。"]},{"t":"又绝句","f":"七言绝句","c":["芙蓉落尽荷叶黄，西风测测梧桐凉。","岁登讼息休吏早，林间独坐歌还乡。"]},{"t":"子华兄生日五首 其五","f":"七言绝句","c":["白鹤群飞散作阴，方春膏雨一犁深。","只知万物含芳润，谁识清通造化心。"]},{"t":"子华兄生日五首 其四","f":"七言绝句","c":["柳阴散释真阳艳，妄虑消除至道冥。","浮世短长何足道，须知时节在明星。"]},{"t":"子华兄生日五首 其三","f":"七言绝句","c":["萱甲微抽碧玉簪，已惊花艳动筠篮。","便须行乐迎东律，莫为回神滞北庵。"]},{"t":"子华兄生日五首 其二","f":"七言绝句","c":["池面和风丽稍开，翠条芳甲满春台。","笙歌竞奏长生曲，兄弟华颠对举杯。"]},{"t":"子华兄生日五首 其一","f":"七言绝句","c":["秀眉华发貌安和，五福于今得最多。","诸圣共忘心外境，八仙同入饮中歌。"]},{"t":"卞仲谋八老会","f":"七言绝句","c":["同榜同僚同里客，斑毛素发入华筵。","三杯耳热歌声发，犹喜欢情似少年。"]},{"t":"太素雪中惠小桃","f":"七言绝句","c":["细雪繁飘远近来，三冬佳气一朝回。","莫嫌天上琼花晚，元待人间粉艳开。"]},{"t":"夫人阁四首 其三","f":"七言绝句","c":["薄暖正当挑菜日，轻阴渐变养花天。","君王勤政稀游幸，院院相过理管弦。"]},{"t":"对雪偶成三颂呈芳公长老兼简收贵二上人 其二","f":"七言绝句","c":["闻君鼎足话无生，说尽无生及有生。","几日西郊回杖锡，小窗同听竹风声。"]},{"t":"玉汝惠猫头笋","f":"七言绝句","c":["汉臣问鹏曾游地，腊祭迎猫始出林。","解箨光先凝片玉，含甘珍重等兼金。"]},{"t":"和微之饮杨路分家听琵琶 其一","f":"七言绝句","c":["酒熟梅香腊后天，春莺巧啭忽当筵。","共嗤白傅辛勤甚，万唤千呼始上船。"]},{"t":"和微之饮杨路分家听琵琶 其二","f":"七言绝句","c":["遇酒逢春触处春，白头相视若天伦。","须知丞相官仪重，不及琳宫自在人。"]},{"t":"再和尧夫同前 其一","f":"七言绝句","c":["朱弦四十昔尝闻，艺不论多贵绝伦。","少损新声放平淡，免教醉杀白头人。"]},{"t":"再和尧夫同前 其二","f":"七言绝句","c":["教得新声十二弦，每逢嘉客便开筵。","春湖水绿花争发，好引红妆上画船。"]},{"t":"再和尧夫欲借琵琶妓 其二","f":"七言绝句","c":["谢公故事常携妓，白傅高年自唱歌。","更假红妆知有意，欲添尊酒十分多。"]},{"t":"再和尧夫欲借琵琶妓 其一","f":"七言绝句","c":["画船西去水成乡，玉管朱弦出上方。","衰病不须多酌我，次公非酒亦能狂。"]},{"t":"再赋颂二首 其二","f":"七言绝句","c":["阳景朝来释冻凘，水边林下好追随。","灵山一会何曾散，莫学时人语别离。"]},{"t":"再赋颂二首 其一","f":"七言绝句","c":["两膝双盘一足垂，历然宾主席间仪。","惟应露柱方能识，只恐仙陀也不知。"]},{"t":"因题象罔亭榜呈太素","f":"七言绝句","c":["一颗圆明不欠亏，胡来胡现大钧知。","如今象罔浑无用，榜样从教作世师。"]},{"t":"尧夫垂示佳驾辄次二韵为谢","f":"七言绝句","c":["横笛能为水龙响，清歌不放綵云飞。","知君未尽杯中兴，故折红芳赠醉归。"]},{"t":"戏示程正叔范彝叟时正叔自洛中过访","f":"七言绝句","c":["曲肱饮水程夫子，宴坐烧香范使君。","顾我未能忘外乐，绿尊红芰对朝曛。"]},{"t":"次韵和唐公北使途中见寄二首 其二","f":"七言绝句","c":["残红著树春无几，怅望君家绿玉杯。","美酒应容步兵醉，后堂先约戴崇开。"]},{"t":"次韵答提刑王朝奉席上看梅见贻","f":"七言绝句","c":["诚己从来不问天，肯将衰白慕华轩。","调羹岂是山翁事，只合看花对酒樽。"]},{"t":"次韵答微之","f":"七言绝句","c":["空门欲问君何得，灭色终非我所能。","岑寂欢狂均有待，无相与处是良朋。"]},{"t":"百门义呈君俞辄成短章","f":"七言绝句","c":["一微尘上百门成，空里花飞谷里鸣。","海印元来君自有，聊将黄叶止啼声。"]},{"t":"红薇花","f":"七言绝句","c":["杏梅成实夏阴浓，波面繁花刺眼红。","莫为春归减欢兴，共将弦管乐薰风。"]},{"t":"君俞惠诗觅洛中所得大金菊辄次韵酬二篇 其二","f":"七言绝句","c":["禅老心真异众心，不缘歌舞费黄金。","春芳落尽慵开眼，豫乞寒花伴苦吟。"]},{"t":"杜君章家赋海棠二首 其二","f":"七言绝句","c":["濯锦江头千万枝，当年未解惜芳菲。","今朝得向君家见，不怕春寒雨湿衣。"]},{"t":"杜君章家赋海棠二首 其一","f":"七言绝句","c":["长条无风亦自动，繁艳著雨更相宜。","少陵不奈被花恼，终日颠狂觅酒卮。"]},{"t":"芙蓉五绝呈景仁 其五","f":"七言绝句","c":["携觞日日绕珍丛，未必欢情尽醉中。","却怕后时无意思，杀风景似范家翁。"]},{"t":"芙蓉五绝呈景仁 其一","f":"七言绝句","c":["堂前堂后尽芙蓉，晴日烘开万朵红。","不把一樽酬胜赏，忍看憔悴落霜风。"]},{"t":"芙蓉五绝呈景仁 其四","f":"七言绝句","c":["不辞晨起立秋风，为爱浓芳露满丛。","若比洛阳花盛品，万枝开遍瑞云红。"]},{"t":"芙蓉五绝呈景仁 其三","f":"七言绝句","c":["少年尝记作西游，尤蕊奇葩夹道秋。","今日家园开烂熳，恍疑身在蜀江头。"]},{"t":"芙蓉五绝呈景仁 其二","f":"七言绝句","c":["小沾清露细摇风，养得新花次第红。","客至莫教樽酒燥，朝吟夕赏未知穷。"]},{"t":"闲居思湖上","f":"七言绝句","c":["远泛每思随雁鹜，深居半是避杯觥。","官闲日永无馀事，卧听朱弦教曲成。"]},{"t":"和三兄立冬祠太乙二首 其二","f":"七言绝句","c":["曾为祝史趋真馆，屈指于今二十年。","琪树瑶林成想像，直疑当日梦游仙。"]},{"t":"和子华对雨有感 其二","f":"七言绝句","c":["雪白朱红已万枝，年年长恨失花期。","莫嗟飞雨淹游棹，却赖春寒发较迟。"]},{"t":"和太素双头牡丹兼呈子华","f":"五言绝句","c":["群英日零谢，并蒂发奇芳。","愿以附驿使，为兄寿且昌。"]},{"t":"和太素密杏","f":"七言绝句","c":["甘滋不假蜂房取，美种疑随鹤驭来。","方朔偷桃徒语尔，安期食枣足珍哉。"]},{"t":"和王詹叔寄彭年四首 其四","f":"七言绝句","c":["一曲清琴满架书，万钟于我亦分铢。","他年欲作林泉计，为问山前有地无。"]},{"t":"和王詹叔寄彭年四首 其三","f":"七言绝句","c":["层楼飞观压溪流，缥缈当从海上求。","病间体轻尘虑静，好追仙子御风游。"]},{"t":"和王詹叔寄彭年四首 其二","f":"七言绝句","c":["断瓢疏罟入提携，浊酒徐倾鲙缕肥。","雨后碧山来爽气，松间明月尚清辉。"]},{"t":"和王詹叔寄彭年四首 其一","f":"七言绝句","c":["纷纷声里满埃尘，一听除书耳目新。","清世未能忘薄禄，官曹犹得作闲人。"]},{"t":"和玉汝赠收上人","f":"七言绝句","c":["道得都来是八成，圣无功用已非灵。","凭君谛视丹霞路，依旧云山点点青。"]},{"t":"和冲老雪颂","f":"七言绝句","c":["揉絮琼飞晓尚飘，平吞六合蔽层霄。","从来不打禾山鼓，且向樽前看绿腰。"]},{"t":"和杜孝锡展江亭三首 其一","f":"七言绝句","c":["斜日低云动水光，偶寻佳处阅群芳。","城闉不隔和风度，吹过千花百草香。"]},{"t":"和述古河阳感怀之作","f":"七言绝句","c":["大河雄胜昔常游，拥节题诗为少留。","我亦华颠无用者，碧嵩清颍是归头。"]},{"t":"和提刑千叶梅 其一","f":"七言绝句","c":["层层玉叶黄金蕊，漏泄天香与世人。","闲寂未须嗟失地，年年长冠百花春。"]},{"t":"和提刑千叶梅 其二","f":"七言绝句","c":["擢玉自成超俗格，施朱不学入时妆。","莫将罗幕轻遮护，从放樽前自在香。"]},{"t":"和景纯栽松 其一","f":"五言绝句","c":["芳根出涧底，秀木依墙东。","莫顾一时好，当观三世空。"]},{"t":"和景纯栽松 其二","f":"五言绝句","c":["论坚莫如松，言脆莫如葱。","坚脆卒同尽，无尽无如翁。"]},{"t":"和微之游湖春夏秋冬四绝 其一","f":"七言绝句","c":["冰散玉珂微弄暖，梅含金粉巧矜新。","道人不管年光逝，贪作诗章等待人。"]},{"t":"和微之游湖春夏秋冬四绝 其二","f":"七言绝句","c":["花边鹭立红云里，林下人行翠幄中。","炎暑吾今知所避，全家移入广寒宫。"]},{"t":"和微之游湖春夏秋冬四绝 其四","f":"七言绝句","c":["画舫新成水拍堤，悲丝急管韵参差。","吟风啸月年年事，未省曾经兴尽时。"]},{"t":"和微之游湖春夏秋冬四绝 其三","f":"七言绝句","c":["败荷衰折水西流，极目清光好放舟。","幸有主人频卜昼，肯同俗子更悲秋。"]},{"t":"奉和君俞以子华古德颂见示","f":"七言绝句","c":["百尺竿头进步人，随缘偶物莫非真。","君看日用如何讨，即此空身是法身。"]},{"t":"奉答祖印喜雪二颂 其一","f":"七言绝句","c":["细逐流风遍大田，皑然一色绝中边。","空生惯识岩中镜，何似天花乱坠年。"]},{"t":"奉答祖印喜雪二颂 其二","f":"七言绝句","c":["久旱终能不失时，田家喜气吐虹霓。","庞公昔日曾垂语，资福今朝更指迷。"]},{"t":"招彝叟厚之饮台上花间","f":"七言绝句","c":["恍然身世出尘心，香霭祇园地布金。","秉烛听歌不知醉，夜深清露满衣襟。"]},{"t":"城西书事五首 其一","f":"五言绝句","c":["蔬畦绕茅屋，林下辘轳迟。","霜蔓已除架，风飘空挂篱。"]},{"t":"某伏蒙寄示五言二韵诗辄次韵上呈聊以见志","f":"五言绝句","c":["尚不求真语，何能计妄言。","且饶只么会，犹是弄精魂。"]},{"t":"送张七元构仕亳州","f":"七言绝句","c":["萧条平马逐飞蓬，回首园林平露中。","政事文章君得法，如今太守古人风。"]},{"t":"闻太素绝食饮水颇甚清羸以诗见招","f":"七言绝句","c":["曲肱饮水归寒士，服气休粮号道人。","顾我非寒亦非道，好来相伴祭身神。"]},{"t":"闻彝叟游展江亭","f":"七言绝句","c":["西亭不觉又春风，弱柳微波四面中。","更欲烦君亭下看，海棠枝上浅深红。"]},{"t":"展江亭海棠四首 其四","f":"七言绝句","c":["人避寒风与暖曦，年年长此探花期。","如今太守尤珍爱，只许官娃带一枝。"]},{"t":"展江亭海棠四首 其三","f":"七言绝句","c":["红糁妆条袅袅长，人间不合有天香。","千觞未足酬佳丽，回首东风更断肠。"]},{"t":"展江亭海棠四首 其二","f":"七言绝句","c":["昔年曾到蜀江头，绝艳牵心几十秋。","今日栏边见颜色，梦魂不复过西州。"]},{"t":"展江亭海棠四首 其一","f":"七言绝句","c":["占尽人间丽与华，白头判得醉流霞。","谁将法锦翻新样，红绿装成遍地花。"]},{"t":"润州","f":"五言绝句","c":["雄风摇碧绿，画角吊黄昏。","一带分江记，双峰点海门。"]},{"t":"病起呈景仁","f":"七言绝句","c":["卧病经旬独掩门，名园空想绿阴繁。","牡丹时节重来会，尝记公非醉后言。"]},{"t":"致仕后次韵答张念七 其一","f":"七言绝句","c":["颍水箕山一老生，漠然心境两俱平。","倘来物外皆如寄，腰底悬金壁挂缨。"]},{"t":"致仕后次韵答张念七 其二","f":"七言绝句","c":["一榻高眠只自思，累朝荣宦竟何为。","颠毛白尽朱颜改，惟有丹心似旧时。"]},{"t":"读白乐天传及文集 其一","f":"七言绝句","c":["才高文赡富诗名，感物伤时动有情。","不识无生真自体，一尘才遣一尘生。"]},{"t":"读白乐天传及文集 其二","f":"七言绝句","c":["直道危言自古难，忠贤常困佞邪安。","兴王赏谏非无法，却为贪令自择官。"]},{"t":"读白乐天传及文集 其三","f":"七言绝句","c":["仲尼饥饿颜回夭，此意谁能问大钧。","何事香山白居士，每嗟衰老亦言贫。"]},{"t":"寄大觉禅师","f":"七言绝句","c":["闻住金山最上方，江云飘槛海风凉。","何时乞得东南守，重拂尘衣入道场。"]},{"t":"庵中睡起五颂寄海印长老 其五","f":"七言绝句","c":["火衰水劣病馀身，未散虚空一聚尘。","更欲强招年少客，折花同赏梦中春。"]},{"t":"庵中睡起五颂寄海印长老 其一","f":"七言绝句","c":["闲窗日射寒松影，枕上风传过雁声。","梦境觉来无一际，不劳唇齿话无生。"]},{"t":"庵中睡起五颂寄海印长老 其三","f":"七言绝句","c":["剡竹纫丝杂短长，谁教曲折号宫商。","自从眠处知消息，终日笙歌是道场。"]},{"t":"庵中睡起五颂寄海印长老 其四","f":"七言绝句","c":["饭后西堂百步行，困来合眼是无营。","从生至老非他物，道著如今已是情。"]},{"t":"庵中睡起五颂寄海印长老 其二","f":"七言绝句","c":["四风标韵出风尘，高下虽殊一色均。","为我终朝谈实相，参差庭柏敞精神。"]},{"t":"晚过湖上登城楼泛小舟归 其二","f":"七言绝句","c":["绿水逶迤城两面，清风摇动稻千畦。","独乘幽兴携樽酒，小艇归时月已低。"]},{"t":"晚过湖上登城楼泛小舟归 其一","f":"七言绝句","c":["蛩响渐依阶砌下，萤光乱出草莱间。","炎蒸散尽人轻健，从此篮舆数往还。"]},{"t":"累日不到西园瑞香忽已烂熳","f":"七言绝句","c":["锦官翻样出新机，浅绿深红各自宜。","不是东风送香气，幽花落尽有谁知。"]},{"t":"黄莲花 其二","f":"七言绝句","c":["只将萧洒与温醇，敌尽千花百草春。","欲赋清诗写深愿，却疑潜笑白头人。"]},{"t":"黄莲花 其一","f":"七言绝句","c":["浅白轻黄两未分，飞来人世作朝云。","天教细雨常遮护，留得清香数日闻。"]},{"t":"黄莲花 其三","f":"七言绝句","c":["一水盈盈独立时，六铢衣薄透冰肌。","临川已没龙丘远，辜负芳妍乞好祠。"]},{"t":"景仁雨中同游南园 其二","f":"七言绝句","c":["宿醉厌厌晓尚曛，卷帘清思满风云。","久嫌日暖撩人困，却喜花香带雨闻。"]},{"t":"景仁雨中同游南园 其一","f":"七言绝句","c":["暖日催花落夕曛，轻雷一夜变重云。","安舆少滞无多怪，涩雨悭风自古闻。"]},{"t":"曾通直见惠风琴","f":"七言绝句","c":["剡竹纫丝匠意深，泠然终日自成音。","吾君方急民财阜，好助薰风入舜琴。"]},{"t":"游北园辄成二颂呈芳公长老 其二","f":"七言绝句","c":["青山隐约林端见，碧水逶迤竹下来。","芳草落花无朕迹，与君亲到北园回。"]},{"t":"游北园辄成二颂呈芳公长老 其一","f":"七言绝句","c":["万法都来一道场，游行何处不真常。","临风不用提玄旨，翠竹森森自短长。"]},{"t":"游象罔亭偶成二绝 其二","f":"七言绝句","c":["竹色隐波流不去，莲香浮坐断还闻。","诛茅结宇才方丈，占尽清风与白云。"]},{"t":"游象罔亭偶成二绝 其一","f":"七言绝句","c":["泛尽溪流数曲清，竹阴开处见新亭。","山翁不会题牌意，犹守枯枝看道经。"]},{"t":"湖上招曼叔","f":"七言绝句","c":["故人旌旆镇邻城，未奏骊歌已怆情。","莫为炎蒸慵命驾，绿荷红芰水风清。"]},{"t":"新作西北门楼","f":"七言绝句","c":["赤白崔嵬晚照间，投闲时复一跻攀。","时平守望皆无用，添得清秋数点山。"]},{"t":"新得小石呈景仁","f":"七言绝句","c":["泥沙洗尽太湖波，状有嵌崆势亦峨。","可笑尚平游五岳，不如坐视一拳多。"]},{"t":"照禅师久欲一见比至汝则已游矣因题广惠","f":"七言绝句","c":["高僧寂寞空尘坐，古寺悲凉足野风。","道在岂须烦目击，亭前双柏自葱葱。"]},{"t":"蒙惠拄杖及诗依韵奉答","f":"七言绝句","c":["藤枝既老解纵横，禅老因何解道情。","识取个中无把捉，眼前瓦砾是瑶琼。"]},{"t":"酴醾","f":"七言绝句","c":["平生为爱此香浓，仰面常迎落架风。","每至春归有遗恨，典刑犹在酒杯中。"]},{"t":"赠曹大夫三绝 其二","f":"七言绝句","c":["窃禄偷安到白头，一闻高韵使人羞。","如今便欲归休去，已愧迟君八九秋。"]},{"t":"赠曹大夫三绝 其一","f":"七言绝句","c":["落落明珠骇暗投，知君所得在无求。","直须言下通非句，识取澄潭皎洁秋。"]},{"t":"赠曹大夫三绝 其三","f":"七言绝句","c":["势利驱人去若流，君才六十便归休。","归时不及家无有，但问松安竹健不。"]},{"t":"九日席上赋得茱萸","f":"五言律诗","c":["寥落霜园树，萸房独照秋。","实兼兰佩结，香近玉卮浮。","嗔蕊醒残醉，纫红感旧游。","三英佳句在，殊喜继风流。"]},{"t":"九月十日游象之葆光亭寄曼叔","f":"五言律诗","c":["几负高阳约，蹉跎此岁华。","论心看翠竹，感事对黄花。","寒日悽征雁，清霜急暮鸦。","临风一樽酒，回首意无涯。"]},{"t":"又和子华","f":"七言律诗","c":["沉阴消尽见春和，初放扁舟溯绿波。","水际踏青怜日暖，林间举白为花多。","狂从田妇窥篱看，醉任家童刮鼓歌。","年少纵欢饶点检，老欢终不挂谁何。"]},{"t":"又和北轩竹上甘露","f":"五言律诗","c":["君家竹上露，点缀如明珰。","垂枝乍惊重，映日复能光。","聊可助清兴，安知为羡祥。","应从草制暇，延咏对华觞。"]},{"t":"又和馆西迎驾","f":"七言律诗","c":["宫树烟开敞禁扉，儒冠罗立望天威。","霜清广殿鸣鞘肃，日上觚棱翠盖飞。","玉勒帕鞍龙在御，锦衣腰剑士成围。","暂来直舍支颐坐，却听箫韶辇路归。"]},{"t":"又和寒食感怀","f":"七言律诗","c":["絮飞丝堕满春阴，叹息流光节物深。","鸡鞠自喧游侠地，莺花空思长年心。","寂寥功业看孤剑，淡薄情怀寄素琴。","我亦新来有华发，并须携酒白头吟。"]},{"t":"与林大夫谢灵寿杖","f":"七言律诗","c":["万岁山中美木成，古今灵寿得嘉名。","龙鳞未测他年化，蜗角先从每节生。","禅拟问来须便打，醉思吟后不妨行。","使君有惠怜衰薾，欲报惭非藻思清。"]},{"t":"久雨奉怀象之九兄","f":"五言律诗","c":["萧洒崔居士，高闲养性灵。","凉风满樽酒，永日一函经。","竹色垂遮户，桐花开满庭。","未嗟相见阔，交照本忘形。"]},{"t":"之石桥","f":"七言律诗","c":["闻说西桥水树间，不辞驱马涉风烟。","疏篱老屋临官道，瘦棘荒茅蔽石田。","欲下鸣鸦盘木末，远来惊雉落山前。","瓢中幸有村醪美，不怕春寒雨满川。"]},{"t":"之雍丘舟中奉寄少述处士明叔公缊","f":"七言律诗","c":["柔橹咿哑画鹢东，翛然清兴不知穷。","新秋草树轻凉外，落日帆樯远思中。","人事感心怀素友，年华催鬓作衰翁。","江湖旧约今仍负，肠断从南万里风。"]},{"t":"千叶梅","f":"七言律诗","c":["南园卉木遍春光，独爱琼葩掩众芳。","不为雪摧缘正色，忽随风至是真香。","未经采折携樽酒，忍见飘零入野塘。","醉客为予簪白发，栏边几作少年狂。"]},{"t":"予会宾答微之惠诗","f":"七言律诗","c":["官冷身闲百不营，一时高会得耆英。","杯心酒气兼香重，池面水华共月清。","铁骑忽从弦上出，水龙争向笛中鸣。","白头学士耽禅习，未免诗魔搅道情。"]},{"t":"予招宾和微之","f":"七言律诗","c":["恩予琳宫庇病身，闲中得近酒杯频。","偶成五老追前会，仍喜三公作主宾。","欢兴到来歌自发，吝情消尽语皆真。","时人不用惊疏放，同是羲皇以上人。"]},{"t":"云","f":"五言律诗","c":["抱石情虽久，为霖意若何。","天心如见用，风力不消多。","冷湿朝仙洞，寒迷宿鸟窠。","飞扬终得路，曾入汉皇歌。"]},{"t":"从厚卿乞移水仙花","f":"七言律诗","c":["翠叶亭亭出素房，远分奇艳自襄阳。","琴高住处元依水，青女冬来不怕霜。","异土花蹊惊独秀，同时梅援失幽香。","当年曾效封培力，应许移根近北堂。"]},{"t":"元日寄袁州仲文兄","f":"七言律诗","c":["前日都门尽鹢飞，秋风执别泪交颐。","清朝远谪庸非命，直道终申自有时。","佳句应因子卿赋，胜游仍共鹡鸰期。","宜春台上春归早，谁伴花前酒一卮。"]},{"t":"公时遗石榴","f":"七言律诗","c":["高冠趋尹君方掾，促席迎宾我已翁。","交态不忘平日厚，歌声犹似少年工。","映阶露菊秋吟苦，盈筥霜榴岁问通。","每与东邻话知旧，白头强健几人同。"]},{"t":"公美侍郎赋诗见诒次韵答谢","f":"七言律诗","c":["哭兄悲友老来情，默默终朝究道精。","双毂幸回贤者驾，一觞聊展故人诚。","身随风力常无住，辩若河源每自倾。","早晚东城见华屋，与君垂白话无生。"]},{"t":"六弟亲诣松楸时祭","f":"七言律诗","c":["上冢还家古所荣，白头今日倍伤情。","怀今又出高阳里，夹道争看太守旌。","应念少游尝有语，可能疏氏独高明。","昔湖水色清堪濯，毋使尘埃久污缨。"]},{"t":"化光殿丞谒告还里某数奉游集蒙赋诗道旧辄依元韵","f":"七言律诗","c":["定契多惭国士知，交欢重喜故人期。","莫辞日嚼千觞酒，况值春归百卉枝。","披竹共寻前会处，插花仍学少年时。","词章褒纪明情重，坐讽行吟刻屡移。"]},{"t":"水阁","f":"五言律诗","c":["约略横云岛，栏干瞰玉渊。","雨汀翘睡鹭，风树咽嘶蝉。","绿发莓苔地，红衣菡萏天。","夜深三弄笛，月在钓鱼船。"]},{"t":"王岩叟招饮南园","f":"七言律诗","c":["翠木珍丛百亩间，我来虽晚及春残。","未嗟流景飘蓬疾，犹喜馀芳对酒看。","斜照舒迟明埤堄，清阴迢递覆栏干。","凭君莫剪高花尽，留插游人醉后冠。"]},{"t":"长安留别七弟兼简刘郎","f":"七言律诗","c":["二年牢落坐回山，平日交亲梦寐间。","关外相逢非素约，樽前一笑慰衰颜。","匡衡沿牒朝廷远，王粲从军幕府閒。","跋马题诗离绪乱，霜风萧飒鬓毛班。"]},{"t":"东郊","f":"七言律诗","c":["东郊丝雨破浮埃，绣骑寻芳两两来。","十亩霜阴青翳目，一篙溪色碧于苔。","林花泛日莺求友，垄麦含风雉应媒。","绿柳朱栏多酒市，杖头谁伴玉山颓。"]},{"t":"东禅院坐上作","f":"七言律诗","c":["山林曾是自由身，岂合区区入世尘。","萧散未能忘故态，优游聊喜及时春。","闲中浊酒偏亲我，风外飞花欲趁人。","多谢鸣鸠催对雨，坐惭无术粒斯民。"]},{"t":"次韵君俞偶成 其一","f":"五言律诗","c":["我道非生灭，天时自去来。","交亲常在席，醪酒不空罍。","默坐唯听水，閒行忽见梅。","何人同此适，君意亦悠哉。"]},{"t":"次韵君俞偶成 其二","f":"五言律诗","c":["雪意凝还解，冰纹结复开。","林鸦时啸侣，城雉不忧媒。","造适心无碍，忘机语绝猜。","曹溪不欺我，何处有尘埃。"]},{"t":"冬日喜雨呈稚卿景仁","f":"七言律诗","c":["严冬温气袭人间，忽听繁声慰病颜。","从律好风千里至，执权真令一朝还。","顿抽陇麦全如揠，欲绽江梅已可攀。","主尹勤民嘉岁望，径携歌鼓乐幽闲。"]},{"t":"冬夜","f":"五言律诗","c":["繁阴扫无迹，庭雪尚馀光。","屋背生寒月，林梢绡暗霜。","昏瞳频废卷，悲泪易沾裳。","却想故园夜，张灯宿草堂。"]},{"t":"北园坐上探题得新杏","f":"五言律诗","c":["红蘤随风尽，团枝泣露光。","叶深惊乍见，实小贵先尝。","点缀怜馀萼，飘零惜旧香。","不须悲节物，且喜手中觞。"]},{"t":"去冬蒙君实示嘉篇懒拙不即修谢临书走笔深愧浼渎","f":"七言律诗","c":["南园百草雨中秋，把烛题诗寄驿邮。","意重不辞终日看，韵强深愧隔年酬。","登山屡赴幽人约，筑野犹稽圣主求。","命驾幸无千里远，春湖舣楫待君游。"]},{"t":"史局坐寝戏呈崇文掌学士","f":"五言律诗","c":["闲官身散诞，饱食坐攲斜。","永日槐阴静，清风葆鬓华。","废书良愧马，落帽偶同嘉。","此适谁知者，逢人莫浪誇。"]},{"t":"对雪看梅","f":"七言律诗","c":["持梅况酒诚为得，对雪看梅始见真。","失素定应潜送腊，露红如欲巧矜春。","神凝姑射今仍在，云覆巫峰晓更新。","谁识仙家事严秘，舞妍妆靓不传人。"]},{"t":"对雪送花走笔况之","f":"七言律诗","c":["春阴黯黯压城低，乱扑帘帷细点衣。","梅蕊更寒犹竞发，杨花未暖忽先飞。","便思樽酒陪公议，敢望笙歌近使威。","绝景坐嗟清燕隔，一篮朱白慰旋归。"]},{"t":"对雪偶成三颂呈芳公长老兼简收贵二上人 其三","f":"七言律诗","c":["谁识天公造化情，珠楼玉殿一朝成。","色空无有何能辨，陵坎高低本自平。","定见乌鸡遭指注，宁分皓鹤失鲜明。","可怜辛苦齐腰客，不悟纷纷觌面呈。"]},{"t":"玉汝弟创治新居作诗见诒次韵为答","f":"七言律诗","c":["止足嘉言每念兹，不应华发叹归迟。","非关启第誇三战，直为营巢欠一枝。","盛放清风来北户，细分鸣溜入西池。","十年契阔多遗恨，今日欣同仲氏篪。"]},{"t":"伏蒙三哥以某再领许昌赋诗为寄谨依严韵","f":"七言律诗","c":["久陪法从常怀愧，再领乡州始觉荣。","政事敢言前可继，宠光深见古为轻。","预装白酒留春盎，旋剪红葩出洛城。","两道况闻时泽足，不妨吟啸玉杯倾。"]},{"t":"会微之诸君","f":"七言律诗","c":["开斋坐阅岁华空，乐与贤豪燕喜同。","清影屡移松桂月，和声频送管弦风。","远于籍外追歌妓，恨不樽前作醉翁。","况近始郊多废事，共迎萧露入弦中。"]},{"t":"再和二首 其二","f":"七言律诗","c":["应为开门近太清，故携歌管逐双旌。","酒逢欢后宁论量，语到真时不属情。","木叶吟风千籁作，菊丛含雨万珠明。","知公几案常丰暇，诗思如泉日夜生。"]},{"t":"再和二首 其一","f":"七言律诗","c":["壮岁希高事独清，介然何意慕三旌。","无邪每奉先儒戒，有犯常存狷者情。","任重股肱惭暗弱，老全骸骨赖休明。","非因大旆闲来往，仲蔚蓬蒿绕舍生。"]},{"t":"再和乐道","f":"七言律诗","c":["凤凰台下芳林合，鸭子陂中绿水深。","不惜清光输曲沼，欲将幽韵伴鸣琴。","馀波及晋良惭昔，春服沿沂正在今。","洗耳濯缨何足道，愿同沉醉复高吟。"]},{"t":"再和昌言喜雪 其二","f":"七言律诗","c":["愧无奇策辅吾皇，乞得闲官老故乡。","壮志未甘悲白发，欢情犹看舞红妆。","长歌不计闲光景，吟苦难滋旧肺肠。","多谢同心二三友，每传佳句挹华觞。"]},{"t":"再和昌言喜雪 其一","f":"七言律诗","c":["精祷潜通上下神，恍然佳气一朝新。","隆楼杰阁偏宜晓，槁木残荄尽变春。","有客裁诗传锦段，谁家度曲试朱唇。","相思不得相从乐，虚作箕嵩无事人。"]},{"t":"再游卞氏园亭","f":"五言律诗","c":["多谢春风意，残芳得我游。","绿阴人去远，翠竹鸟啼幽。","醉舞纷无次，狂歌漫不收。","林间簇车马，欲去尚迟留。"]},{"t":"同三兄安公亭看雨","f":"七言律诗","c":["高堂六月苦炎曦，雨逐轻雷过后池。","水面凉生跳赤鲤，林端声寂语黄鹂。","翠深岸筱无风乱，红重蔷薇到地垂。","清景虽嘉欢意少，白头支策坐题诗。"]},{"t":"同士则游西湖","f":"五言律诗","c":["今日西湖好，来游未觉喧。","柳枝风处乱，花艳暖中繁。","桥远归人渡，舟移集鸟翻。","何须更樽酒，道胜有清言。"]},{"t":"同化光饮象之家","f":"五言律诗","c":["又从邻舍客，来折主人花。","游处当年似，悲伤老去加。","兴长歌易放，情密语无哗。","归路生残月，春风醉袂斜。"]},{"t":"同化光陪宁极之滍阳城","f":"五言律诗","c":["不踏南溪路，于今五换春。","能来再联骑，还是旧游人。","置酒真乘兴，谈经或入神。","欢馀不无愧，林壑未还身。"]},{"t":"同江谢王出郊","f":"五言律诗","c":["东郊二月天，寒尽未成暄。","永日青丝骑，和风绿酒樽。","径抽萱甲细，墙倚杏梢繁。","烂醉谁知者，行歌入国门。"]},{"t":"同芳公上人游湖","f":"七言律诗","c":["晴阳溢目尽光华，乘兴闲来步径沙。","水满不知新穫稻，霜严犹放后凋花。","传心密处宁离妄，著眼高时亦是邪。","竟日清谈何所得，鱼沉鹭起各归家。"]},{"t":"同曼叔化光游卞氏园","f":"五言律诗","c":["野圃无人到，秋风共子行。","花临流水落，草上废台生。","气晚才看菊，天寒不见莺。","幽闲固多味，浊酒讵须倾。"]},{"t":"和永叔雪","f":"七言律诗","c":["二十年来野逸身，懒能奔走傍埃尘。","偶逢闾里闲游伴，同过丛林燕坐人。","世事纠纷宁有尽，劳生萧散不妨频。","晴阳缓辔殊多适，它日重来访道真。"]},{"t":"后园杂花特献辄书呈子华兄","f":"七言律诗","c":["向晚低云还作雨，稍寒飞雪又随风。","新芽展尽枝头绿，落蘤飘成水面红。","身外有名皆是妄，杯中无物未为通。","扁舟少待暗阳放，西阁何妨一醉同。"]},{"t":"字谷道中","f":"五言律诗","c":["驱车背河去，鸡犬几家村。","山断春风急，云生野气昏。","涉溪沙水乱，步径草花繁。","谷口多幽思，青林啼鸟喧。"]},{"t":"戏月","f":"五言律诗","c":["缺处还孤守，圆时亦独栖。","何曾闻合璧，只见是如圭。","桂子遗秋信，方诸寄夜啼。","建章残漏促，又伴玉绳低。"]},{"t":"次韵","f":"七言律诗","c":["势利拘牵无已时，超然真乐绝端倪。","家风淡寂从今见，人事尘劳与我暌。","门外旌旗犹坌拂，辕间款段已鸣嘶。","何当解组如初约，直与西京二傅齐。"]},{"t":"次韵玉汝","f":"七言律诗","c":["浮生难得是华颠，美景能并属禁烟。","况值公庭多暇日，且欣农亩兆丰年。","曾裁酒量容杯斝，谓品歌声被管弦。","莫道老人无气力，能排万事付陶然。"]},{"t":"次韵玉汝弟乞致仕不允","f":"七言律诗","c":["人生大节在行藏，七十归休有旧章。","红旆碧幢虽帝宠，紫嵩清颍是吾乡。","老依莲社心冲寞，梦绕榆关路杳茫。","何日安车解归鞅，浊醪鸡黍晏东岗。"]},{"t":"次韵君俞","f":"五言律诗","c":["世事真千变，年光又一新。","举生皆是幻，熙我莫如春。","啸傲盈樽酒，诗书满席尘。","园林已芳意，悬榻待高人。"]},{"t":"次韵和三兄田家","f":"五言律诗","c":["东皋雨新足，绿野对柴扉。","晴日风景旷，暮春草木肥。","好鸟依林响，疲牛望舍归。","饷妇散田陌，桑间人语稀。"]},{"t":"次韵和之美十日菊","f":"五言律诗","c":["孤根随地发，繁蕊破霜迟。","但取凋零晚，何忧赏爱移。","物情伤老大，人事阅兴衰。","会有陶彭泽，清樽与重持。"]},{"t":"次韵和厚卿答微之","f":"七言律诗","c":["秉节当官号直清，非招不往为虞旌。","书闻玉座光儒效，任久琳宫长道情。","老纵笔锋尤壮健，醉评花艳益精明。","吾人岂是蓬蒿士，默默拘挛过一生。"]},{"t":"次韵和唐公北使途中见寄二首 其一","f":"五言律诗","c":["文史平居乐，尘埃少别心。","都门开柳色，樽酒驻车音。","汉节光华远，春风藻思深。","一闻传丽句，清兴霭盈襟。"]},{"t":"次韵奉同景仁答微之","f":"七言律诗","c":["鸦腹灵砂养就丹，知公不复更衰残。","洛川花下经春醉，潩水亭边尽日欢。","白发高吟思老笔，青娥嘉赠伫华鞍。","淮阳过客如相问，莫道闲人姓范韩。"]},{"t":"次韵奉答四哥廷评欲垂访以诗为示","f":"七言律诗","c":["再临乡国两逢春，乞与优闲荷帝宸。","德薄敢同商四老，论狂难预汉诸臣。","行吟水际花粘履，燕坐林间絮点茵。","早晚湖波照车马，为君酌酒鲙鲜鳞。"]},{"t":"次韵奉答君俞","f":"七言律诗","c":["闾里幽居几案前，迹虽相异意同然。","禅书罢阅成端坐，讼牒希投得晏眠。","情累已知超永劫，身名那复计当年。","才疏政拙逢嘉岁，敢窃天功自谓贤。"]},{"t":"次韵答景仁喜雨","f":"五言律诗","c":["凉云四向复，沴气一消沉。","上天垂景贶，高秋沾喜霖。","槁苗变新实，时菊抽芳心。","聆君得意句，起我掉头吟。"]},{"t":"江亭晚眺","f":"五言律诗","c":["日下崦嵫外，秋生沆砀间。","清江无限好，白马不胜闲。","雨过云收族，天空月上弯。","归鞍侵调角，回首六朝山。"]},{"t":"自城南濠上步月之葆光","f":"五言律诗","c":["厌踏尘中路，远寻濠上行。","水声喧夜堑，月色满春城。","衎衎交游乐，依依里巷情。","优哉不知老，何暇慕轩缨。"]},{"t":"西轩会中与辛杨诸君同赋","f":"五言律诗","c":["一笑聊为适，非关事赏心。","芳菲逐风尽，时序感人深。","世事无多问，香醪且细斟。","更须乘月色，潇洒坐中林。"]},{"t":"西轩雨中期象之夜话","f":"五言律诗","c":["积雨空堂暮，清宵独掩门。","陈编徒自对，幽兴欲何言。","碧草生墙角，丹花发竹根。","聊持静者辙，一与道人论。"]},{"t":"西湖雨中同公懿诸君饮","f":"五言律诗","c":["十月平湖上，繁霜藻荇空。","柳枝横堕雨，波白细生风。","水鸟飞幽碧，寒花折浅红。","谁能尽一醉，灯火宿船篷。"]},{"t":"西墅","f":"五言律诗","c":["城居不为惬，言适西陂冈。","雀噪野堂静，鸡鸣春日长。","书棚落幽蠹，佛幔掩馀香。","释子庐岩至，清谈殊未央。"]},{"t":"观安公亭戏呈观文主人","f":"七言律诗","c":["十五年来此地行，白头重到不胜情。","寒梅未放黄金蕊，冰绽初流碧玉声。","憔悴霜松如有诉，纷披风竹似相迎。","红裙散后歌音绝，海鹤阶前时一鸣。"]},{"t":"观音精舍期邻几未至","f":"七言律诗","c":["懒驱羸马傍朱门，来对祇园寂寞春。","撩乱绕楼唯有燕，萧条垂箔更无人。","未回山简池头马，空愧陶公顶上巾。","留得清风满衣袖，为君吹尽鬓边尘。"]},{"t":"许昌道中","f":"五言律诗","c":["荒郊不可望，极目尽伤心。","日薄不开冻，风凄还作阴。","倦鸦飞趁马，寒犬吠依林。","赖有瓢中酒，愁来一独斟。"]},{"t":"过卞氏园亭","f":"五言律诗","c":["桃李郊扉静，东风拂面柔。","偶陪连骑客，来作探春游。","斜日池边树，轻云城上楼。","不须花艳动，一醉且淹留。"]},{"t":"过杜甫坟","f":"五言律诗","c":["三尺孤坟墓，空留万古名。","风骚谁是主，天地太无情。","入夜月虚白，逢春草自生。","耒阳江色迥，吊罢恨难平。"]},{"t":"过邵先生居","f":"五言律诗","c":["竹坞斜开径，茅檐半卷书。","幽闲入高卧，淡薄见平居。","乱水随酾引，残花不扫除。","因君动高兴，回首想吾庐。"]},{"t":"何龙图赴上秘阁同诸君赋诗","f":"七言律诗","c":["华阁岧峣冠道山，群公清晓集初筵。","独持金印承新命，重对牙签识旧编。","英俊雍容欣接袂，文章疏阔愧怀铅。","一时高会形风什，留作儒林故事传。"]},{"t":"况之席上作","f":"七言律诗","c":["桐叶翻飞荷芰香，好风吹暑作清凉。","便惊帘幕生秋气，径促金丝尽羽觞。","浮世已谙身是幻，高歌莫笑老仍狂。","知君不久还符竹，烂醉犹须教十场。"]},{"t":"呈诸先辈","f":"七言律诗","c":["谢事归来老白头，杜门终日绝营求。","顾惭义礼非先得，窃幸英豪许并游。","介寿又逢春酒熟，贻诗常骇暗珠投。","自惭筋力难为礼，不及低回奉献酬。"]},{"t":"运判再以前韵见寄","f":"七言律诗","c":["突兀朱堂冠北城，云峰满目互阴晴。","凭栏不负思山意，对酒何烦考鼓声。","清话从容双麈秃，雕章温丽百金轻。","归轩未必能相迟，梦绕西湖春水生。"]},{"t":"连日休务过邻几","f":"七言律诗","c":["广文自古无羁束，况复三逢著令休。","纵酒不防官长骂，驱车聊过故人游。","闲中日月随方罫，远外风云入小舟。","准拟墙根菊花好，共乘清露赏高秋。"]},{"t":"饮方君舍晚归","f":"五言律诗","c":["惨淡秋原思，归鞍暮向城。","野风吹酒散，寒日上衣明。","踯躅樵儿聚，喧呼猎骑轻。","村醪处处熟，准拟数来行。"]},{"t":"和十侄喜象之来饮兼简龙阳孔先生","f":"七言律诗","c":["世事茫然剧转蓬，一樽何意与君同。","从容谈笑皆尘外，恍忽游从似里中。","还有桂华来静夜，稍惊梧叶下秋风。","欲论归去令人愧，高卧襄阳有德公。"]},{"t":"和三兄晚饮","f":"七言律诗","c":["乍去炎氛浊暑中，高怀幽事不如穷。","乍怜老竹梢云碧，已见新梨著露红。","回雪舞腰来洛浦，仰天歌韵有秦风。","雄图壮节消磨尽，所得清樽一笑同。"]},{"t":"和三兄游湖","f":"七言律诗","c":["竹阴回抱柳阴敷，石色青青润不枯。","暂到已经风力劲，更清须待月轮孤。","波涵天影迷高下，云覆山光变有无。","暑退疾清人意健，纵吟狂醉是良图。"]},{"t":"和三哥立春即事","f":"七言律诗","c":["青帝收寒岁令回，綵幡今胜下天来。","人声恺乐归歌缶，风气恬和拂寿杯。","发逐时光明似雪，心谙世味冷于灰。","西堂梅蕊今年晚，应待安舆到始开。"]},{"t":"和之美春日对酒","f":"七言律诗","c":["高轩怒马一憧憧，夫子端居寂寞中。","绿酒细斟消暇日，朱弦缓拨对春风。","官闲势利无从入，道胜纷华岂易攻。","即此便堪遗万虑，可怜夸者自穷通。"]},{"t":"和子华见寄","f":"七言律诗","c":["松柏无心自后凋，此心无物更寥寥。","伯夷岂是归周晚，孟子空嗟出昼遥。","谈道每嗤犹有待，当官常欲取非招。","荒园寂寞无谁语，兰菊幽香没艾萧。"]},{"t":"和子华兄太素泛舟香菜门","f":"五言律诗","c":["霜髯照四坐，宛是商颜来。","舟移一水远，楼对群峰开。","谈笑尽永日，声利轻浮埃。","既同剡溪往，亦类稽山回。"]},{"t":"和子华兄方惜莺声之晚今忽闻之","f":"七言律诗","c":["山鸟凡禽处处鸣，独怜清啭久无声。","起从岩谷春风晚，飞过林塘霁日明。","不为好音轻俗耳，自逢真赏动诗情。","少年乐事今抛尽，节物催人只自惊。"]},{"t":"和子华兄同永叔饮三班官舍兼约明日饮永叔家","f":"七言律诗","c":["视草名臣润色才，玉墀晨退共徘徊。","朝廷无事文书省，台阁相欢笑语开。","少厌赓酬停落笔，旋寻歌舞约衔杯。","广文主簿官閒冷，不是诗情岂合来。"]},{"t":"和子华兄闻布谷声而莺声寂然","f":"七言律诗","c":["杨花飞尽叶成阴，坐阅啼禽百种声。","戴胜催耕当是月，杜鹃遗恨岂今生。","及时燕乐风骚急，感物伤嗟老大情。","自笑拙艰成底事，十年不听上林莺。"]},{"t":"和子华兄喜雨","f":"七言律诗","c":["膏润涵濡万物中，欣然生意满和风。","■飘先动吟毫紫，急洒疑催舞袂红。","病手便甘千日醉，疲农又得一年丰。","欢声定有歌尧壤，喜气遥瞻绕汉宫。"]},{"t":"和子华同程中散燕湖上","f":"七言律诗","c":["林塘潇洒夏阴初，翠窦红芳助燕娱。","不用俗音流乐府，自期仙御下蓬壶。","金跳巨鲤开纹浪，雪洒群鸦度绿梧。","日落人归尤胜绝，篮舆回首尽城隅。"]},{"t":"和子华安国明空颂","f":"五言律诗","c":["欲识真空理，须明动用间。","色心全不碍，生死岂相关。","卷箔凉风动，焚香昼景閒。","回头大行路，满目是青山。"]},{"t":"和子华湖上书事","f":"五言律诗","c":["清霜彫远木，潩水溢西陂。","画鹢凌空界，鸣鸥矫翠漪。","菊残犹可折，竹密不容窥。","物我同真际，谁当惮四知。"]},{"t":"和子华湖上避暑","f":"七言律诗","c":["堤边杨柳无穷碧，亭下芙蓉四面红。","岛影低回明镜里，荷香浮动绿樽中。","清心不厌飞山雨，动发时欣过水风。","鼎足坐谈非俗侣，不归名教即真空。"]},{"t":"和子履再游李氏园","f":"七言律诗","c":["翠竹苍林颜色老，游人安得故时同。","沾衣似对金城柳，握管翻悲楚水枫。","新鬓旋惊吟后白，好花犹记折来红。","须知世事徒劳耳，惟有清樽不负公。"]},{"t":"和六弟苦雨","f":"七言律诗","c":["雷激霆奔夜复晨，天街流潦没车轮。","清风皎日收无迹，妖蜧顽蛟亦有神。","荐至已惊占习坎，汨陈深恐败彝伦。","苍生可念非吾力，漏屋颓垣不庇身。"]},{"t":"和太素大雪苦寒","f":"五言律诗","c":["晨兴出户望，一色四方齐。","旋委清池失，偏欺翠竹低。","杯深怜绝景，毫健得新题。","丽藻思风絮，衰颜怯冻梨。"]},{"t":"和王都尉","f":"五言律诗","c":["乘槎天上客，脱帽酒中仙。","谈笑非俗韵，欢欣忘我年。","浩歌轻白雪，密意得青莲。","诗就西楼月，留为好事传。"]},{"t":"和乐道","f":"七言律诗","c":["红旆重来镇故乡，吏民欢喜拂牙床。","忽颁优渥垂天诏，仍许衰残守郡章。","自笑木鸡犹独立，人嗟竹马漫相将。","君皇念旧恩非浅，南北圭符各一方。"]},{"t":"和圣俞天津桥闻歌","f":"五言律诗","c":["飞雪朝来霁，朱楼月下过。","绝云看丽构，裂玉堕清歌。","醉烛轻摇箔，游鞍不动珂。","回头少年乐，惨淡一悲哦。"]},{"t":"和永叔从驾谒景灵宫","f":"七言律诗","c":["驰道尘清生紫烟，帝临原庙拜衣冠。","日华先向金舆动，霜气犹通玉仗寒。","后骑绵裘明粲粲，侍臣瑶佩响珊珊。","一闻佳句歌熙盛，不减都人夹路观。"]},{"t":"和永叔内直晨出马上口占","f":"七言律诗","c":["天门朝日照崔嵬，车骑雍容下禁台。","清景每将诗思遣，高情不为宠名回。","山林岂要须长往，轩冕当知是傥来。","欲与明公论出处，会乘飞雪旁金罍。"]},{"t":"和永叔思滁州幽谷","f":"七言律诗","c":["滁阳山水翳荒榛，公为开治物物新。","自作嘉名遍华榜，连题秀句入青岷。","泉声尚记岩寒夜，花思偏怜谷暖春。","绝境坐驰高兴动，安能碌碌久风尘。"]},{"t":"和永叔病中寄诸君子","f":"七言律诗","c":["几日东风独掩门，忽传佳咏感芳辰。","应缘高位须忧国，未必多情便负春。","过眼只看花艳疾，惊心初见草芽新。","狂吟烂醉无拘束，始信光阴属散人。"]},{"t":"和永叔雪","f":"七言律诗","c":["浴凤池边雪舞风，题诗高揖杜陵翁。","怀人共惜车音断，对酒须论盏底空。","授简久虚梁苑候，引舟谁过剡溪中。","今朝白雪闻君咏，千载风流未觉穷。"]},{"t":"和玉汝弟甘雨应祈","f":"七言律诗","c":["后稷明农佐有妫，耻令世有一夫饥。","勤民事业能如古，闵雨精诚必应时。","顿觉微凉生水际，尚思馀润浃天涯。","恤人自享宜君福，小疾何须更祝釐。"]},{"t":"和太素喜景仁新宅","f":"七言律诗","c":["处仁由智古常然，贤者宁同聚所寰。","植木便知如渭水，结茅仍得见箕山。","杯深不许嘉宾诉，花小须防稚子攀。","投绂归来无异事，许公诗酒断生还。"]},{"t":"和仲连兄城上晚步","f":"五言律诗","c":["久积端居滞，聊为散步游。","青苔跳怒黾，绿树矫鸣鸠。","雨暗横舟浦，凉生调角楼。","不妨乘晚兴，更尽水西头。"]},{"t":"和仲巽在高阳日作诗见怀而不见寄","f":"七言律诗","c":["常记当年并马鞍，翛然无事世尘间。","独怜交契如君少，仍喜官曹共我闲。","却顾旧游空岁月，欲传佳句邈河关。","从今会合尤须数，此别相看鬓已斑。"]},{"t":"和冲公上人","f":"五言律诗","c":["远色分诸岛，清光湛一陂。","鸟行排夕照，竹影乱风漪。","道体烦摩撮，禅心绝占窥。","由来输范老，佛法不曾知。"]},{"t":"和安国天钵拈香","f":"七言律诗","c":["杖策乘缘利有生，闻风犹得耳根清。","去年俱是凝然体，存殁徒伤妄者情。","灵骨不随烟共尽，真心常与月孤明。","世人欲识泥洹路，问取师今第几程。"]},{"t":"和尧夫思湖上秋时见寄","f":"七言律诗","c":["落尽芙蕖十顷红，败荷衰草满秋风。","夷犹画鹢来天外，嘹唳惊鸿入镜中。","亭榭装成如待我，樽罍开处便思翁。","粗官岂得君留滞，府第深严合在东。"]},{"t":"和朱主簿游园","f":"七言律诗","c":["白首昏昏度岁年，忽闻春至便开颜。","溪头冻水晴初涨，竹下名园昼不关。","旋得歌辞教妓唱，远寻梅艳唤人攀。","如今尚有官拘束，解组归来始是闲。"]},{"t":"和伯寿秘监","f":"七言律诗","c":["曾陪道论接清欢，屈指于今四十年。","不用笙歌娱上客，直将风月待高眠。","黄花一醉犹能否，白首相逢是偶然。","便欲投冠结闲伴，家山况与碧嵩连。"]},{"t":"和况之","f":"七言律诗","c":["湖上和风艳翠漪，柳枝摇动草芽齐。","珍禽綵翼嬉晴日，游女红裙上大堤。","新试画船浮鹢首，却惭美盎乏驼蹄。","喜君不负持杯约，正是桃花水满溪。"]},{"t":"和况之提刑途中遇雪","f":"七言律诗","c":["云凝野旷接高低，切切寒侵使者衣。","客路恍惊霜鬓改，家山回望玉觞飞。","更添宿雨催花润，未放春雷起蛰威。","柳色压堤清溜满，舣船持酒待君归。"]},{"t":"和君俞岁暮偶成","f":"五言律诗","c":["冻水迎风解，芳芽逐日新。","不惊身渐老，还喜物皆春。","发短频添雪，心虚不受尘。","鸡豚如有燕，莫忘社中人。"]},{"t":"和君俞春暮书事","f":"五言律诗","c":["举俗从多事，惟君独闭关。","废觞岂为戒，开卷不妨闲。","小雨清湖面，飞花乱席间。","应怜狂太守，心不到灵山。"]},{"t":"和君俞偶成","f":"五言律诗","c":["窃比淮阳卧，幸非庄舄吟。","政馀无异事，物外得同心。","遇兴倾浮蚁，投闲作戏禽。","世间并出世，于我两沉沉。"]},{"t":"和君俞喜雨","f":"七言律诗","c":["一夜歊炎散烈风，清和从令气潜通。","诚微敢谓天心应，政拙惟希岁事丰。","便有欢声南亩俗，首传佳句少陵翁。","心灰鬓雪无馀愿，饱食安居与众同。"]},{"t":"和张太中馆于西湖","f":"七言律诗","c":["湖榭从来与众同，况于清晏奉群公。","驱车即日趋翔凤，就馆初寒听过鸿。","霜雪满髯仍自壮，珠玑落笔不知穷。","太平鱼鳖今咸若，岂系区区一老翁。"]},{"t":"和杜七学士见寄","f":"七言律诗","c":["谋猷久恨辜明主，骸骨终蒙赐老臣。","绝口敢论当世事，放怀重老故园春。","闲寻物外忘言客，喜遇杯中得趣人。","能作新诗仍寄我，知君心不在埃尘。"]},{"t":"和贡甫","f":"七言律诗","c":["十年灯翳视浮荣，兀坐翛然槁木形。","别后情怀非往日，老来光景似流星。","厚恩未报心徒赤，多病何从发复青。","一览彫章思旧好，忽如醒病得初酲。"]},{"t":"和邵兴宗再还馆","f":"七言律诗","c":["莫嗟华发尚蓬瀛，自古儒生半滞荣。","学似杨雄老天禄，才如严助厌承明。","一箪聊喜安吾道，几骑当知达此生。","闻说东郊可携手，能来从我并鞍行。"]},{"t":"和邻几前岁同济川原甫赏阁后杏花今兹对之有怀二君","f":"七言律诗","c":["春风几日到蓬莱，仙伯初惊杏蕊开。","绕树独听清夜漏，怀人空对昔年杯。","坐怜珍赏同心隔，愁见新芳入眼来。","欲折繁枝有所赠，九重丹禁照瑶魁。"]},{"t":"和周仲章出郊","f":"七言律诗","c":["万里青天洗曙霜，秋曦满眼对晴光。","扫残遗秉川原静，折过寒花径隧荒。","偶入名园逢漆吏，远寻香刹问支郎。","浮生宠辱何须道，幸有田家浊酒尝。"]},{"t":"和定国廷评","f":"七言律诗","c":["孤身万里逐流人，两见炎洲末利春。","勋族每蒙朝念旧，圣恩方与士更新。","忘忧自有禅心静，禦瘴无先道气醇。","傅野为霖非我事，愿闻雷雨跃穷鳞。"]},{"t":"和昌言太中","f":"七言律诗","c":["眉秀瞳青却少容，精神强健几如公。","相逢细雨开篱菊，自愧繁霜满鬓蓬。","谈道远追西域祖，题诗今得少陵翁。","锋车北去归何日，且愿从容一笑同。"]},{"t":"和昌言谒见景仁所居话及洛事","f":"七言律诗","c":["重迁岂是贤人累，乐内非期俗子誇。","万瓦生烟新起第，一经消日旧传家。","浮舟共爱清湖色，披竹时寻曲水涯。","未信闲中无事役，隔年贪看别都花。"]},{"t":"和昌言喜雪","f":"七言律诗","c":["万里多仁德有邻，故交仍佩左鱼新。","欢娱每恨流阴驶，谈笑几还太古淳。","浮蚁生光盈寿斝，惊鸿取势落华茵。","题诗寂寞高眠冷，笑杀尊前起舞人。"]},{"t":"和欧阳内翰内直对月见寄","f":"七言律诗","c":["新衔佳命上金銮，递直连初寝未安。","霜气稍依罗幕重，月华先近玉堂寒。","诏函裁罢骞灵凤，诗句书成舞瑞鸾。","学省地閒清赏隔，怀贤空向斗杓看。"]},{"t":"和盈祖中散见寄","f":"七言律诗","c":["朝言民事两无裨，谢病还家独掩扉。","散发时从溪叟乐，荷锄仍逐野农归。","山当楼槛千螺髻，柳绕湖波万羽旂。","雕鴳逍遥各天分，抢榆何意著云飞。"]},{"t":"和原甫立春日拜赐归不赴邻几会","f":"七言律诗","c":["上阁群公拜赐归，九衢春色遍熙熙。","后房丝竹争相命，穷巷箪瓢亦我期。","浊酒满樽聊混俗，嘉蔬登俎在随时。","刘郎固自多幽思，门掩东风独赋诗。"]},{"t":"和原甫对月招江梅不至","f":"五言律诗","c":["尘事无时已，归休虑暂空。","超飖广庭步，萧散葛衣风。","默与清樽对，心期静者同。","独怜新月色，百过达幽丛。"]},{"t":"和晏相公初春","f":"五言律诗","c":["春物华犹少，春风思已多。","新黄先入柳，微绿自生波。","酒兴潜倾倒，诗情暗揣摩。","流年不须问，判作白头歌。"]},{"t":"和晏相公答张提刑州名诗三首 其二 讲德","f":"五言律诗","c":["上德钦明代，中阶翊亮司。","夔龙曜勋业，鸾凤肃威仪。","复古高文丽，为邦惠化绥。","还当奉侯瑞，归辅太平基。"]},{"t":"和晏相公答张提刑州名诗三首 其三 陈情","f":"五言律诗","c":["濠上蒙庄达，田中彭泽归。","安能陈道德，直可景光辉。","欣奉燕台集，恭陪汉相威。","阳春回丽曲，清越满金徽。"]},{"t":"和晏相公答张提刑州名诗三首 其一 颂圣","f":"五言律诗","c":["文德绥中夏，威灵镇远夷。","恩灵沧海润，基业泰山维。","汉曲白麟应，虞韶丹凤仪。","伪儒蒙景化，鼓舞庆淳熙。"]},{"t":"和晏相公答邵校勘","f":"七言律诗","c":["两朝典策成挥笔，二府勋庸在运筹。","历践枯荣皆德举，重陪閒燕是恩留。","康宁必有神明劳，萧洒真无世俗忧。","早晚安车赐高退，碧嵩清颍从公游。"]},{"t":"和曼叔","f":"七言律诗","c":["官路飘蓬奈别何，塞垣相见此情多。","酒樽重喜为亲寿，华发犹能继子歌。","行树坐思新种色，断冰应泛晚来波。","紫荆山下游从少，独把雕章醉后哦。"]},{"t":"和象之北轩书事","f":"五言律诗","c":["舍北多嘉树，重阴及四邻。","清风常满竹，好鸟不惊人。","图史无它物，讴吟佚此身。","应容千里客，一醉倒冠巾。"]},{"t":"和象之河上见怀之作","f":"七言律诗","c":["一昨芳郊祖画轮，索居南北对残春。","忽传河上相望意，未觉庵中独处人。","几有高怀投绂冕，尚缘微禄走风尘。","世间万事徒劳耳，清颍归来理钓纶。"]},{"t":"和景仁","f":"七言律诗","c":["平池旋涨西山雨，密竹频惊北户风。","垂箔屡销檀炷紫，出门时看杏梢红。","酒成岂见甘而坏，花在须知色即空。","只怪彫章今日至，不知清醉昨宵同。"]},{"t":"和景仁之什","f":"五言律诗","c":["美疢随冰释，微阳应律生。","严风散馀燠，密雪暗深更。","预喜衔杯集，当期策杖行。","知公有新庆，金奏动皇情。"]},{"t":"和景仁元夕 其二","f":"五言律诗","c":["禁户千通鼓，天街万点灯。","怀君瑩如玉，驱马不嫌冰。","乐事看流俗，狂游记旧朋。","回思真梦幻，不待访林僧。"]},{"t":"和景仁元夕 其一","f":"五言律诗","c":["月上朱楼角，风摇翠筱层。","传声回步辇，满目烂行灯。","箫鼓千门沸，弓刀万马腾。","诗翁怀盛事，眉雪惨霜棱。"]},{"t":"和景仁赋才元寄牡丹图","f":"五言律诗","c":["胜事常归蜀，奇葩又验今。","仙官裁样巧，彩笔费工深。","白岂容施粉，红须陋间金。","不嗟珍赏异，千里见君心。"]},{"t":"和景仁同游南园","f":"七言律诗","c":["喜公新就好林塘，方驾来游属盛阳。","广厦阴凉回暑气，平波炎赫变秋光。","酒中未免分清浊，身外何曾校短长。","地胜人高多乐事，须知洵美是吾乡。"]},{"t":"和景仁同稚卿湖光亭对雪","f":"七言律诗","c":["共喜忘怀势利间，每逢嘉景便开颜。","梅花冒雪轻红破，湖面先春嫩绿还。","浮蚁浓来当为釂，冥鸿高举不须攀。","我惭习气欢狂在，未及仙翁一纪闲。"]},{"t":"和景仁湖中","f":"七言律诗","c":["繁花乱委茵铺锦，弱柳交垂绿作笼。","竹影入波添旧翠，桥阴横岸见新红。","临觞善谑如平日，落笔佳章有古风。","早乏斯文华国体，更将何术代天工。"]},{"t":"和景仁探春 其二","f":"五言律诗","c":["才疏非所用，身退此其时。","静默安虚室，忧虞履薄凘。","景和闻鹊稔，花近候梅知。","杖履从兹数，非公孰与期。"]},{"t":"和景仁探春 其一","f":"五言律诗","c":["山色青螺髻，清波绿鸭头。","已欣春事起，那问岁阴流。","玉蚁新浮盎，金鳞恰上钩。","衰年怯多酌，尤怕范家瓯。"]},{"t":"和景仁喜晴","f":"五言律诗","c":["浓阴开积晦，和气散馀凄。","碧爱城阴草，红知花下泥。","啼鸡一声尽，归雁数行低。","溪路桃争发，须防去棹迷。"]},{"t":"和景仁寒食","f":"五言律诗","c":["韶华已过半，感叹固多同。","万室初藏火，千花竞笑风。","林光高蔼蔼，山气远葱葱。","洒泪松阡里，伤心白发翁。"]},{"t":"和景彝圣俞马上见槐花","f":"七言律诗","c":["天津南望两涯间，蓊若青云乍吐山。","花叶相催何日已，尘埃不断几人闲。","郎官萧洒裁诗丽，博士龙钟叹鬓班。","我独无诗亦无叹，朝驱羸马暮知还。"]},{"t":"和曾令绰买宅贻景仁","f":"七言律诗","c":["久治孤学慕轲丘，投老还乡寡所求。","蓬荜随缘安静默，林泉乘兴访深幽。","高门此地成君志，方驾何时写我忧。","白首故人知所待，一竿同钓鸭陂头。"]},{"t":"和曾令绰资政西湖见贻","f":"五言律诗","c":["虎节尝三换，琳宫亦再来。","白添新鬓发，红识旧亭台。","酒为迎寒好，花应趁暖栽。","但愁衰谢意，未到已思回。"]},{"t":"和曾通判招饮后见贻","f":"七言律诗","c":["竹际松间构小堂，高眠客榻燕华觞。","每询浊酒频加酿，不问馀金几在囊。","自愧效陶无好语，敢烦凌杜发新章。","庆门又喜亲才子，藉藉声华满士乡。"]},{"t":"和谢主簿游西湖","f":"七言律诗","c":["云阴开剥日光穿，和气随风近酒船。","湖面波清浑见底，楼头山碧自生烟。","兴长不忍回孤棹，歌懒才能逐缓弦。","因子樽前话归计，醉魂先到岘山边。"]},{"t":"和微之","f":"七言律诗","c":["风骚宿将勇于行，白日堂堂整旆旌。","再鼓未甘衰战气，千毫犹可奉诗情。","忘机始验朋欢浃，受恶方知酒令明。","了得本来常寂灭，一尘何足累无生。"]},{"t":"和微之宴张大夫家园","f":"七言律诗","c":["郎官高会一时贤，胜践幽栖近接联。","敢论怀黄誇故国，聊欣垂白上华筵。","同心况是论交旧，二首何疑贵老年。","东里作诗成故事，明珠当尽落吾前。"]},{"t":"和微之宴景仁新第","f":"七言律诗","c":["华构经营不日成，宛如图画著丹青。","温貂密坐浮香篆，绿蚁盈斟照弁星。","得地新篁皆袅袅，凌霜修桧自亭亭。","祝公眉寿长康乐，不学痴人事醉醒。"]},{"t":"和微之燕西湖","f":"七言律诗","c":["三月韶华大半过，好花零谢已无多。","暮年光景如残梦，浮世尘劳付浩歌。","游子有时眠岸草，啼禽终日在庭柯。","白头不作垂钩客，辜负春湖十里波。"]},{"t":"和詹叔游庐山见寄","f":"七言律诗","c":["香炉峰色压群山，仰眺频攲使者冠。","江面烟波摇紫翠，佛宫金碧照晴寒。","密藏幽谷梅千树，散走鸣泉竹万竿。","今日顿惊尘虑尽，一章佳句雪中看。"]},{"t":"奉同中道锁宿南宫思宝奎殿前花树子","f":"七言律诗","c":["曾见芳春二月时，弱枝繁萼动辉辉。","难忘绝艳惊心丽，重惜良游与意违。","好事几人能载酒，感时今日为沾衣。","南宫老树无妍思，坐想东风绛雪飞。"]},{"t":"奉同景仁九日宴相公新堂","f":"七言律诗","c":["高堂突兀里人惊，丞相规模固自宏。","移石远分嵩峤色，凿池切放潩泉声。","茱萸结佩聊同俗，鹦鹉传杯岂吝情。","右席先生亦华构，便应次第落新成。"]},{"t":"奉和介甫正月二日","f":"五言律诗","c":["春意来何早，乾坤润泽中。","雪明初照日，云断欲随风。","世事蚊虻过，身谋雁鹜同。","诸君亦诗酒，吾道未应穷。"]},{"t":"奉和乐道","f":"七言律诗","c":["昔闻有客荐扬雄，清世文章又见公。","奏赋独高天下士，辞荣远继古人风。","怀贤不啻三秋久，置酒须期十日中。","幸有红芳妆点在，可无多愧白头翁。"]},{"t":"奉和乐道席上见诒","f":"七言律诗","c":["大隗山前一老翁，幸分州契接群公。","饮豪肯放兵先北，论合须欣水必东。","坐对华灯燃宝檠，行看红艳发珍丛。","良辰胜事从兹始，嘉与吾民乐岁丰。"]},{"t":"奉和乔年馆宿","f":"七言律诗","c":["蓬莱仙构斗魁旁，递直初登汉署郎。","云向城头收暝色，月从楼角放寒光。","行看砌菊嗟残艳，坐对书芸袭暗香。","景物过清浑不寐，素经雠罢得新章。"]},{"t":"奉和仲通秋宴","f":"七言律诗","c":["参差天仗拂云台，雉尾分行剑佩来。","万寿称觞臣节罄，九韶张乐帝颜开。","班趋玉佩花相斗，舞入文茵雪屡回。","疏贱恭承湛露赐，惭无辞藻咏康哉。"]},{"t":"奉和君俞佳雪二首 其一","f":"七言律诗","c":["老来事事皆抛尽，惟独忧民尚有心。","深喜天公回气象，便同田父作讴吟。","缘何更得闾阎暖，恨不偏于垄麦深。","禅伯静中知我意，琅琅佳句玉其音。"]},{"t":"奉和君俞佳雪二首 其二","f":"七言律诗","c":["居尘不染先生意，与众同忧太守心。","两处本来非异事，一时都把付高吟。","忽惊瑞相家家遍，潜助春功日日深。","拥鼻临池哦丽句，水泉风竹共清音。"]},{"t":"奉和杨直讲除夜偶书","f":"七言律诗","c":["杨公白首困青騧，坐对流阴颇自嗟。","半夜星文穷斗次，平明春色遍人家。","漫将愁思惊天运，好看新诗待物华。","何日一樽相就醉，为君先探此园花。"]},{"t":"奉和运判朝散登乐山亭","f":"七言律诗","c":["看山日日上孤城，不问云昏与雪晴。","六六高峰长秀色，双双啼鸟忽春声。","心惊流水光阴逝，身慕冥鸿羽翼轻。","方促吏文严指使，不知诗兴坐中生。"]},{"t":"奉和府判学士景彝喜雪","f":"七言律诗","c":["朔风收尽冻云漫，细洒狂飘入夜寒。","润浃土膏谣万俗，喜闻玉色舞千官。","川原谁作呼鹰出，楼观朝宜跋马看。","亚尹勤民流咏叹，一章高唱掩幽兰。"]},{"t":"奉答乐道","f":"七言律诗","c":["禁职台纲佚旧儒，青林华屋俨高居。","炎天久隔挥犀论，暇日聊脂载酒车。","雨逼秋容生户牖，风回凉思入襟裾。","东朝第一推调护，圣主宁容久卧庐。"]},{"t":"奉答宋中道服除还朝示亲友","f":"七言律诗","c":["喧然佳句落神都，哀此援琴尚有馀。","未见校文登子政，空传为赋似相如。","道存固可轻华冕，谈进当知得异书。","推毂贤豪非我事，所期诗酒乐朋裾。"]},{"t":"奉酬君俞","f":"五言律诗","c":["夫君有奇尚，与世实相差。","不饮三春酒，唯看九日花。","名虽贤士籍，心自法王家。","顾我何能尔，东风醉弁斜。"]},{"t":"奉酬君俞席上偶成","f":"五言律诗","c":["候月纱笼合，看梅翠幄开。","满城均俗乐，同闬得君来。","笑极时倾弁，欢狂欲倒罍。","赋诗惭善祝，凡器岂公台。"]},{"t":"孤雁","f":"五言律诗","c":["节物何催逼，翩翩不可留。","枫丹湘渚暮，芦白楚江秋。","只影侵霜月，孤鸣入戍楼。","天高云路杳，安稳过罗浮。"]},{"t":"宝奎殿前花树子去年与宋中道同赋今复答宋诗","f":"七言律诗","c":["长条飞动不依栏，淡粉浓朱巧作团。","无语不辞终日立，有情曾是隔年看。","春罗试舞衣新换，古锦藏诗墨未乾。","我为愁多悲节物，欲酬佳句泪沾翰。"]},{"t":"废烽台","f":"五言律诗","c":["耆老不可问，高台荆棘间。","一时戎马散，千古暮鸦还。","事往孤鸿断，人来落照閒。","兴亡无限恨，惨淡对河关。"]},{"t":"招王微之","f":"五言律诗","c":["龙图老学士，腰痛比如何。","久阕新诗和，应寻曲旧歌。","梅红轻绽萼，池绿细生波。","欲与君同醉，春风试舞罗。"]},{"t":"武牢道中","f":"五言律诗","c":["春寒驱传马，西度虎牢关。","草树高低雪，烟云左右山。","英豪攻战地，风物笑谈间。","俯仰看今古，翛然百虑间。"]},{"t":"绍隆池上对月","f":"五言律诗","c":["野月来何处，东池柳影深。","微生水风力，稍散暝云阴。","冷极萤沈草，明多鹊动林。","欲知清绝兴，不寐有孤吟。"]},{"t":"范公新池","f":"七言律诗","c":["忘机人似汉川阴，取友从来亦断金。","华屋万楹开里第，清池十顷是家林。","笙歌喧甚犹能默，觞斝飞馀不废吟。","便欲与君从此适，藕花风外一披襟。"]},{"t":"范奉议作西江月劝酒","f":"七言律诗","c":["故里亲交半柏城，坐中牢落似明星。","雨多秋草荒三径，零重寒花坼万铃。","闲后并和诗笔废，兴来未放酒杯停。","樽前一曲西江月，犹识当年旧典刑。"]},{"t":"雨过化光西斋","f":"五言律诗","c":["华屋衡茅接，闲门杖屦通。","客来非载酒，君坐正书空。","白菊晚霜后，青蔬寒雨中。","从今日无事，来听竹窗风。"]},{"t":"临汝遇雨","f":"七言律诗","c":["回风萧飒过山西，一望平郊雨脚齐。","但使农畴苏旱稼，敢辞客路踏春泥。","暮投野寺明灯宿，声入幽窗绿树低。","明日尘清洛阳道，呼童严驾候晨鸡。"]},{"t":"城西二首 其二","f":"七言律诗","c":["西城驰道直如弦，百顷晴波御柳边。","韶乐铿轰罗帐殿，春旗偃蹇近楼船。","曲江未赐唐家燕，灵沼空思镐邑篇。","几日金舆下阊阖，鱼龙奇戏出中渊。"]},{"t":"城西二首 其一","f":"七言律诗","c":["绣鞅金羁十里尘，共传恩诏乐芳辰。","千重翠木开珍圃，百尺朱楼压宝津。","御麦初长遮雊雉，宫花未识骇游人。","自怜穷僻看山眼，来对天池禁籞春。"]},{"t":"春朝","f":"五言律诗","c":["燕语闻多日，蚕眠过几宵。","花深不辨蝶，柳暗欲迷桥。","便面金环重，障泥玉勒骄。","黄公酒垆上，谁贳阮孚貂。"]},{"t":"春霁忆洛阳","f":"七言律诗","c":["少年结客洛阳时，闲傍东风驻马蹄。","山色远饶潘岳宅，波光轻撼窈娘堤。","花繁到处红如堵，酒好寻常醉似泥。","赖有金台旧知己，应怜魂断虎牢西。"]},{"t":"独坐","f":"五言律诗","c":["雪屋生寒劲，风灯落烬频。","惊号独过雁，默坐未眠人。","世事存伤没，年华故换新。","还将寂寞意，强与冻醪亲。"]},{"t":"览杨乐道洛下诸诗","f":"七言律诗","c":["昔驱羸马望嵩云，正值嵩阳踯躅春。","千古废兴都邑地，百年劳苦宦游身。","曾耽胜事留连久，忽见新诗叹息频。","君欲买山能遂否，它时愿作社中人。"]},{"t":"览邻几重游西池兼简和叔","f":"五言律诗","c":["积雨淹连骑，新波滟广池。","喜闻重到客，更作复游诗。","逐水无留絮，飘空有断丝。","送春吾得地，一问故人期。"]},{"t":"览景仁君实议乐以诗戏呈景仁","f":"七言律诗","c":["少年议乐至颠华，作得文章载满车。","律合凤鸣犹是末，尺非天降岂无差。","劳心未免为诗刺，聚讼须防似礼家。","一曲银簧一杯酒，且于闲处避风沙。"]},{"t":"送卫真晏太丞","f":"五言律诗","c":["才名宰相子，二十取辞科。","得县古称厉，登楼朝见涡。","疲民劳赋役，静理足弦歌。","八桧仙祠在，知君秀句多。"]},{"t":"送门客李秀才赴省试","f":"七言律诗","c":["伤思易子闻前戒，务学求师是至言。","岂有车鱼延上客，欲将诗礼示诸孙。","青衿散后人千里，黄菊开时酒一尊。","壮岁雄图当自勉，未应长啸入苏门。"]},{"t":"送太素南游","f":"七言律诗","c":["戕性伤生俗所同，人间今见百年翁。","无稽不学公超雾，有待犹嗤禦寇风。","心到灵源千虑息，气随真火百骸通。","临觞不用嗟离阔，达者相忘道术中。"]},{"t":"送王奉议知吴江县","f":"五言律诗","c":["闻说吴江上，长桥百丈虹。","蚝粘能固本，人度若乘空。","明委三秋月，清来万里风。","君知此为政，名惠广无穷。"]},{"t":"送石昌言归蜀","f":"五言律诗","c":["省署聊休直，皇恩许过家。","朝廷宠儒雅，车骑有光华。","行色星垣动，褒章宰树加。","遥知蜀父老，夹道竞咨嗟。"]},{"t":"送休上人之荆门玉泉寺","f":"五言律诗","c":["怜师真达者，于世了无求。","万事沤起灭，一身云去留。","楼台金地古，风雨玉泉秋。","安得超尘网，相从物外游。"]},{"t":"送刘巽殿直官蜀","f":"七言律诗","c":["车马萧条西出门，怜君宦薄意能闲。","并游多得贤豪士，久困独无憔悴颜。","白酒园林休洛社，黄花风露见岷山。","男儿荣滞古来有，收取功名晚节间。"]},{"t":"送刘景元观察守襄阳","f":"七言律诗","c":["荆州太守驾朱轓，宝笔题诗出御前。","应厌笙歌消暇日，欲将才业效当年。","千章翠木云间寺，百丈清江雪后船。","看取古来良吏迹，苍碑突兀岘山巅。"]},{"t":"送吕寺丞","f":"五言律诗","c":["古有从军乐，人今衣綵行。","春风骐骥健，朝日凤凰鸣。","树远秦中道，花繁塞下城。","篇章闻旧俗，当为放遗声。"]},{"t":"送孙广","f":"七言律诗","c":["文才武略有家规，懿行乡闾雅见推。","乘障讵能申远业，偃戈良喜遇清时。","风吹秀菊篱边发，雨落黄榆塞下悲。","白首情怀何以慰，从军早寄仲宣诗。"]},{"t":"送孙通直","f":"七言律诗","c":["白首归来养性情，同时流辈尽彫零。","忘怀物外思游好，访旧樽前得典刑。","霜月醉留湖榭白，雪风吟度陇山青。","斯民利病君多识，好奉新书谒帝庭。"]},{"t":"送尧夫知陈州","f":"七言律诗","c":["亮节金坚气玉温，入登廊庙出藩垣。","谈经每尽先儒意，议政居多长者言。","恩恤疲羸蠲重赋，礼加耆耄屈常尊。","白头但祝公归早，南陌东陂并短辕。"]},{"t":"送朱主簿","f":"五言律诗","c":["浮舟下东溪，春寒花未遍。","共约征车行，复此华堂饯。","人事多龃龉，临分阙芳燕。","坐想竹间风，杂英纷如霰。"]},{"t":"送李宣德为县太原","f":"七言律诗","c":["昔叨符守访乡评，守节安贫得水名。","道在莫嗟为邑晚，禄微须喜及亲荣。","风吹白菊篱边别，雨落黄榆塞下行。","善抚疲羸修分职，边庭无事正休兵。"]},{"t":"送李瑜屯田通判润州","f":"七言律诗","c":["耳熟江南胜事传，闻君官去便翛然。","江流截楚红尘断，山势吞吴秀色连。","紫蟹迎霜新受钓，黄花吹酒正当前。","嗟予不得从斯乐，坐看秋风发画船。"]},{"t":"送沈学士知常州","f":"七言律诗","c":["毗陵今古号名州，况是风流得隐侯。","吴岫稍迎双隼旆，洛尘凡敝几貂裘。","预期庭下无嚚讼，还向樽前作艳讴。","去去国门谁不羡，画船烟浪入清秋。"]},{"t":"送芳公长老归法云","f":"七言律诗","c":["水际茅亭竹下庵，清谈竟夕不知厌。","伽佗善巧何能继，经藏幽深亦许觇。","额内珠存虽本有，眼中金落复谁拈。","圆通到日如相问，为道春来米价添。"]},{"t":"送辛十七作尉盐城","f":"七言律诗","c":["少年嘉誉冠诸生，白首青衫仅有成。","千里辛勤州县职，一觞凄惨里闾情。","家临颍水花催发，柳绕长堤絮扑行。","寸禄折腰何必去，道存心在即渊明。"]},{"t":"送河秘校鬲主簿良原","f":"五言律诗","c":["平时太学客，文藻士林传。","憔悴尚一邑，声名空十年。","风烟长夏始，关塞浊泾前。","莫作归来叹，将军好荐贤。"]},{"t":"送思上人南归","f":"五言律诗","c":["尘埃不可久，归卧故山秋。","荣利非其好，风骚得所求。","晨征随社燕，夜宿近江鸥。","闻子禅林胜，它年一系舟。"]},{"t":"送洵阳王令之官","f":"五言律诗","c":["离马嘶高树，郊原夏景深。","还持长者政，往慰远人心。","种黍侔千户，张鱼盛百金。","江山永嘉咏，时寄草堂吟。"]},{"t":"送晁怀州学士 其二","f":"七言律诗","c":["退传清门世有才，使君嘉誉蔼中台。","未甘文墨工彫篆，聊取圭符试剸裁。","垄上劝耕春晼晚，山前闻笛月徘徊。","明朝建隼临长道，回首仙庐拂斗魁。"]},{"t":"送晁怀州学士 其一","f":"五言律诗","c":["儒馆雠书旧，侯藩请节行。","山川犹古气，铙吹自春声。","问俗怜彫瘵，颁条赖简平。","从来寇河内，谁复继声名。"]},{"t":"送海印住香严颂","f":"七言律诗","c":["枕石漱流尘外趣，随缘应物谷中声。","更无宾主能酬对，自有儿孙可使令。","万古清风归法语，一轮明月伴经行。","鳌山成道知何日，时伫雷音警妄情。"]},{"t":"送高寺丞宰岐上","f":"五言律诗","c":["墨绶垂腰底，怜君尚一同。","人豪固秦俗，地古自豳风。","春色鸣弦外，山光隐几中。","定应传善政，不日到关东。"]},{"t":"送崔朝请通判徐州","f":"七言律诗","c":["与君仍世接游从，造次相敦德义中。","善继家声名父子，不追时好古人风。","流光岂受长绳系，妙道才容一线通。","待得铃斋民讼简，更将此理问庞公。"]},{"t":"送曹大夫归家","f":"七言律诗","c":["飞尽杨花见绿阴，飘然轻盖返家林。","野堂泥落归双燕，纹簟风清戏一禽。","秀麦柔桑皆有望，高轩华衮久无心。","知君自得闲中乐，早寄新诗别后吟。"]},{"t":"送曾通直入京","f":"七言律诗","c":["敏学高文俊茂身，少年今见鲁公孙。","明心早得无生意，清耳常闻有味言。","绿鸭陂中春纵棹，芰荷池上雨移樽。","临分有赠非他物，声利精忘道始存。"]},{"t":"送戴处士还卢州","f":"五言律诗","c":["早识浮生妄，欣陪达士游。","观心非本有，于法尚何求。","煮茗林间寺，题诗湖上舟。","还嗟别后夜，风雪拥貂裘。"]},{"t":"重阳对雨招介甫","f":"五言律诗","c":["积潦行车绝，高舂闭户眠。","萧条黄叶下，冷落菊花前。","废卷怜佳节，衔杯想少年。","君来慰愁坐，厩马疾于烟。"]},{"t":"宴逍遥堂","f":"七言律诗","c":["朱颜绿鬓尽才良，永日逍遥宴此堂。","乐事已先桃艳动，欢情仍共雪花狂。","梦中身世知虚实，醉里光阴任短长。","荣辱誉非那复问，无何有处是吾乡。"]},{"t":"宴湖上呈稚卿","f":"七言律诗","c":["熠熠萤光草际流，及时高宴落霞洲。","繁弦急管宜清月，细蕊浓芳艳晚秋。","飞鹭欲来迎画舫，跳鳞如喜脱金钩。","知公加数为醇酿，应许闲官烂漫游。"]},{"t":"展江亭看海棠遇风","f":"七言律诗","c":["少陵昔日富辞华，愁见飘零万点花。","写物高才从古少，伤春情绪此时加。","恨无巧语谗风伯，直欲狂图系雨车。","莫怪晚来觞屡釂，白头判得醉流霞。"]},{"t":"晏相公湖上泛舟赋","f":"五言律诗","c":["小雪未成寒，平湖好放船。","水光宜落日，人意喜晴天。","云薄翠微外，禽归莽苍前。","上公宽礼数，清醉亦陶然。"]},{"t":"桃花菊 其二","f":"七言律诗","c":["霜女星娥不俗情，施朱点出浅深更。","平泉记上遗嘉品，本草经中注别名。","气得清凉开更早，色沾寒露久逾明。","今朝樽酒来篱下，不为重阳为尔倾。"]},{"t":"桃花菊 其一","f":"七言律诗","c":["谁测天工造化情，巧将红粉傅金英。","武陵溪上分佳色，陶令篱边得异名。","不使秋光全冷淡，却教阳艳再鲜明。","瓮头消息香醪熟，何必黄花便可倾。"]},{"t":"浴普静同江二李叔中道赋","f":"七言律诗","c":["夜来飞雨濯残芳，绿遍童童佛树行。","把酒可劳悲暮节，振衣还自喜微凉。","清帘不下轻飏燕，别院时来暗霭香。","自是嵩阳欲归客，为公聊尽次公狂。"]},{"t":"积雨成雪呈子华","f":"七言律诗","c":["寒威暗袭春和去，坐拥重裘仅自温。","对景直须忘适适，随机聊耳不言言。","兴来一笑非缘酒，道本无忧岂在萱。","欲与何人论此意，竹风松雪满西轩。"]},{"t":"请微之饮","f":"七言律诗","c":["句解章通字字安，书成进御九重观。","更加亲切从新诏，却得高闲是旧官。","禁阁不忧连夜直，好山应许老年看。","菊香酒熟身无事，且尽樽前一笑欢。"]},{"t":"载酒过景仁东园","f":"五言律诗","c":["地胜依危堞，城高若半峰。","衔觞惊岁序，候雪仰云容。","不假猫滋竹，须防犬败松。","顾惭文俗吏，游步蹑仙踪。"]},{"t":"陪宁极游南溪夜还山墅","f":"五言律诗","c":["南溪晚酌罢，归路笑言同。","家在碧山下，人行清露中。","鹊飞斜映月，虫响暗移丛。","下马儿童喜，谁知为德公。"]},{"t":"陪范尧夫之北第饮彝叟新堂","f":"七言律诗","c":["光禄新堂指顾成，非奢非俭称高情。","春风为我开朱户，晴日从公驻彩旌。","庭下早梅惊喜客，门前垂柳欲啼莺。","追攀梦境终何得，识取家乡旧路行。"]},{"t":"陪景仁赴况之湖上燕集遇雨","f":"七言律诗","c":["炎蒸消尽作浓阴，湖上兹游喜重寻。","急雨洗开荷芰色，清风借出管弦音。","凉生顿觉絺衣薄，欢至宁论酒盏深。","善谑清谈都有适，过从所得在知心。"]},{"t":"偶成寄曼叔","f":"七言律诗","c":["红芳落尽鸭陂边，白首伤春倍惨然。","自愧闲官消永日，独吟佳句想当年。","早休诸吏眠斋馆，时引双童上舞筵。","闻说年来亦归兴，琳宫仙籍旧无员。"]},{"t":"宿西京府署晚游东池","f":"五言律诗","c":["牢落悲春事，萧条作晚游。","清光溢平沼，凉思近高楼。","碧树森将合，朱栏渺若浮。","公来慰羁寓，华月许移舟。"]},{"t":"寄庆州德孺待制","f":"七言律诗","c":["常爱公家好弟兄，忠言直道友于情。","心期光禄朝中驾，目断将军塞上旌。","埤堄高风回过雁，琵琶宵寂语流莺。","共欣出处非它辙，报国诚身各自行。"]},{"t":"寄李公达","f":"七言律诗","c":["早为书殿同游客，尝贰侯藩共理臣。","流景又逢黄菊节，狂欢犹记紫荆春。","浮生几度花前饮，访旧多为柏下人。","闻说真乘得深趣，暂抛珍御出埃尘。"]},{"t":"寄郑州曾资政","f":"七言律诗","c":["鲁公旌旆镇兹邦，曾奉樽罍佚老堂。","彩服过庭闻政术，缁衣传世见诗章。","斗龙门外波光绿，集凤台边柳色黄。","应感归欤形丽唱，故园春草满池塘。"]},{"t":"寄侯官知县吕宣德","f":"七言律诗","c":["鸭子陂边昔并游，别来频见藕花秋。","十年已惯身萧散，百里空嗟手滞留。","道在岂常忘塞马，机閒真可伴沙鸥。","平时几案应多暇，还有妖歌近耳不。"]},{"t":"寄秦川马从事","f":"七言律诗","c":["往岁游西谒季长，陇云秦树胜风光。","分题红叶蛮笺腻，对举流霞綵袖香。","宴洽翠娥连象榻，夜寒娇凤泥银黄。","未知早晚重携手，惆怅而今鬓已苍。"]},{"t":"寄致仕李洵大夫","f":"七言律诗","c":["买得田园便退身，世间今作自由人。","不争路上风波静，无相光中日月新。","红叶委阶非异物，碧峰当户见全真。","知君未放狂心歇，兴在陶公漉酒巾。"]},{"t":"寄谢师直","f":"七言律诗","c":["十年三退卧吾庐，解组归来始定居。","数亩家园荒杞菊，一池秋水拂龟鱼。","临花对月难忘酒，咏古怀贤不废书。","更欲两忘真俗累，逍遥常御白牛车。"]},{"t":"寄微之通议","f":"七言律诗","c":["十五年来自在身，晴天万里见孤云。","闲中密迹常同俗，老去忠言尚爱君。","一坐精神归素发，两行歌舞避红裙。","早梅时节华灯夜，日伫车公共醉醺。"]},{"t":"寄题苏子美沧浪亭","f":"七言律诗","c":["闻君买宅洞庭傍，白水千畦插稻秧。","生事已能支伏腊，岁华全得属文章。","骞飞灵凤知何暮，蟠蛰蛟龙未可量。","莫以江山足清尚，便收才业傲虞唐。"]},{"t":"寄题周著作江山县溪亭","f":"七言律诗","c":["结亭遐僻古江山，胜绝终为好事传。","溪泛夜声来枕上，峰回午影过樽前。","禽鱼旧识应相乐，花木亲栽益自怜。","我抱沧洲未归恨，羡君生计有林泉。"]},{"t":"寄题曹大夫栖真堂","f":"七言律诗","c":["闻君初欲挂冠缨，便构兹堂不日成。","桐桧茂阴归后得，烟霞高兴坐中生。","禅心皎月通宵静，诗思寒泉彻底清。","十五年来饱闲散，纷纷人世自浮荣。"]},{"t":"晚过邻几官舍三首 其三","f":"五言律诗","c":["萧洒君官舍，从来可数来。","养莲疏浊水，薙草出荒台。","芡散初成籍，蒲长欲映杯。","吾知蒋生径，不为俗人开。"]},{"t":"晚过邻几官舍三首 其二","f":"五言律诗","c":["车马东桥绝，凉风满夕轩。","水声通沁苑，树色入夷门。","每接渊明咏，常怀仲理言。","沧洲如可约，杯酒会重论。"]},{"t":"晚过邻几官舍三首 其一","f":"五言律诗","c":["炎日来休骑，红尘喜放船。","波平凉洗马，树净晚吟蝉。","风至披襟后，云消倚拖前。","潭心见华月，归意一留连。"]},{"t":"晚过象之葆光亭戏呈一首","f":"五言律诗","c":["萧洒崔家宅，重门一径通。","竹烟虚晚碧，花雨重秋红。","傲睨怜苔石，徘徊俯桂丛。","自期新月色，不为主人翁。"]},{"t":"晚春","f":"七言律诗","c":["春晖东去月如弦，却拂凝埃敞北轩。","几曲云屏空白昼，一帘花雨自黄昏。","庭芜碧合阴虫息，窗树红稀斗雀喧。","细忆旧欢都入梦，习家池上子山园。"]},{"t":"曹通直以颜鲁公墨迹题辞乞诗刊石","f":"七言律诗","c":["临池馀事得忠臣，白刃林中不动身。","见义舍生安为己，怀谖保位独何人。","英名在世长如日，遗像于今凛若神。","一览精诚方自失，羞将累句刻苍珉。"]},{"t":"清明北园泛池舟中作","f":"五言律诗","c":["路绕高林尽，舟篷出近湾。","鸟啼青竹影，人对绿波间。","野色平当坐，春愁巧作颜。","已知湖榭近，飞絮落班班。"]},{"t":"清涟矶独坐","f":"七言律诗","c":["绿筱清涟得钓矶，制名翻与实相违。","沉钩不忍潜鱼乱，回棹常侵宿鸟飞。","林霭散馀知月上，水风清极怯秋归。","兴来诗就觞来尽，不信人间有是非。"]},{"t":"累日不到中园晚步闲咏","f":"七言律诗","c":["南陌西陂趁物华，归来扶杖重咨嗟。","绿罗浅淡新开叶，红玉玲珑半谢花。","泉溜拍池初跳鲤，柳枝含雨不胜鸦。","啼禽亦有伤春恨，百种鸣声到落霞。"]},{"t":"谒汉高帝庙","f":"五言律诗","c":["魂魄应游沛，空嗟庙貌残。","苍碑火剥裂，画壁雨阑干。","帐幕虚风肃，松槐白日寒。","升堂欲进拜，犹怯戴儒冠。"]},{"t":"谒象之同诸君步之东禅院","f":"七言律诗","c":["二年憔悴走京尘，匹马归来访四邻。","足滑旧谙城下径，眼明重见里中人。","青蔬不没荒畦雪，翠柏常留野殿春。","风物自如人事改，夕阳哀泪落衣巾。"]},{"t":"象之以山药见赠","f":"五言律诗","c":["龙山有游客，赠药满筠笼。","叶渍沙泉碧，苗分石窦红。","斸应侵晓露，来喜及春风。","却笑丹砂远，卒勤勾漏翁。"]},{"t":"象之席上赋得寒字","f":"五言律诗","c":["爱子林亭胜，高秋驻马鞍。","梨红先著露，竹碧自生寒。","惨戚伤多事，淹留强一欢。","所嗟怯杯酌，不得倒吾冠。"]},{"t":"野步","f":"五言律诗","c":["目倦风尘观，身疲鞍马行。","春沙迎步润，山雪照怀清。","冰水初消色，林鸦欲乳声。","物华多感触，一动故园情。"]},{"t":"雪中同邻几出游","f":"七言律诗","c":["絮糅琼霏浩满空，平明骑马入春风。","九重城阙寒光外，百万人家喜气中。","不学闭门徒自洁，且欣携酒与君同。","柳梢花甲从今始，便好寻芳下苑东。"]},{"t":"黄葵花 其二","f":"七言律诗","c":["春花夏蕊已飘零，秀出秋芳一朵倾。","禀赋定应全得土，遮围须合尽彫琼。","鹄衣照水匀颜色，仙袂无尘莫壮名。","应笑菊花妍意少，篱边冷落伴渊明。"]},{"t":"黄葵花 其一","f":"七言律诗","c":["池上朝来玉露零，檀心先向日边倾。","侧金巧样新成盏，蒸栗温姿始号琼。","芍药未应推艳品，牡丹须合避姚名。","秋花碎琐谁能数，醉眼逢君亦自明。"]},{"t":"寒食出郊","f":"词","c":["都门气象雨馀佳，压尽风尘见草芽。","日薄风和近郊路，朱红粉白远林花。","堤开独去媻珊女，柳下相逢轻?车。","丝鬓未催樽酒在，不须辛苦问年华。"]},{"t":"寓展江亭谢尧夫寄酒及花","f":"七言律诗","c":["措枉我先违陛石，均劳公亦下堤沙。","已欣晚岁逢良友，更喜高秋见好花。","旨酒芳新来似水，危亭清绝至如家。","三杯举白歌相和，忘却风前两鬓华。"]},{"t":"普明亭赋","f":"五言律诗","c":["杨柳飞花尽，樱桃结子成。","蹊阴空净绿，野艳有孤明。","访古重来地，伤春独望情。","幽禽亦何恨，百种向人鸣。"]},{"t":"景仁招况之闻用歌舞望门而反作此戏之","f":"七言律诗","c":["一夜严风结素波，盍簪宁避晓寒多。","范滂揽辔方清俗，墨子回车岂恶歌。","云外雁寒惊岁晚，林间鸦语弄春和。","知君不久承宽诏，始奈红裙绿酒何。"]},{"t":"棣华堂","f":"七言律诗","c":["锦衣赍钺耀当年，心在王家迹在边。","论议每先诸将勇，规模仍袭仲兄贤。","一朝华栋飞翚动，四坐清觞插羽传。","欲赋酬章惭懦武，白头终日诵尘编。"]},{"t":"游北园赋","f":"五言律诗","c":["多病伤春客，经时独掩扉。","偶随游骑出，已见落花飞。","芳草微迎履，香风细弄衣。","扁舟可载酒，便拟拍浮归。"]},{"t":"游龙门归","f":"五言律诗","c":["洛浦残芳尽，来寻关塞春。","青林横石阁，翠壁涌金人。","涧草薰衣晚，松风落面新。","愁驱向城骑，还踏九衢尘。"]},{"t":"游龙兴寺","f":"五言律诗","c":["空庭落叶赤，联步得幽寻。","藓剥残碑字，尘昏古象金。","菊烟凄晚秀，松日淡秋阴。","南陌风埃满，禅关只自深。"]},{"t":"游象之葆光亭因以寄之","f":"五言律诗","c":["东亭不到久，双桂长新梢。","窗静虫收网，檐低燕护巢。","晚花红自照，繁笋翠相交。","清景成虚委，知君叹系匏。"]},{"t":"湖上饮","f":"七言律诗","c":["高秋水木变清光，荷叶乾枯䆉稏黄。","习静久安融子懒，乘欢聊发次公狂。","未甘浊酒欺人老，深喜寒花入坐香。","更谢林端新月色，留连归舫尽三觞。"]},{"t":"登城楼呈子华","f":"七言律诗","c":["麦苗黄熟稻苗青，饷妇耘夫笑语声。","楼上清风帘箔静，田间白水鹭鸥轻。","展亲会集从容乐，娱老讴吟放旷情。","羽孽渐消民食足，更无馀事计亏成。"]},{"t":"登湖光亭","f":"七言律诗","c":["雪尽尘消径露沙，公家池馆似山家。","翠痕满地初生草，红气通林未放花。","匝岸平波清照雁，压城危榭斗回鸦。","自惭白首犹圭组，此地年年赏物华。"]},{"t":"登楼书事","f":"五言律诗","c":["病起思遐眺，兹楼寓一欢。","烟芜连雨脚，秋稼入云端。","惊鹭衔鱼起，饥鸦啄果残。","凭谁图好景，画手世无宽。"]},{"t":"答外孙杨承务","f":"七言律诗","c":["享厚功微每愧颜，辞荣聊企汉疏贤。","居民未睹黄公化，过客空疑绛老年。","适用每惭龟手伎，全生真赖马蹄篇。","从今风月知无负，鸭子陂中有钓船。"]},{"t":"答张念五","f":"七言律诗","c":["浮云名宦祗劳人，解组归来径杜门。","继世命官联六傅，传家与子及诸孙。","圣贤相对书千帙，闾里交欢酒一樽。","荷芰满湖秋气早，待君方驾践诚言。"]},{"t":"答张念五见寄","f":"七言律诗","c":["林泉萧洒逸平生，不识人间宠辱惊。","美质自全荆璞贵，嘉名长共洛波清。","身虽贫约非原病，诗为穷愁似孟精。","命驾高踪久无继，一时风义独归程。"]},{"t":"答李正议见贻","f":"七言律诗","c":["如公举世几何人，八十年龄自在身。","处俗不绕诸有相，持心肯受一微尘。","逢僧便出衣中宝，待士多陈席上珍。","火宅未须生厌苦，不离当处岂非神。"]},{"t":"答杜孝锡观乡老堂","f":"七言律诗","c":["华发苍然亮直身，谁将綵笔欲传神。","论功顾我常流汗，好事烦君为拂尘。","汉阁寂寥班氏赞，伊川潇洒白公真。","怀贤却坐酬嘉句，空觉中郎善愧人。"]},{"t":"答和叔见寄","f":"五言律诗","c":["清霜落堤水，知子戒归舟。","蹭蹬蛟龙雨，翻飞鸿鹄秋。","文章真自乐，得丧岂吾忧。","南国江山好，裁诗寄少游。"]},{"t":"答临淄公见招","f":"七言律诗","c":["帝思元老付关西，公受兵符与命圭。","应识疲羸须镇抚，便期愚散豫招携。","汉家宫殿看龙首，秦地山川入马蹄。","自愧不才多病者，空哦嘉句滞幽栖。"]},{"t":"答赵县丞","f":"七言律诗","c":["止足常佳汉二臣，早思幽退谢朝绅。","奉藩终乏三年最，学道才知一日真。","目病懒将书卷展，心闲得近酒杯频。","朝吟夕啸无厌斁，正赖贤宾与德邻。"]},{"t":"答唐州郑郎","f":"七言律诗","c":["先帝宫藩昔曳裾，便将狂直许倾舒。","制分内外常更掌，省列东西亦预除。","敢以功名为己任，自知谋议与时疏。","归来粗足生生计，幸免乡邻厌乞诸。"]},{"t":"答寄广信六弟","f":"七言律诗","c":["才见高帆落归艑，又携轻剑逐戎麾。","步兵厨里仍多酒，王粲军中不废诗。","绝塞风烟通夕静，近关榆柳识春迟。","花时不得同嬉赏，肠断东风把一卮。"]},{"t":"答微之","f":"五言律诗","c":["南圃携樽数，西陂纵棹同。","除书褒晚岁，归驭觞西风。","节物萧条后，交游寂寞中。","何时还一笑，池上舞惊鸿。"]},{"t":"筵上遇雪赠人","f":"七言律诗","c":["前贤遇雪方乘兴，何况雪飞欢兴时。","自古难并惟美景，人生不饮是痴儿。","颠狂故态无先舞，淡薄幽怀子独诗。","安得琼花更飘洒，常令此物及蚩蚩。"]},{"t":"谢尧夫寄新酒","f":"七言律诗","c":["故人一别两重阳，每欲从之道路长。","有客忽传龙坂至，开樽如对马军尝。","定将琼液都为色，疑有金英借密香。","却笑当年彭泽令，篱边终日叹空觞。"]},{"t":"谢李公达惠诗再答","f":"七言律诗","c":["功名无得得闲身，位列东朝愧汉臣。","空性屡捞潭底月，浮名那记禁中春。","知音罕遇忘言士，绝学常思过量人。","莫取无心心外道，此心生处即为尘。"]},{"t":"谢到水仙二本","f":"七言律诗","c":["黄中秀外干虚通，乃喜佳名近帝聪。","密叶暗传深夜露，残花犹及早春风。","拒霜已失芙蓉艳，出水难留菡萏红。","多谢使君怜寂寞，许教绰约伴仙翁。"]},{"t":"谢厚卿载酒见过","f":"七言律诗","c":["黄花池馆雨馀清，载酒亲迂太守旌。","交契早陪廊庙语，宾欢曲尽里闾情。","尊前白发时间乐，烛下红妆分外明。","今日始谙闲气味，十年枉却叹劳生。"]},{"t":"谢微之送鸭脚","f":"五言律诗","c":["拔尔蒿莱际，微根仅自支。","劳心勤一溉，拭目待三移。","秾李惭同列，芳橙合并枝。","绛囊如有惠，莫忘赠君时。"]},{"t":"赏梅花有怀曼叔","f":"七言律诗","c":["逍遥堂下去年梅，还向春来撩乱开。","白发每思同泛客，红芳应怪久停杯。","鸭头新浪暌游泛，鹭羽遗民寄剸裁。","闻说铃斋多暇豫，何时度曲逐风来。"]},{"t":"颍桥会曼叔坐中写呈","f":"五言律诗","c":["朔雪清初霁，风生翠柏阴。","星辰寒殿近，灯火夜堂深。","坐爱温炉密，欢从浊酒斟。","何当老吾里，杖屦日相寻。"]},{"t":"照邻从予假韦苏州集因以诗致之","f":"五言律诗","c":["都官郎署老，平淡古人如。","更觅苏州集，长依释子庐。","室中无净几，门外自华舆。","为问萧疏意，如何善福居。"]},{"t":"酬盈祖中散","f":"七言律诗","c":["勇脱尘冠尚壮年，高斋图史日萧然。","不教歌舞家规在，善作文章世学传。","道旧每思倾浊酒，仰高徒觉愧华颠。","相君昔展西陂尽，好约春风放画船。"]},{"t":"暮春游卞氏园","f":"五言律诗","c":["路出清阴下，残花著马蹄。","过城春水静，度墅野桥低。","池废青蘋合，林深绿笋齐。","流莺知我恨，落日再三啼。"]},{"t":"题卞大夫翠阴亭","f":"七言律诗","c":["新得亭名号翠阴，轩窗环合尽青林。","定知野客先回顾，何处山禽自好音。","池面有莲风气馥，城根多竹月华深。","明年便作归来计，应许携樽与抱琴。"]},{"t":"题余山人壁","f":"五言律诗","c":["一室闭香林，萧然物外心。","棋声敲月重，屐齿印苔深。","竹径茶烟细，山园锻树阴。","会当逃世网，尘事缔朋簪。"]},{"t":"赠卞大夫","f":"七言律诗","c":["鍊得朱颜老不衰，归来三径有馀资。","青林蔽日深开第，翠竹生寒密映池。","明月泛觞频度曲，华灯照序未收棋。","白头默坐公毋怪，独爱泉声入夜时。"]},{"t":"赠香严敷老慧照上人","f":"七言律诗","c":["胜地名蓝代有人，惟公传得国师真。","苍崖翠壁风流在，杰阁隆楼指顾新。","半死半生排俗世，一颦一笑是家珍。","欲知闻法诸天喜，庭下于今有瑞筠。"]},{"t":"襄城道中怀曼叔","f":"五言律诗","c":["吾交作尉地，南望一淹留。","岁月催人老，山川记子游。","向城非昔勇，遇物更春愁。","独喜高阳近，岚光逼马头。"]},{"t":"襄柑分惠景仁以诗将之","f":"七言律诗","c":["荆州解绂十经春，回梦青林绕汉滨。","霜气轻寒催柑实，渚波馀润作甘津。","僧园采掇宁论数，客路奔驰竟占新。","雪意垂收高会缺，分金聊助席间珍。"]},{"t":"同辛杨游李氏园随意各赋古律诗一首","f":"五言古诗","c":["腊近云容变，阳生日景添。","偶然回晚辔，相与坐晴檐。","水绿冰微泮，沙明雪尚沾。","弄襟风力薄，著履土膏粘。","惊鸟不成下，寒鱼犹在潜。","翠深荒岸竹，黄折败池蒹。","碍径藤梢曲，钩衣棘刺铦。","辞锋怜子淬，閒癖讵予砭。","自以清谈胜，宁非乐事兼。","春芳有近信，频此醉厌厌。"]},{"t":"依韵和冲卿槐花","f":"五言古诗","c":["翠葆连阴直，黄金布蕊齐。","流尘一开眼，急节重含悽。","蝶冷相携去，蝉清无数嘶。","翻风随御水，带雨落秋泥。","自喜凋零后，何嫌采掇稽。","朝緌映晨入，游袂拂宵携。","惨淡林烟早，轻明楼日西。","临溪如有此，当似武陵迷。"]},{"t":"依韵和贡父见寄","f":"五言古诗","c":["早接英豪论，常多伯仲贤。","风尘一会合，岁月几徂迁。","禀性成樗散，干时类凿圆。","论心谁合者，握手子欢然。","经训开前古，谈辞屈老先。","春游同烂漫，醉乐屡回旋。","乐事嗟难久，离襟怅独偏。","驱车清汝曲，佐幕紫嵩前。","官兴惟高咏，人生得晏眠。","丹铅涂旧史，杖屦接幽禅。","叹息春期失，淹留夕梦牵。","非因传丽唱，何以慰劳悁。"]},{"t":"和公美以诸家会集所赋诗","f":"五言古诗","c":["道在何非乐，官闲不近权。","过从只闾里，真率易盘筵。","捉麈躬千圣，衔杯慕八仙。","清欢垂老得，佳句即时传。","玉醴初醇日，琼花欲坠天。","谁能于此际，华发问流年。"]},{"t":"和宋中散寄题景仁新池","f":"五言古诗","c":["北顾兴王府，东瞻象日畿。","稻塍常借润，黍尺讵能晞。","鹭浴菖芽短，鱼跳荇菜肥。","乐亭初置酒，试舞旋裁衣。","逸冀相从老，冥鸿自在飞。","月游刳小艇，雨钓筑新矶。","栽插期春事，追游惜晚晖。","气同均我尔，道胜绝从违。","安燕兴棠棣，艰勤陋采薇。","如何宋中散，留滞不成归。"]},{"t":"和象之同孔宁极游石桥且简宁极","f":"五言古诗","c":["春风杖藜客，同到石桥边。","引袖披云木，携樽俯涧泉。","岩花聊采摘，野器不雕镌。","俯仰元和内，熙恬太古前。","草心柔可绾，蒲叶密于编。","涧麀来窥坐，沙鸥不改眠。","濛濛桃李雨，幂幂薜萝烟。","舞类雩祠日，吟非楚泽年。","鱼跳闻急管，鸟语似幺弦。","紫翠羞薇蕨，清香袭蕙荃。","乱流时揭厉，微径巧萦穿。","德义心诚服，山林性所便。","敢令然诺负，直以事为牵。","圯下履终跪，溱边裳且褰。","春醪可益酿，况有帛戋戋。"]},{"t":"和微之","f":"五言古诗","c":["早接忠贤论，常钦古学风。","何期华发后，更得绿樽同。","远水秋光外，高亭夕照中。","芡盘凋晚翠，菊艳夺春红。","歌放聊娱老，谈精本代工。","欢馀笑张翰，迢递想江东。"]},{"t":"和微之尧夫作会","f":"五言古诗","c":["燕豆何频设，归鞍夜屡阑。","敢言挥麈倦，惟怯釂觞难。","就暖歌筵密，凭高绘境宽。","未甘闲处卧，犹学少时欢。","浮蚁凌山玉，飞花掩袖纨。","幸同诸老醉，击壤颂安安。"]},{"t":"奉同邻几对","f":"五言古诗","c":["时律迎阳近，天云带雪低。","欲飞含气象，忽散失端倪。","绛阙明先曙，清衢冻不泥。","休祥占岁序，佳气动烝黎。","矫若翔廱鹭，纷疑剥楚圭。","晨昏檐影眩，壬丙辨方迷。","贺瑞彤墀集，凌寒玉仗齐。","御筵开省户，赐醴走宫奚。","屋角悬珠网，林梢挂素霓。","山号悲虎兕，渊伏怯龟蠵。","哀响求群雁，喧啾得食鸡。","饥鹰无近击，狂兔有新刲。","感往悲时物，怀幽梦故栖。","温炉期夜拥，杰阁想晨跻。","验古闻牛目，投閒读马蹄。","吾交情不薄，今日手同携。","酒拨新醅酌，诗看本字题。","优游无不可，何必剡中溪。"]},{"t":"寄题刘仲更泽州家园","f":"五言古诗","c":["闻君有佳尚，买胜不论钱。","径凿苍林藓，亭开翠壁烟。","徙花穷洛谱，得石记唐年。","数卷书盈万，言章木以千。","晨昏板舆往，社腊燕觞传。","予亦耽幽事，西风一慨然。"]},{"t":"游曲水园和景仁","f":"五言古诗","c":["楼峻城千堞，堤长竹万竿。","草芽生戢戢，花蕊落漫漫。","走笔狂吟放，扶筇醉步跚。","屡回宜舞袖，甘著堕游冠。","野老来窥坐，沙禽不避观。","两行桃艳暖，一道柳阴寒。","纵棹非寻戴，掀车免效栾。","官曹嗟倥偬，农事闵艰难。","急景三春好，浮生几日欢。","康强直行乐，此兴不应阑。"]},{"t":"答杨之美春日书怀依韵","f":"五言古诗","c":["久宦怜官薄，端居惜岁芳。","世情徒枳棘，吾操自松篁。","铁擿敷经暇，檀槽度曲长。","浮沈归浊酒，感激见新章。","守道言何固，安时志不忘。","惭无推挽者，祝子寿而康。"]},{"t":"九日北园思临涡之游","f":"五言古诗","c":["吾生岂鹰鹯，胡为见羁绁。","题鞭古胜地，落帽秋佳节。","一为尘事牵，坐叹高会缺。","天兼水澄淡，树与堤曲折。","萸房露应重，菊艳晨可撷。","嘉景成想像，清樽废提挈。","阴风吹北园，众槁声切切。","把酒望霜空，冥鸿溯辽碣。"]},{"t":"九日客散西轩","f":"五言律诗","c":["穷阎车马散，默坐吊孤影。","烟生竹町深，月出茅庐静。","道存轻外物，心寂丧前境。","即此之吾生，安知慕箕颍。"]},{"t":"九日高会有怀宁极","f":"五言律诗","c":["亲宾过我舍，置酒乐嘉节。","不见箕山人，坐令欢意歇。","霜风吹嘉菊，撩乱篱下发。","欲寄一枝芳，云深去鸿灭。"]},{"t":"九月十日西湖席上得乐字","f":"五言古诗","c":["秋云淡不飞，霜水清欲落。","维舟坐近浦，悲风满衡薄。","良游未为晚，佳节止在昨。","湛湛觞醪醇，娜娜菊枝弱。","天时倏代去，所恃有行乐。","何能学次公，忉咄谢多酌。"]},{"t":"入都席上答曼叔见送","f":"五言律诗","c":["少乏四方志，所怀在林丘。","尘埃岂我事，义往不得留。","进酒长亭上，离马俨行辀。","临分子无惨，且复相从游。"]},{"t":"又灵沟道中","f":"五言古诗","c":["春风来无迹，泱莽天地和。","群生乐时阳，众鸟舞且歌。","嗟尔道旁叟，寒馁独见罗。","短席不自蔽，皮骨撑枯柯。","呼童问所以，口噤不能哦。","所见且如此，况馀生齿多。","吾闻古三代，仁术固匪他。","老幼孤洎疾，饩养平不颇。","斯道久寂寞，吾悲其奈何。"]},{"t":"又和杨之美家琵琶妓","f":"词","c":["杨君好古天下无，自信独与常人殊。","勤身所营世或弃，反眼不顾我以趋。","彼其察物类有道，能取精妙遗其粗。","官卑俸薄不自给，买童教乐收图书。","客来呼童理弦索，满面狼籍施铅朱。","樽前一听啄木奏，能使四坐改观为欢娱。","有时陈书出众画，罗列卷轴长短俱。","破缣坏纸抹漆黑，笔墨仅辨丝毫馀。","补装断绽搜尺寸，分别品目穷锱铢。","以兹为玩不知老，自适其适诚吾徒。","岂无高门华屋贮妖丽，中挂瑶圃昆崙图。","青红采错乱人目，珠玉磊落荧其躯。","苟非绝艺与奇迹，杨君视之皆蔑如，杨君好古天下无。"]},{"t":"又和春游","f":"七言古诗","c":["青春之来漫无踪，但见佳气流融融，天地百物和风中。","轻雷殷出草根绿，丹霞散作枝上红。","鸣蜂喧空蝶扑地，似与游人报芳意。","东城南陌交轮辔，朝尘暮雨才几日，已见残花落如积。","人生劳苦诚可悲，奔走事役无休时，天意以眷使其熙。","会须举酒烂漫醉，当与不取庸非痴。"]},{"t":"又和原甫省壁画蟹","f":"五言律诗","c":["天工不为神，众物自我具。","钱侯扫墨笔，敖跪生指顾。","如依石穴出，尚想秋江度。","真伪本相夺，安知彼非误。"]},{"t":"又赋京师初食车螯","f":"词","c":["翰林置酒冬之严，庶羞罗列穷脆甘。","有馈奇味众莫觇，久秘不出须宾酣。","红炉炽炭发其钳，金钟一引连四三。","满坐诧美欢笑谈，肯复重顾蛏与蚶。","京都贵人粱肉厌，远致异物无微纤。","骈珍错怪百类兼，何久遗此不得参。","乃知物用有远。"]},{"t":"三月十三日游卞氏园","f":"五言律诗","c":["窄径下深竹，有堤平若席。","开樽荫密树，正见溪水碧。","游鱼出柳根，翕忽无定迹。","酒行不须遽，月色林上白。"]},{"t":"上巳","f":"七言律诗","c":["栏干浮波走长桥，琉璃光中虹动摇。","浪头画舸百龙首，鼓声叠叠来塞剽。","我欣禊事得壮观，眼底不顾花飞飘。","劝君酒到莫浪免，一春佳节惟今朝。"]},{"t":"下横岭望宁极舍","f":"五言律诗","c":["驱车下峻坂，西走龙阳道。","青烟人几家，绿野山四抱。","鸟啼春意閒，林变夏阴早。","应近先生庐，民风亦淳好。"]},{"t":"与江梅景德夜归","f":"五言律诗","c":["吾交陈与谢，屡结东城游。","春宵灯火繁，跃马此道周。","怀人邈何远，念岁忽以遒。","况自抱私感，归来清泪流。"]},{"t":"与张仲巽游善护院","f":"五言古诗","c":["高城面脩涂，呀豁若箕口。","其右释子庐，苍柏荫庭牖。","翘翘幕中彦，疏怀脱喧垢。","结辔游禅扃，弹弦乐嘉友。","华榱翳广坐，仰视眩丹黝。","朱光羞晨樱，绀玉折春藕。","初筵颇清简，中醉稍喧糅。","歌休众管作，令发洪钟叩。","横浮或见违，义蕴□□□。","酒酣隘常见，大观资远取。","上跻危磴盘，却立土崖斗。","长川自西来，逶迤带坰薮。","绿树下成列，猎猎清风走。","侧身宇宙间，群动何纷纠。","自顾龌龊极，天地一罂缶。","安得修灵根，超然出诸有。"]},{"t":"久旱喜雨","f":"五言古诗","c":["炎风驾京尘，久旱氛祲恶。","羲和鞭日车，光焰赫飞跃。","群生困熬暴，嘉谷坐焦灼。","高堂袒裼卧，汗下如鞭索。","安知于此时，乃见嘉树落。","狂飘随烟云，急洒动林薄。","萧然宇宙间，昏雾一疏瀹。","虽忻意暂豁，所叹施未博。","雷霆司天令，何乃久寂寞。","微阴虽自复，阳亢不为却。","安得跻帝阍，一鼓造化橐。","太上方厉政，进贤登謇谔。","日将太平近，此变不应作。","吾徒勿咨嗟，坐看雨时若。"]},{"t":"之石窟寺马上作","f":"五言律诗","c":["今辰忘我劳，幽事随所历。","翠麦回一川，黄花明半壁。","山林契宿尚，老大悲物役。","便欲从溪僧，分居窟崖石。"]},{"t":"之灵岩三首 其三","f":"五言律诗","c":["山高景逾变，所览今非昨。","云覆嵩顶寒，河倾滩面□。","□中塔庙涌，日暮钟磬作。","延首望洛城，气象□□□。"]},{"t":"之灵岩三首 其二","f":"五言律诗","c":["朝行曲河道，暮夜不遑止。","野草熏满衣，山蝉鸣裂耳。","我仆痡秋阳，我马困石齿。","未厌行役劳，当前碧蒿起。"]},{"t":"之灵岩三首 其一","f":"五言律诗","c":["积阴旷初霁，策马望嵩洛。","斜日黑云西，回光照城郭。","牛散陂草深，蛙鸣沟水浊。","雷远尚馀音，山前垂雨脚。"]},{"t":"之祀奉呈同行二进士","f":"五言古诗","c":["煌煌儒者宫，是惟风教首。","群贤日造集，经训谨传授。","公田有常廪，著令所从久。","逋租积岁月，课督岂宜后。","浮舟出东郊，秋日丽榆柳。","幸同二三子，谈笑失炎昼。","鄙生窃薄禄，万补无一有。","伫观盛化流，朝列登秀茂。","彼微主簿官，岂敢息奔走。"]},{"t":"子张子夏庙同邻几圣俞过作","f":"五言古诗","c":["峨峨道旁庙，庭户焕丹黝。","恭闻师商贤，下拜奠卮酒。","大梁故王都，豪杰所奔走。","当时多尊荣，死不道人口。","二君夫何为，血食独传后。","岂于圣人道，自托致不朽。","荒坟屹相望，荆棘不盈亩。","衣冠应作尘，制度复何有。","得无埋奇书，文字暗科斗。","怀古意惨淡，春风一搔首。"]},{"t":"山林","f":"五言古诗","c":["长林翳空谷，兹惟群材府。","石路险且跻，不为斧斤取。","火云无时蒸，众叶朝自雨。","仰视不见末，飞鸟安得度。","下有灵药草，其品难记数。","骈然花实繁，红紫贯四序。","霜风落橡栗，投掷地虺怒。","过岭林更深，欲前防猛虎。"]},{"t":"从道损舅乞移山药","f":"五言古诗","c":["弱岁抱衰病，好读神农经。","杂然众药品，粗识性与形。","商于岩谷间，厥产芝朮菁。","山家乘冬采，气烈味亦并。","常思负笼往，斸此地气灵。","近闻山旁县，移本来公庭。","石泉尚含润，溪风有馀清。","想像春丛敷，蔚蔚扬华英。","骈罗良可佳，疲薾宜见矜。","安得畦畹馀，种食羽翼生。"]},{"t":"元道席上得秋风为题下为韵送广信舍弟","f":"五言律诗","c":["秋风感人切，况在欲别者。","狂翻断蓬转，寒助离樽泻。","吹云急燕雁，猎草嘶代马。","莫作塞垣声，端令客泪下。"]},{"t":"公孙孝子","f":"楚辞体","c":["丧期著常数，在古固有之。","嗟嗟三季后，礼让俗亦衰。","亲亡有不葬，况问功与期。","公孙布衣士，未免寒与饥。","生兮已不恤，死者吾敢欺。","孝生因其心，礼大实以时。","挺然颓俗内，独以古自为。","萧萧天平山，松柏有馀悲。","何以表懿行，刻此无愧辞。"]},{"t":"切切","f":"七言律诗","c":["我怀切切重切切，今日归当去年月。","香车不复故道来，血泪空沾旧行辙。","严风正射人面过，冻地惟忧马蹄裂。","举头且愿愁阴开，悲搅胸肠刻霜雪。"]},{"t":"化光东堂赋得奕棋","f":"五言律诗","c":["君家何所乐，棋奕侑清兴。","帘垂虚堂肃，子落文楸静。","机心久已忘，胜势安敢竞。","吾知霍将军，固亦有天幸。"]},{"t":"孔先生以仙长老山水略录见约同游作诗答之","f":"七言古诗","c":["群峰罗立青巉巉，中有佛庙名香严。","飞泉汹涌出峰后，四时激射喧苍岩。","跳珠喷雪几百丈，下注坎险钟为三。","援萝俯瞰石底净，明镜光溢青瑶函。","淙流四走渠为窦，左右吞啮何其馋。","缘源散讨不知极，但见洞穴争嵚嵌。","攀藤直上出云背，岩户秘邃疑神缄。","仰窥阴洞看悬乳，白龙垂须正䰐鬖。","或凝如盖覆宛宛，或散如指长掺掺。","有台高下且十数，如以势位相临监。","平铺老藓柔可坐，谁藉绿罽遗不拈。","北山之石何琐碎，形制一一如镌镵。","叩之清越诸谷应，不意此地闻韶咸。","已霜桂树垂冻壁，未腊梅蕊辉晴岚。","浮屠曰仙好事者，奄有胜迹穷搜探。","书之远寄龙山下，云此仅止存都凡。","先生以本来示我，谓我所好同甘咸。","相期历览在他岁，事高意笃非予堪。","人生萧散不易得，常苦世累为羁衔。","吾徒幸当治平日，况又无事于牵贪。","便须巾车不可后，愿以几杖从君南。"]},{"t":"忆宁极","f":"五言律诗","c":["雨滴庵上茅，风乱窗外竹。","繁声夜入耳，欲寐不得熟。","独怀归田客，石径滑马足。","连山暗秋雾，一灯何处宿。"]},{"t":"王家渡","f":"五言律诗","c":["浮舟乱清洛，中流望嵩少。","山晴水光晚，蓝碧近相照。","倚崖睨落日，坐觉身世小。","叹息浮生劳，临风一长啸。"]},{"t":"王詹叔惠酥","f":"五言古诗","c":["兴平产良酥，厥品为第一。","岁时盛献馈，霜梨副冰蜜。","东来连车轸，并走卫霍室。","盘筵得此物，主意自为毕。","詹叔官西州，遗我资口食。","甘知马酒薄，素觉鹅肪失。","我今农里人，藜藿度閒日。","多惭掷嘉味，徒用饱仁术。","厚意如何报，还持况贤质。"]},{"t":"东窗","f":"七言律诗","c":["高窗不掩秋气清，下见瓦沼涵泓澄。","雨洗浮萍翠色静，青丛绿蔓相缠仍。","阶前童童两好树，上有鸣禽不可数。","杖藜书生爱苦吟，独立西风无旦暮。"]},{"t":"令绰泛舟潩河作诗诒之","f":"五言古诗","c":["投闲归里闾，幸与故人遇。","情期夙所敦，邀迓已去屡。","尚嫌城阙拘，未尽林壑趣。","导河高其梁，轻舟具指顾。","寒花黄被堤，秋实翠登俎。","白须二三翁，相对无俗语。","夷犹起遐想，恬旷绝近慕。","适野讵有谋，登高亦非赋。","信哉庄生言，忘我带与履。"]},{"t":"冬至日作","f":"五言古诗","c":["初阳动新琯，微霰集前墀。","举宗会佳节，拜贺俨成仪。","念我闺中人，独此隔容徽。","昔同奉祭笾，今自享酹卮。","彷佛平生像，凄怆故年衣。","寒灯清无光，僮使侍虚帷。","对之忽悲结，零泪不可挥。","娇儿何所识，摴博自为嬉。"]},{"t":"出郊古意","f":"五言古诗","c":["跨马长林下，落叶填荒沟。","严霜熟秋实，野物毕以收。","空场委馀穗，雀鴳鸣相求。","仰视鸿鹄群，肃肃摩天游。","清风下哀响，静听令人愁。","时序迭而去，曾不与我谋。","小人急趋利，君子怀德忧。"]},{"t":"发襄城寄曼叔","f":"五言律诗","c":["别离何从生，乃生欢爱间。","一登君子堂，笑语十日连。","薄暮跃马去，飘忽如云烟。","毋言欢戚殊，世事举皆然。"]},{"t":"圣俞约晚见过不至","f":"五言律诗","c":["闻君敕车骑，晚驾慰愁独。","焚香霭疏箔，洒水静深屋。","高怀岂我遗，幽思方自续。","日暮尚徘徊，清风满修竹。"]},{"t":"对雨思苏子美","f":"七言古诗","c":["五月阴盛暑不效，飞云日夕起嵩少。","回风飒飒吹暮寒，翠竹黄蕉雨声闹。","北轩孤坐默有念，人生会合那可料。","昔与子美比里闾，是月秋近足霖潦。","吾徒无事数相过，日策疲马度深淖。","升君之堂伏君几，果饵罗列亦稍稍。","开樽得酒味已酢，辅以谐谑聊可嚼。","长歌激烈或孤起，大论纷纭特一噪。","飒然夜气变凄栗，连披短褐曳颠倒。","且欣主人同气类，安问邻家厌呼笑。","而今相望各千里，局促有如鱼在罩。","人生此乐不易得，世事荣辱何足校。","行当结侣候春水，一访洞庭湖上棹。"]},{"t":"对雨独酌","f":"五言律诗","c":["褰帘雨正繁，附火寒已薄。","修竹摇清音，芳梅绽朱萼。","感此时运驶，对酒成独酌。","多谢枝上禽，飞鸣慰寂寞。"]},{"t":"对雪偶成三颂呈芳公长老兼简收贵二上人 其一","f":"七言绝句","c":["空生去后花飞绝，庞老行时雪落频。","有句无言空不会，夜寒红燄一炉香。"]},{"t":"石藓","f":"五言律诗","c":["托根一何洁，冉冉冒幽石。","不学萝与薜，攀缘走岩壁。","云埋晓愈滋，雨洗秋更碧。","移来色难改，足慰思山客。"]},{"t":"立春观杖牛","f":"五言古诗","c":["清霜凉初曙，高门肃无哗。","行树迎初日，微风转高牙。","兹辰亦何辰，见此气候嘉。","有司谨春事，象牛告田家。","微和被广陌，缨弁扬蕤葩。","伐鼓众乐兴，剡剡彩杖加。","盛仪适未已，观者何纷拿。","因思古圣人，时儆在不差。","礼实久已废，所重存其华。","吾非鲁观宾，胡为亦咨嗟。"]},{"t":"仲连兄治南堂","f":"五言古诗","c":["予生乏时用，惟懒性所便。","强挽亦已退，虽鞭讵能前。","有园不盈亩，正在居南偏。","荒埋日失治，坐惜嘉观捐。","伯氏解官守，燕居此回旋。","芟芜属时暇，斫枯候春妍。","面堂一径直，夹树兰与荃。","畚土艺佳卉，沼盆注清泉。","东风过墙头，朱白争繁鲜。","芬香四飘散，蝶蜂来飞翾。","向时疏懒人，游步始连连。","微勤不少施，胜赏得以专。","才劳拙者逸，此固物理然。","作诗代俳笑，以继南华篇。"]},{"t":"仲夏田家","f":"五言古诗","c":["仲夏农务急，老壮纷盈畴。","上天无愆沴，登我蚕与麰。","晨兴腰镰出，子妇向田头。","绿树绕阡陌，当昼岂暇休。","柔丝缫满盆，新实已可羞。","归来一欢笑，卒岁期无忧。","为民各有业，处世无异谋。","但愿岁尝然，囷廪有乾糇。","糟床注浊酒，邻里日相求。"]},{"t":"伏日同当事诸君饮延祥观","f":"五言古诗","c":["适郊惮勤远，近市厌喧局。","纷然异趋向，日晏靡宁足。","回车憩琳馆，邂逅得所欲。","凉飙飒生林，飞雨时度竹。","醇醪挹云浆，佳果咀冰玉。","欢争校奕棋，谈笑追割肉。","兹辰著休令，嬉燕动辇毂。","聊从一时乐，庶以同厥俗。"]},{"t":"会圣宫","f":"五言古诗","c":["驱车□□□，回首望陵树。","冈原何郁盘，左右瞰龙□。","□□□□□，□此延真驭。","冠山崇朱堂，面洛□□□。","□□□□璧，铁马有馀怒。","深沉风尘表，想□□□□。","□朝尚仁俭，供养事殊古。","充邑无豪宗，埋枕废嫔御。","寂寞歌舞音，飞花乱红素。","小臣骇奇观，恍若梦帝所。","巍巍列圣业，欲颂惭非甫。"]},{"t":"再游薛园","f":"五言古诗","c":["朱樱满芳林，夏景始云变。","郊园掩深寂，休驾一来玩。","残花扫空蹊，密竹乱清涧。","置酒临层轩，波禽俯鸣泛。","南风扬绡衣，微暑忽飘散。","感此幽思生，吾其老佳观。"]},{"t":"列子庙","f":"五言律诗","c":["废垒荒祠古，空庭独树寒。","精诚褰画帐，事迹问黄冠。","晦昧尘笼墨，淋漓雨壁丹。","冷风满帘隙，仙驭或盘桓。"]},{"t":"同子华兄象之宿资福院","f":"五言律诗","c":["风尘暗西郊，野寺欣税鞅。","虚堂清气肃，偃仰百骸放。","至道本自简，欲语不可强。","夜深松桧寂，明月皎相向。"]},{"t":"同子华仲连二兄游湖","f":"五言律诗","c":["浊酒非陶令，方池似习家。","放船风动柳，著岸水涵花。","对影情无极，高歌兴转赊。","群鸟思共济，何必问仙槎。"]},{"t":"同陈太丞游龙兴寺经藏院","f":"五言古诗","c":["空堂洒寒水，碧楸凉漠漠。","高眠得珍簟，委弃巾与屩。","薰风穆然来，殿角鸣金铎。","清香有时闻，幽鸟无声落。","论诗爱平淡，语道造冲寞。","非吾方外友，谁当共兹乐。"]},{"t":"同陈道原谒象之","f":"五言律诗","c":["歊炎日为倦，休驾一潇洒。","风竹来迎人，翠色欲倾写。","神交不前约，至理非外假。","窅然天地间，谁是忘言者。"]},{"t":"同杨方叔游开宝上方有怀里中二三故人","f":"五言古诗","c":["京都寡临观，兹地高且明。","仲冬一来望，旷然写予情。","千载豪杰尽，夷门荆棘生。","时平盛民物，华屋连飞甍。","长烟冒百里，下视色正青。","慨彼尘土间，扰扰何多营。","往车无徐驱，来马无停征。","顾惭托閒官，幸得游衍并。","念我同里人，三四不在行。","孔公老龙山，孙子令江城。","崔閒盎有粟，辛困冠无缨。","一回西南首，惨淡意莫平。"]},{"t":"同邻几和叔登定力阁","f":"五言古诗","c":["清风何飘飘，万里吹曾轩。","侧身红尘外，却视飞云根。","王都屹雄胜，长河中怒奔。","上有怀归子，心随惊浪翻。","登临岂非壮，悲伤久客魂。","日暮下危级，且复同一樽。"]},{"t":"同邻几原甫谒挺之","f":"七言律诗","c":["河面参差结冻凘，清风不展画船旗。","偶驱羸马知何适，独过长桥问所思。","可喜身闲亲浊酒，未忘心竞是枯棋。","凭君莫唱阳关曲，自觉年来不能悲。"]},{"t":"同邻几避暑景德","f":"五言古诗","c":["脩廊环无端，华殿鸟斯革。","石鲸窥广庭，金像飞半壁。","高槐十丈馀，凉叶散檐隙。","兹游得我所，烈日徒自赤。","体烦惬清潭，发散谢危帻。","彷徉或持书，静默方对奕。","惟时骄阳甚，燥气裂金石。","城郭困风埃，田畴有忧色。","顾惭无用躯，独此享嘉适。","举头望赤霄，安得片云黑。","滂沱为飞霖，一洗周八极。"]},{"t":"同和叔饮王文正公三槐厅呈正卿","f":"五言古诗","c":["投杯送馀景，休驾避初燠。","久嫌花搅心，始爱树清目。","主人乐儒学，定契均季叔。","疏帘翳广坐，并荐肴与蔌。","肃肃太尉馆，简俭见遗躅。","中有戒子篇，惨淡刻寒玉。","世传盛德茂，名与清风穆。","公乎不可见，怅望三槐绿。"]},{"t":"同胜之明叔游东郊","f":"五言古诗","c":["仲冬景气佳，旷然思远涉。","晨遵大堤去，寒日在马鬣。","浮屠红尘外，楼殿焕层叠。","地遐幽景闲，瑶碧秀林叶。","清香时出箔，馀经尚委笈。","跻阁眺远陂，浮阳来晔晔。","花枝亦已柔，行见春露浥。","久耽田野乐，况与贤俊接。","逍遥永日暇，尘事不过睫。","昔人重时晷，所志树勋业。","慨予胡不然，空陋无所挟。","诗情朝生肠，酒气暮醺颊。","陶陶大化内，得此自为惬。","诸君能我从，游履方屡蹑。"]},{"t":"同胡江范邵裴二宋司马饮会灵水轩即席赋以日暮天无云春风扇微和为韵得日字","f":"五言律诗","c":["华轩压春波，樽酒四座密。","柔软柳间风，舒迟花后日。","晚色帘捲静，欢兴觞行疾。","一陪诸英游，黾勉惭落笔。"]},{"t":"同晏著作饮薛园坐中赋","f":"五言古诗","c":["鄙生秉愚尚，与世实龃龉。","寄身轩裳内，懒惰众不数。","朅来西都游，获并丞相府。","命驾多从君，载酒即得侣。","洛水南北涯，胜事著自古。","名园蔼相望，香刹屹时睹。","最怜薛家溪，架阁在西浒。","浑流激石来，知自嵩少雨。","如从柁楼下，夜听潮生浦。","采珠樱在盘，剥玉笋登俎。","杂花虽云晚，红白尚可取。","兴来倒冠巾，万事一尘土。","想在京辇日，耳目塞如堵。","出憎车马喧，坐厌名利语。","幸兹清景对，醉死亦吾所。"]},{"t":"同曼叔出郊","f":"五言古诗","c":["驱马信所适，路转上野桥。","桥边春水净，萦回带平皋。","两崖卉木茂，东风澹正摇。","故丛尚含绿，新芽已满条。","老小延我观，名品各异标。","问翁安致之，远自伊洛郊。","涉正曾未几，已觉芳意饶。","后日风更雨，繁红定飞飘。","顾谓同行客，有酒频我招。"]},{"t":"同曼叔观颍昌酴醾","f":"七言律诗","c":["前日看花花正发，今日看花花欲歇。","入门但见绿阴下，寂寞无人委春雪。","狂风飘簸百卉尽，惟有清香吹不绝。","攀条惆怅可奈何，与君把酒到明月。"]},{"t":"同曼叔诸君登醴泉观凝碧亭","f":"五言古诗","c":["门前车马尘，当昼塞昏雾。","安知此亭上，秋色生四顾。","黄花散晴阳，赤叶变寒露。","境非游览旧，人得朋从素。","乐幽鱼群行，赏俊鸟横度。","惜无一樽酒，留连清景暮。"]},{"t":"同曼叔游高阳山","f":"五言古诗","c":["久闻高阳胜，近在汝州侧。","跂予三年望，我愿今卒获。","烟云函两山，台殿开半壁。","解鞍高林下，仰视怯登陟。","苍松盘老枝，矫矫入檐隙。","微风韵其上，落耳寒恻恻。","枇杷两高树，中国所未识。","叶间青实骈，大与蜀土敌。","我来暮暮后，花草已狼籍。","不见踯躅红，西岩向人碧。","出门步榛荟，微径不可索。","援篱下幽涧，剥藓题苍石。","鸟啼无定音，虎斗有遗迹。","石台平挺挺，野竹瘦历历。","主人尉下邑，奔走困符檄。","喜我萧散人，幽奇共搜剔。","息阴时一憩，贪胜还自力。","归时山气冷，草露湿游屐。","举手谢峰峦，高秋复来觌。"]},{"t":"同曼叔游菩提寺","f":"五言古诗","c":["高城如破崖，寺带乔木古。","禅房掩清昼，佛画剥寒雨。","荒池野蔓合，浊水佳莲吐。","萧条联骑游，淡薄对僧语。","秋风日夕好，胜事从此数。"]},{"t":"同景仁况之诸君游南园饮梅花下","f":"五言古诗","c":["兹园旷不涉，寒草忽已芽。","同游三四人，及此风景嘉。","芳梅如我期，朱萼承素华。","欣然坐其下，偃君初月斜。","攀条酌醇酒，谈笑时一哗。","歌童虽非妍，清唱凌烟霞。","人生自有适，岂要外物加。","兴尽复云返，修竹盘昏鸦。"]},{"t":"同戴处士游湖","f":"五言律诗","c":["京尘倦游久，爱此西城曲。","泉温草尚青，春近波先绿。","幽人幸相对，高论良自足。","蚩蚩北州民，安得同我欲。"]},{"t":"同魏进道晚过湖上","f":"五言古诗","c":["春风湖上泮，奈此净绿何。","平堤看潋滟，皎如镜新磨。","支流别而东，下走万玉珂。","俜俜桥边柳，芳芽缀柔柯。","中洲嘉卉繁，条甲亦以罗。","游禽接翅羽，沉沉鸣声和。","避人去稍远，盘空落还多。","我来日已暮，伫视其顷俄。","羡尔禽类微，终年乐清波。"]},{"t":"后圃偶成","f":"五言律诗","c":["气昏聊止酒，讼简时闭阁。","池红落花委，岸绿新蒲合。","厌暄解重衣，息倦偃清榻。","永日林下风，山禽响相答。"]},{"t":"岁暮","f":"五言律诗","c":["高风动河汉，肃肃下阴霜。","起视夜向艾，华星粲相望。","犬吠闾巷静，哀鸿正南翔。","岁暮已多感，及兹重成伤。"]},{"t":"早登襄城之龙山呈曼叔","f":"五言古诗","c":["鸟啼斋前树，促驾吾当西。","朝从良友别，夕赴幽人期。","方以会合喜，敢曰道路疲。","予戆昧时利，百事弃不为。","惟有好贤心，未愧缁衣诗。"]},{"t":"次道东轩赋惜春","f":"五言律诗","c":["青春忽已晚，去我剧奔马。","残芳已扫园，浓绿空蔽野。","春风欲有问，对酒不能把。","人心正如此，狂雨自飞洒。"]},{"t":"次韵和平甫同介甫当世过饮见招","f":"词","c":["炎风得秋亦已凉，喜抱尘策罗南窗。","策中古人不可见，独咏君子予心降。","高文大论日倾吐，响快有类钟应撞。","却嗟吾侪多暇日，俚谣暴谑何其咙。","驱车正得我所念，起具肴蔌陈杯缸。","自怜愚戆接豪迈，蔽履乃与华冕双。","圣经王道有本末，斟挹醇粹挥其尨。","须臾上下今与古，武库千矛鏦。","疑怀滞义一开豁，有如暗室来明釭。","冯侯抗议亦殊健，短钩长?相撑摐。","介卿后至语闲暇，偃载戈甲韬旌幢。","弱弓枉矢尚何用，久已束手甘避逄。","是时君有山阳役，扁舟已具河之矼。","朝吟淮山翠扑扑，夜梦楚水鸣淙淙。","轩然欲去坐所惜，文字雅正姿信悾。","行年三十不得饱，况有荐道登朝邦。","遂令奔放不自敛，欲旅渔钓终湖江。","朝廷揽贤无远近，北尽漠塞南岭泷。","如君才大齿且壮，安可推亮而居庞。","功名得时看树立，岂若都尉眉空厖。"]},{"t":"次韵和永叔种菊过节方开","f":"五言古诗","c":["皇天于万生，难用一理晓。","芝兰喜憔悴，蒿艾长美好。","况兹封培晚，荣茂安得早。","赖逢贤主人，拂饰文字巧。","不然彼微芳，零谢同众槁。","清霜不能凋，秀色出庭草。","珊珊黄金明，落落众星小。","人生苦多累，适意会常少。","在昔陶公园，恨无酒樽倒。","敛襟赋寒华，高唱徒杳袅。","幸无斯人叹，一醉可遗老。"]},{"t":"次韵和君实寄景仁","f":"五言古诗","c":["予年行七十，惟日就志昏。","虽高鸿鹄举，尚困鸡鹜喧。","壮心久已摧，弱羽不得翻。","每诵少游言，顾惭下泽辕。","蜀公有高志，谢事久杜门。","扰扰世俗务，不复挂口论。","群经杂图史，拥坐如周垣。","上谈千载故，速若水注盆。","客来必命酒，左右拱诸孙。","虽无鼓舞欢，自喜谈笑温。","仰高顾吾私，有类羝触藩。","尚期蓬荜完，亦有桑榆存。","近观敕子诗，尤见朋义敦。","卜居近吾庐，指日驾君轓。","构堂始云基，筑圃亦已樊。","前知会合期，不惨离索魂。","想像入第初，亲宾燕华樽。","谈高一理会，体王百疾奔。","共完天纯粹，岂识世诈谖。","方笑司马翁，独乐守空园。"]},{"t":"次韵和李公达见寄","f":"七言律诗","c":["五分符竹尽吾乡，圣主恩私溢故常。","揽辔岂能清北道，支筇时得问西堂。","湖边冻柳生春意，月下晴梅动暗香。","乘兴可能同一醉，闻君筋力尚坚强。"]},{"t":"次韵和相公九月八日所赐诗","f":"七言律诗","c":["丛头金菊层层闹，木末丹花艳艳红。","美景岁时暌寿斝，流光朝暮阅疏钟。","诗成洛社腾邮置，梦绕伊川捧杖从。","早晚安车来就第，樽前重奏喜相逢。"]},{"t":"次韵和原甫游会灵观","f":"五言古诗","c":["松乔去我久，高驾不可攀。","何意尘外游，近在王城间。","先帝昔临御，抱冲启玄关。","营宫奉岳镇，缥缈当人寰。","疏泉抗台殿，拟迹三神山。","想像列仙下，半空来佩环。","云车倏容与，旄节俨成班。","翩翾万玉女，红颊翠羽鬟。","世人那得见，石坛空自闲。","伊予厌羁局，酷甚负病瘝。","兹行适所愿，帖若贾在阛。","春风吹园桃，几日朱霞殷。","寒碧竹间见，新黄柳际还。","主人非素期，促具初无艰。","抗侯角善手，持觞发欢颜。","尚无形骸累，安问绂与纶。","跋马兴不尽，东池水潺潺。"]},{"t":"次韵和崔朝散西湖避暑","f":"五言古诗","c":["人生苦炎歊，我所得萧爽。","乔林无纤穿，好鸟不停响。","冯轩纵遐瞩，万象归一掌。","道心流水闲，世事浮云往。","岂同中林士，所乐在膏壤。","寄语同心人，金鳞当透网。"]},{"t":"次韵和景仁兄","f":"五言律诗","c":["既酬斯有酢，在礼犹可追。","起劝孰曰狂，狂在捉白髭。","白髭虽见捉，渌酒安可辞。","歌童小如拳，聊以开公眉。"]},{"t":"次韵奉答君实问禅","f":"五言律诗","c":["仲尼称无我，老氏贵不仁。","存心一邻虚，去道万由旬。","入俗权立圣，达空安取真。","摩诘非有法，还公本来人。"]},{"t":"次韵答和乐道侍读给事","f":"五言古诗","c":["岁丰讼滋简，拙守容晏眠。","起来视云景，春意亦已鲜。","驱车望南城，精庐屹当前。","华堂坐沈邃，迟日步暄妍。","流览高僧壁，稽首金像莲。","即事岂非适，感怀良慨然。","宫藩与乡闬，早接二公贤。","高文炳群宿，大论倾长川。","尔来曾几时，急景凋朱颜。","从容味真理，萧洒赋高篇。","岂无安民策，坐惜成弃捐。","尚期雅正音，入和薰风弦。","余本岩壑姿，台阁缪见延。","渊明亦有言，误落尘网间。","命固有行止，理非可控抟。","素发纷已垂，行当挂吾冠。","侧闻治林圃，栽插及晴天。","芳芽吐膏壤，柔条擢暖烟。","光景非我力，为君导鸣泉。"]},{"t":"次韵谢尉公靖同游北园五首 其五","f":"五言律诗","c":["九夏困炎毒，出门如探汤。","不知此幽亭，俯仰皆清光。","寒流给我濯，白云供我望。","况有尊中酒，犹泛残菊香。"]},{"t":"次韵谢尉公靖同游北园五首 其四","f":"五言律诗","c":["今兹冬已孟，青林犹蔽野。","爱此晴景嘉，置酒衡茅下。","缅思陶公句，异代同潇洒。","结庐在人境，而无车与马。"]},{"t":"次韵谢尉公靖同游北园五首 其三","f":"五言律诗","c":["凿堤要水近，依竹任径斜。","残叶时委地，晚笋犹穿沙。","不知人间世，况论空中花。","却思城市喧，阁阁鸣群蛙。"]},{"t":"次韵谢尉公靖同游北园五首 其二","f":"五言律诗","c":["阴阴乔木交，竦竦修竹翠。","黄花与丹实，夹路何琐细。","是辰雨新足，支策问田事。","一感孤征鸿，泪落衣襟际。"]},{"t":"次韵谢尉公靖同游北园五首 其一","f":"五言律诗","c":["我本岩壑人，何意裨衮阙。","一从谴逐归，林下聊散发。","步堤得幽花，照水见新月。","即此穷朝曛，平夷免歌蹶。"]},{"t":"灯夕次韵答微之","f":"七言律诗","c":["白首还家再遇春，每将弦管乐脾神。","况逢旧相分藩契，仍喜闲官脱世纷。","灯散异光全作昼，歌翻新调欲留云。","归时绝景醒馀醉，极望银蟾照玉尘。"]},{"t":"百合花","f":"五言律诗","c":["真葩固自异，美艳照华馆。","叶间鹅翅黄，蕊极银丝满。","并萼虽可佳，幽根独无伴。","才思羡游蜂，低飞时款款。"]},{"t":"红雀集汜水罗者得之云来自新罗与圣俞皆赋","f":"五言古诗","c":["有翩者微禽，尔类何穰穰。","饱飞檐栋间，千百齐下上。","几人习汝见，于命保无枉。","尔胡丹其质，投翅落异壤。","殊尤众所骇，安得免罗网。","苍茫海外国，长抱万里想。"]},{"t":"自静教院晚步潩上","f":"五言律诗","c":["雪尽冈头路，风和腊后天。","人安闲淡内，鸟下寂寥前。","冻水晴初浪，荒城晚自烟。","西桥车马急，归意尚留连。"]},{"t":"行庆关","f":"五言古诗","c":["高关拒重阻，险状固天设。","俯窥洪流奔，仰视赤崖绝。","来往无时停，千载一车辙。","我行触飞雨，舍辔上嵽嵲。","筋劳不敢息，黄土百丈裂。","伊昔六国馀，楚汉起相啮。","乘时急形便，利害校一发。","生民入鞭笞，溪谷日流血。","时平属真主，汾壤事西谒。","翠华此回旋，万骑出岩阙。","斯人一何幸，泽浸厚地彻。","烜哉行庆名，高与日星揭。","干戈昔不守，符传今尚撤。","昏明变夷险，在德信前说。","愧无能铭才，吊古空惨切。"]},{"t":"西园","f":"五言古诗","c":["西园日修整，竹树相缀属。","春华犹未敷，气象郁函蓄。","密雨昏远林，轻寒傍脩竹。","于此隐几坐，物我同一目。","弟妹四五人，时来问幽独。","我云忧与乐，在志所徇逐。","无厌万钟慊，有道一箪足。","置是不须议，春醪满樽绿。"]},{"t":"西园暮雪","f":"五言古诗","c":["空园响松竹，霰雪霭霏霏。","仰视长云色，皓然同一辉。","天寒鸣雁急，日暮行人稀。","惟见众小禽，啾唧满林飞。","阴风起何处，拂拂来吹衣。","俯念当世事，幽愤不可挥。","归来散群帙，独掩袁安扉。"]},{"t":"西轩同诸君探题得食奁","f":"五言律诗","c":["简素与夙尚，提携得兹器。","春芳席馀红，夏木荫初翠。","酣游性所适，甘脆略云备。","独愧颜氏子，终朝守箪食。"]},{"t":"西轩席上探得丁香树子","f":"五言律诗","c":["物生各有性，矫之理宜伤。","如何生微木，揉结始滋芳。","开花不满把，琐碎垂丹黄。","岂识青桂枝，一引百丈彊。"]},{"t":"西轩欲雨同诸君偕赋","f":"五言律诗","c":["轻雷隐何山，云色如黛涌。","凉满翠竹浮，阴连芳树重。","烦襟一披豁，清思欲飞动。","会待急雨来，华觞与君捧。"]},{"t":"观龙和谢师厚","f":"七言古诗","c":["龙于经传皆有云，明幽其德能屈伸。","尝闻于耳昧厥真，乃今睹之信所闻。","层阴填空白日昏，仰见巨尾垂轮囷。","其长百丈围车轮，彷佛如辨鬣与鳞。","腥风萧飒来逼人，观者骇伏褫魄魂。","须臾摇动卷缩云，云气断岸随飞奔。","惊雷下震万瓦裂，暴雨一泻群河翻。","霆收无迹雨在物，吁龙出处何其神。"]},{"t":"观灯市井之利得雨农田所急而二者不可以并时乃所愿灯彻而雨作也今幸得之辄次原韵以酬来贶","f":"七言律诗","c":["风回协气通青律，月破游氛上碧天。","万盏华灯辉永夜，一犁甘雨报丰年。","梅含宿润妆先试，荑展新桑手不拳。","云势崇朝殊未已，坐看泽遍先垓田。"]},{"t":"观饲鱼","f":"五言古诗","c":["群鱼戏清川，容貌甚融易。","投饵落其间，纷争忽无次。","其来若有召，贪吻动如沸。","波间互出没，似亦夸巧智。","警跳鳞迸雪，饱泳尾摇翠。","安知沧海外，五犗不可致。","幸逢观者仁，不与钩网值。","庄生昔濠上，尝叹天理遂。","利心一以发，所向固多累。","我观虽有殊，我得岂云异。"]},{"t":"讲武池和师厚","f":"五言古诗","c":["沧池拟溟渤，莽漾豁厚地。","曰吾神祖为，气象固宜尔。","六合昔未一，教战出精锐。","至尊降黄屋，惨淡乘金气。","凌波飞百艘，撇烈若鹘翅。","扬旌万旅噪，伐鼓九渊沸。","其行速天旋，其止甚阴闭。","信乎王者师，足以服睽异。","尔来承平久，地与兵革废。","秋风长蒲苇，烂漫失洲沚。","惟见金明上，结构销绣绮。","春游驻天跸，万国奉燕喜。","铿鍧鼓钟响，杂遝羽旄美。","岂惟与民乐，施及鱼鸟细。","宏哉艰难业，愉怿逮万世。"]},{"t":"过李膺墓同曼叔作","f":"五言古诗","c":["汉衰奄寺炽，威柄敢专有。","桓桓李司隶，誓夺还君手。","登门盛贤俊，破柱发奸丑。","身虽以此亡，慕者犹恐后。","我行襄之野，把酹孤冢右。","精诚有相激，泪落入卮酒。","剖心死亦仁，灭顶过何咎。","大雅称明哲，于君岂其谬。"]},{"t":"初春吏隐堂作","f":"五言古诗","c":["微风稍破冻，芳萌亦吐林。","百鸟感春阳，钩辀弄其音。","振策遵城曲，逍遥写烦襟。","爱此堂下石，青润挺琅琳。","中坳贮清泉，测之不盈簪。","纤鳞候暖戏，寂历自浮沉。","默视澹忘虑，白日为移阴。","人生本虚静，垢浊无自侵。","忽为外物牵，至性不可寻。","于焉得所监，一洗尘中心。"]},{"t":"别曼叔","f":"五言律诗","c":["岁晏多感慨，况复饯之子。","腾装指近邑，弭盖眷同里。","日薄古原树，天寒石桥水。","毋为少别念，春风候车轨。"]},{"t":"君俞惠诗觅洛中所得大金菊辄次韵酬二篇 其一","f":"七言绝句","c":["繁英浮动满烟叶，爱重不减双南金。","陶公此兴亦不浅，聊赠翠茁酬高吟。"]},{"t":"听琴","f":"五言律诗","c":["达士寡世慕，至音遗俗弹。","一闻正始奏，坐使太古还。","残雪照樽酒，晴阳挂檐端。","曲罢了无得，清松空自寒。"]},{"t":"孝义桥","f":"五言律诗","c":["残花辞故都，细雨度清洛。","浮梁拖龙腹，径石乱鹅壳。","山形豁如对，林色秀可握。","渔子何处去，长罾波面落。"]},{"t":"拟杜子美体赋夏日閒居三章 其三","f":"七言古诗","c":["邻家芳树墙头垂，群鸦引儿日夜啼。","驱之稍去还满枝。","我初厌鸦挠吾静，听之既久理亦齐。"]},{"t":"拟杜子美体赋夏日閒居三章 其二","f":"七言古诗","c":["何所为乐夏日閒，手把内篇卧且观。","香气氤氲满帘间。","圆荷贴水雨打乱，青蔓挂壁风吹寒。"]},{"t":"拟杜子美体赋夏日閒居三章 其一","f":"七言古诗","c":["阶前萱草开丹花，竹根乱笋生如麻。","幽居无言感物华。","衡门流乱车马绝，绕舍阁阁喧鸣蛙。"]},{"t":"村居晓起","f":"五言律诗","c":["天星何寥寥，野旷风露清。","田父出门望，山鸦绕舍鸣。","蚕桑从此起，农里各有营。","顾惭不耕者，日宴掩茅衡。"]},{"t":"灵沟道中","f":"五言律诗","c":["久局慕遐放，出郊欣所瞩。","清心晓岫碧，豁眼春原绿。","耕人毕在野，鸣鸟催播谷。","嗟尔农事劳，愿闻时泽足。"]},{"t":"苏才翁与予定林下之约今被命提点湖南刑狱恐其侵寻而不能反作诗贻之","f":"五言古诗","c":["轩冕予已轻，山水君所乐。","相逢说高兴，南望欲奔趠。","今君被国恩，明刑弼予教。","群公许风棱，列郡瞻气貌。","朝廷方急才，悬爵待明效。","美官诚足慕，素约未宜挠。","当怀平生言，拔足利名罩。","笑谢世俗人，夷犹五湖棹。"]},{"t":"邻几和叔饮定力同赋","f":"五言古诗","c":["城头片云黑，飞雨霭已至。","凉生芳树颠，影乱樽中翠。","沈烦忽去体，精锐飒生思。","江翁发新嘲，陈子抗奇议。","在言岂多同，于道不为异。","夜归清有馀，微月照连骑。"]},{"t":"邻几舍对菊无酒","f":"五言律诗","c":["陶公爱佳节，对菊愁空杯。","日晏东篱下，竟见白衣来。","今君亦嗜饮，复有伊人才。","惜无王江州，黄花徒自开。"]},{"t":"邻几晚见过小饮","f":"五言古诗","c":["朝居厌喧呶，暮坐苦幽独。","忽闻江翁来，喜视樽中醁。","所惭升斗微，不足满君腹。","强酌良胜无，逡巡怯行速。","萧萧风著树，惨惨雨昏烛。","谈精几丧言，道在空击目。","此兴自不浅，岂要酩酊足。"]},{"t":"闲房书事示五弟及诸侄等献肃公","f":"七言律诗","c":["老病归休得桶栖，吾庐萧洒乐天倪。","北窗偃卧都何有，东阁过从亦自揆。","碧桧轻烟无鸟哢，绿槐风细或蝉嘶。","世间万事全如梦，岂得南华物我齐。"]},{"t":"饮圣俞西轩","f":"五言古诗","c":["欢常以饮合，欢意则非外。","今吾二三子，共此西轩会。","主人吾儒秀，言与二雅配。","酒行倡大论，文字略琐碎。","上言评人物，要当本诸内。","下言讥为学，不以满自概。","唐之众诗人，区别各异派。","一经君子评，敛凿弃秕糒。","予曰吾圣俞，名足通后代。","答我文如韩，尚有六经在。","况吾何所立，闻誉若抱趸。","圣俞善诱掖，斯语不无戒。","意欲令吾曹，事业进以大。","我虽顽无能，闻此亦健快。","呼觞满自引，不畏坐客怪。","归来书短篇，聊以记所佩。"]},{"t":"和十一侍郎","f":"七言律诗","c":["地传槐大井泉深，昔侍先庭此镇临。","奉使共成三世泽，思亲还怆百年心。","怀金岂足骄颜氏，抱瓮徒劳拙汉阴。","抖擞尘中千万虑，海风高处坐披襟。"]},{"t":"和三兄之山阳省孀姊书怀","f":"五言古诗","c":["君子蹈仁义，近自亲爱始。","当行岂顾留，千里犹举趾。","伯氏有东役，驾言适淮涘。","离樽未及展，浊醪未及洒。","起视白日移，驱车一何驶。","遵涂骊唱发，春风落端绮。","义参成周作，辞追建安轨。","感此留滞迹，一诵三四起。","安得假羽翮，远慰心所企。","此志良未遂，洒泣讵能已。"]},{"t":"和三兄立冬祠太乙二首 其一","f":"七言律诗","c":["楼外阑班晓斗垂，霜晴宫瓦湿琉璃。","珠幢羽节严仙仗，桂酒椒浆洁祠仪。","寒气导迎通律管，神光飞动属坛壝。","定闻贾傅开良对，天子斋居待受釐。"]},{"t":"和三哥入山二首","f":"五言古诗","c":["巢由没已久，风迹旷不嗣。","长啸箕颍间，悲风肃然至。","传闻龙山下，茅屋架三四。","中有隐者栖，读书乐仁义。","饱观人事变，深钩易象秘。","耕田给衣食，乡里沾赈遗。","呦呦山鹿群，摩抚驯不畏。","乃知至仁心，足以通异类。","声名自驰击，我心晏无累。","寤寐想斯人，安得同所致。"]},{"t":"和子华兄宴王道损公宇","f":"五言古诗","c":["济济高燕会，众宾且喜乐。","方冬气常温，是日寒始若。","愁云际平林，垂见雪花落。","四座喜相顾，有引必虚爵。","中堂岂非佳，东圃罗帟幄。","当亭列射格，抗的明灼灼。","雕弓既出韔，劲矢各在握。","主人揖让兴，客以次序作。","目惴綵树移，心倾钟鼓数。","笑言何谑失，仪节亦称娖。","酒酣事颇变，极口纵谈谑。","失令固有罚，出语辄见酌。","平生爱疏放，论议鄙龊龊。","欢来一狂散，岂顾醒后怍。","诗人亦有言，善戏不为虐。","所赖众君子，阔达见表襮。","还家遂酩酊，岂复记鸣柝。"]},{"t":"和子华兄寄酒走笔","f":"七言绝句","c":["开壶绿酒金英满，走笔彫章锦段成。","不假陶潜篱下望，更判五斗涤烦酲。"]},{"t":"和子华对雨有感 其一","f":"七言绝句","c":["小桃零乱逐东风，繁杏枝梢次第红。","把酒直须连日看，春光一半已成空。"]},{"t":"和子华许昌道中诗有隐逸之思","f":"五言古诗","c":["悲风中夜兴，寒气入我室。","颓然揽衣坐，中怀百忧溢。","我生乏壮图，少小事刀笔。","窥古得微尚，趋时寡良术。","野性不受羁，尘事忧见桎。","况兹罹大艰，哀号重衰疾。","生意且萧瑟，何必慕禄秩。","风俗日以恶，险诈路百出。","素昧防闲术，睹此实怖慄。","安能徇时好，哓哓丧天质。","所赖子华兄，志尚古人匹。","新诗来联翩，意韵时高逸。","中画归休计，罗列甚详密。","雅怀萧洒心，期言倘能必。","便当奉几杖，相与安蓬荜。","薄田能力耕，岁计犹不失。","结庐守松楸，筑圃蓺柿栗。","鸡豚燕嘉辰，鱼钓乐暇日。","读书取知道，白首穷经一。","甘从野儒事，庶保幽人吉。","咄哉轩冕徒，校此孰劳佚。"]},{"t":"和中道游金明池","f":"七言律诗","c":["出苑花光朱雪动，压波桥影綵虹摇。","飞扬莺燕惊高管，偃蹇鱼龙近画桡。","早识浮名身外事，久判闲日醉中消。","几年寥落同游伴，还喜春风并马镳。"]},{"t":"和太祝端居有怀叔恬秘书","f":"五言古诗","c":["鄙生复田庐，疏绝豪俊后。","侧聆杨生贤，名挂时辈口。","向风结遐想，几岁欲奔走。","比闻官旁郡，敛板不去手。","沈埋文俗间，有类鱼落笱。","颇思沿檄来，一洗烦滞久。","览君端居作，怀伫日延首。","窃高田苏游，遂信尹公友。","丈夫相期意，不必衔杯酒。","作诗助嘉招，此志非邂逅。"]},{"t":"和太素同看梅花寄子华","f":"七言律诗","c":["寒林冻卉谁观者，繁艳清香自得之。","天赋好花如有待，日寻幽径不知疲。","未逢驿使空怀远，犹喜山翁亦好奇。","昔岁一觞今一咏，共陶真意不为私。"]},{"t":"和王昭君","f":"五言古诗","c":["汉宫姝丽地，华观连珍台。","娥眉三千人，皆自良家来。","昭君乃独出，负色羞自媒。","一为丹青误，白雪成缁埃。","结欢万里外，不得少徘徊。","车马怅不前，观者为悲摧。","空令琵琶曲，千载传馀哀。","物生美恶混，天意未易回。","兰茝苟不珍，且愿生蒿莱。"]},{"t":"和圣俞斗山鹊","f":"五言律诗","c":["禀此分斗姿，用舍在所激。","翻跳巧相中，一败躯命掷。","晨鸡鸣不渝，霜隼时乃击。","既无一二效，岂不愧肉食。"]},{"t":"和圣俞饮会之作","f":"五言古诗","c":["幕府多俊良，乘间得邀命。","陈觞四座合，清笑发高兴。","冰梨走咸黾，霜橘荐穰邓。","肴羞愧无珍，粗竭我家称。","礼酬嫌已拘，戏罚甘太横。","诗诵唐人为，议法汉儒正。","新嘲时巧发，诡令或孤迸。","聊矜一时快，岂校负与胜。","行伤昆弟别，且乐宾友盛。","但愿会合频，醉日敢辞并。"]},{"t":"和圣俞饮廷老家晚又饮原甫家","f":"五言古诗","c":["人生天地间，常为外物驱。","自非无心者，不能忘所趋。","所趋既若一，莫如饮酒娱。","饮酒既复醉，万事皆分铢。","醉心兀无思，安问贤与愚。","醉目浩无睹，安识嫱与嫫。","是非两弃绝，幸免祸患俱。","况吾二三友，襟抱达者徒。","所营既同方，所处又比闾。","惟吾廷老生，宛在城北隅。","北隅虽云远，跨马亦须臾。","季冬阴气凝，风力利石砮。","从今雪花落，径往不待呼。"]},{"t":"和圣俞闻景纯吹笛妓病愈","f":"七言古诗","c":["刁侯好事闻当年，至今风韵独依然。","归来不作留滞叹，能出窈窕夸樽前。","前时宾客会清夜，横笛裂玉吹孤圜。","新声妙逐柔指变，馀响欻与高云连。","悲风萧瑟四座耸，清笑自足遗拘挛。","近闻有疾勿药喜，主人欲饮期数贤。","气羸曲节宜少缓，体软舞态当益妍。","人生行乐不可后，幸及华月秋娟娟。"]},{"t":"和圣俞逢羊","f":"五言古诗","c":["雉以媒就获，鹿以由见羁。","物情非本然，实自巧者为。","惟人莫或使，势利中夺移。","朝游固金石，暮变险阱机。","世路有如此，君无独羊悲。"]},{"t":"和圣俞喜雪","f":"七言古诗","c":["穷冬不雪天子忧，既祷乃降惟神休。","人间半夜天地白，灵泽一洒万汇周。","乃知天人相响影，自古王者重修省。","登贤黜邪朝序清，锄奸戮妖海波静。","群公不劳岁奔走，四时不干雨旸正。"]},{"t":"和圣俞游梁王吹台有感","f":"五言古诗","c":["高台压万井，四绝埃与氛。","上有金仙庐，凌虚结楣棼。","尝闻登其巅，直视太行云。","壮观良跂予，夙驾惭后君。","况当朱炎月，烈风来朝曛。","泛潋白正醴，飘飖轻练裙。","想像箫鼓处，寥寥如有闻。","一写沈郁忧，怀古何足云。"]},{"t":"和永叔小饮怀同州江十学士","f":"五言古诗","c":["翰林文章伯，好古名一世。","家无金璧储，所宝书与器。","北堂冬日明，有朋联骑至。","新樽布几案，二鼎屹先置。","大鼎葛所铭，小鼎泽而粹。","坐恐至神物，光怪发非次。","群贤刻金石，墨本来四裔。","纷穰罢卷轴，指擿辨分隶。","其中石赞藏，家法非一二。","精庄与飘逸，两自有馀意。","兴来辄长歌，欢至遂沉醉。","颜饥足箪瓢，韩饮尚文字。","乃知内可乐，不必钟鼓贵。","温温江冯翊，兹理久所诣。","赋诗多雅言，嗜酒见淳气。","岁晏不在席，使我长叹喟。"]},{"t":"和永叔言怀","f":"五言古诗","c":["弱岁抱衰病，掩关卧园庐。","端居寡人事，永日惟对书。","得花辄手植，生草每自锄。","最怜脩竹姿，擢干青玉如。","添栽岁岁广，翠色满窗疏。","起坐一堂内，乐此不愿馀。","偶来从吏役，幽事日以疏。","出门何所见，扰扰尘中车。","素怀就湮没，有恨不可摅。","尚念禄仕微，欲返复踌躇。","高贤侍天陛，文章冠严徐。","迹虽台省游，志慕江湖渔。","凤皇览辉下，阿阁正其居。","顾惟蒿艾翮，分甘侣田鴽。","因诗益自警，庶不忘厥初。"]},{"t":"和玉汝弟感秋偶书","f":"五言古诗","c":["园林雨馀清，碧色遍秋草。","露叶委闲阶，风荷乱幽沼。","晨昏爽气嘉，吾意欲轻矫。","古来达道者，冥冥独见晓。","四序虽代换，一物未尝老。","况兹浮幼质，终非智人保。","唯有至真界，日日无非好。","岂同世俗情，妄计迟与早。","矢诗勿庸多，万事一能了。"]},{"t":"和仲巽诮京尘","f":"七言律诗","c":["轻如游泛坌如驰，朝雨才暗暮即飞。","常恐旱风增气势，却教晴日损光辉。","衣缁京洛言何验，缨濯沧浪志尚违。","此物无情君莫诮，九衢声利走轮騑。"]},{"t":"和冲卿晚秋过金明池","f":"五言古诗","c":["闻君西郊行，正值秋风晚。","清霜卷枯荷，碧玉瑩池面。","浮空结脩梁，涌波抗华殿。","云烟渺净色，览望一萧散。","缅思暮春际，都人盛嬉燕。","连帷错绣绮，方车骛金钿。","填填鼓钟响，耳目厌哗眩。","乃令尘嚣辞，而有清旷恋。","达人冥至理，喧寂无异观。","偶然秉化往，何适非汗漫。","吾知禦寇游，所乐在观变。"]},{"t":"和刘郎浴观音予置酒见贻","f":"五言古诗","c":["禅关严城侧，深靓辟华构。","方吾挟书来，值子出杅后。","欣然出浊酒，谈笑坐清昼。","三四同来人，颇喜出邂逅。","牵衣起相酌，曾不烦劝侑。","纷披索潜逃，顾壁恨无窦。","不谓一樽乐，有踰万金寿。","瓶罍忽已竭，馀兴不自收。","走登故人堂，拜叙十年旧。","夜深跃马归，不畏妾妇诟。"]},{"t":"和如晦游临淄园示元明","f":"七言古诗","c":["平津开馆大道西，桃夭杳姹通园蹊。","东风入林朱白动，次第装遍枝高低。","红梅最好花正盛，我时往看归仍携。","尔来风雨就零谢，忍见踏尽随春泥。","广文先生厌闲冷，投书结伴散马蹄。","主人同僚相门出，未肯朝暮甘盐齑。","欢然握手喜迎候，促具并走子与妻。","插芳咀甘不知去，归舍已见鸡在栖。","坐挥大句鄙凡近，脱落尘迹登天梯。","不因时节自娱放，颇置白黑为愁凄。","我昏如此漫不省，何异车鼓乐鴳鼷。","长安绿酒春正美，与子一醉万事齐。"]},{"t":"和孙廷平坦嵩山十首 其五 云际钟","f":"五言古诗","c":["层云冒诸岭，迢迢起何处。","稍与暝烟沉，还随晚风度。","声绝人倚楼，东风月才吐。"]},{"t":"和孙廷平坦嵩山十首 其六 天外峰","f":"五言古诗","c":["孤峰望不极，却视天形低。","天高岂可踰，直以云濛之。","何时一扫去，高下皎不疑。"]},{"t":"和孙廷平坦嵩山十首 其一 古木阴","f":"五言古诗","c":["山木以不材，故能遂拥肿。","阴成众人息，于世岂非用。","不用用已成，兹理古所重。"]},{"t":"和孙廷平坦嵩山十首 其四 垂崖鞭","f":"五言古诗","c":["蛰蛇拖脩尾，下映赤壁烟。","骐骥久不出，此物甘弃捐。","常恐雷雨至，飞起苍崖颠。"]},{"t":"和孙廷平坦嵩山十首 其三 孤竹蘋","f":"五言古诗","c":["春山夜多雨，点蘋生水涘。","谁与赏幽芳，惟有岩中子。","抱琴沙上立，日暮清风起。"]},{"t":"和孙廷平坦嵩山十首 其十 幽谷泉","f":"五言古诗","c":["鸣泉泻幽谷，谷响声又激。","上荫百丈松，下有无数石。","会脱炎天屦，坐浸两脚赤。"]},{"t":"和孙廷平坦嵩山十首 其九 春溪水","f":"五言古诗","c":["阳生溪谷温，坼坼冰面破。","渌随波色还，白放云光堕。","野鸥岂知此，终日忘形坐。"]},{"t":"和孙廷平坦嵩山十首 其七 秋原菊","f":"五言古诗","c":["秋风原上菊，百草同蕃滋。","霜至草已死，黄花始离离。","君子不独异，显晦顾有时。"]},{"t":"和孙廷平坦嵩山十首 其八 渔舟火","f":"五言古诗","c":["拖网潭上归，孤烟出峰背。","稍没寒雾中，微明秋雨外。","起我江湖心，鲈鱼方可脍。"]},{"t":"和孙廷平坦嵩山十首 其二 寒溪石","f":"五言古诗","c":["寒溪水痕落，怪石千万状。","须防游屐滑，不碍钓舟漾。","安得平若席，卧看孤月上。"]},{"t":"和朱少府","f":"五言古诗","c":["自我还故栖，再见炎与凉。","朝游每含哺，昼坐常焚香。","撷圃得奇艳，俯池鉴清光。","不忧饥所驱，非为饱则飏。","同里四三人，每过必命觞。","浊醪无孤斟，嘉果有新尝。","看舞雪翻席，度曲尘飞梁。","桑榆傥徘徊，此乐未渠央。","行止固有命，贵弃乃其常。","与君酣且歌，幸世方欢康。"]},{"t":"和朱簿对雪","f":"五言古诗","c":["公堂寂无事，默坐拥重裘。","馀霰竹上集，寒风日飕飕。","哀鸿不停征，好鸟鸣相求。","君能于此时，为我发新讴。","上言有年庆，幸免刺史忧。","下言美光景，宜以欢燕酬。","名园抱城角，亭观俯清沟。","松桂有佳色，芳梅朱白稠。","晨昏傥霁止，当复从君游。"]},{"t":"和江十浮光隐者","f":"五言古诗","c":["我本岩壑性，落身名利场。","譬如笼中鸟，飞举意不忘。","常恨此世人，与古不相方。","争名塞朝市，养志空岩房。","近闻二三子，卜筑淮山旁。","松柏手自种，夏阴郁苍苍。","晨钓淮上石，暮返林中堂。","琴樽自为乐，过是皆秕糠。","乃知天下士，未易一概量。","好事江夫子，慕之著辞章。","名落尘土间，清风何激扬。","安知后来者，不及董与黄。"]},{"t":"和君俞属疾见诒","f":"七言律诗","c":["密桐新筱昼阴阴，独想禅房燕□□。","□□□□何者病，一尘不立本来心。","生涯易足惟高枕，物累难除是苦吟。","乘兴几时回杖履，后池泉溜有馀音。"]},{"t":"和吴九王二十八雪诗","f":"五言古诗","c":["方冬气潜温，得晚阴始重。","狂随风力翻，怒若云面涌。","中微玉霏屑，后盛毛纷氄。","寒光动城阙，甘滋入田垄。","鹏骞海水飞，骥愤盐车覂。","萦楼巧作层，覆道高城甬。","群方破昏雾，万物被光宠。","涂歌涵太和，送贺仰高拱。","判官坐丞华，赋诗掩垂陇。","貂裘拥宵谈，金杯落晨捧。","此兴吾不薄，君门旦当踵。"]},{"t":"和李大邻几圣俞及予见过小饮","f":"五言古诗","c":["朝朝骑马出，请道所从何。","所从亲且旧，恩义固匪它。","京都众权豪，门户高轲峨。","苟无势利求，安事徒奔波。","不如过亲旧，虽数无嫌诃。","君家庭馆闲，远在城北阿。","惟吾二三友，暇日一来过。","解鞭不肯去，得酒亦已歌。","况逢春阳始，风力渐柔和。","浮膏动郊壤，芳萌缀林柯。","良辰游不处，为乐戒蹉跎。","烂醉穷吾年，十日讵足多。"]},{"t":"和杜孝锡展江亭三首 其三","f":"七言绝句","c":["世情未免歌红粉，道韵无妨寄白云。","归路看花应更好，林间明月涌金杯。"]},{"t":"和杜孝锡展江亭三首 其二","f":"七言绝句","c":["惊鹭飞鸣避画桡，游人笑语过朱桥。","贾家园里花应谢，绿遍墙头野杏梢。"]},{"t":"和邻几社日","f":"五言古诗","c":["春阳□□□，□□□□□。","□□□流光，连坐叹故园。","游□□□□，□□□□□。","击鼓会乡人，莫觞为曰□。","□□□□□，□□割肉归。","独我恨不与，京尘空□□。","□□□时惊，先入旧庐飞。"]},{"t":"和邻几馆宿观伯镇题壁有作","f":"五言古诗","c":["城南饮骑散，君赴蓬山庐。","禁门肃清夜，飞阁何渠渠。","深沉漏下始，萧飒雨气馀。","俯仰河汉明，高情邈冲虚。","独怀同舍郎，被命分左鱼。","得州东南胜，绕郭生芙蕖。","苦嗟已留滞，三岁纷尘裾。","人生固不一，理亦相乘除。","或彼有所近，或此亦以疏。","冯唐匿郎署，白首常晏如。","方朔虽金门，避世等樵渔。","古来守道者，期不忘厥初。","但愿饮酒间，时读古人书。"]},{"t":"和叔惠荠","f":"五言古诗","c":["君居压城根，厥产地宜荠。","呼儿乘昼暄，培壤露寒翠。","撷之登盘蔬，蔼蔚见春意。","方其下箸时，绝甘遽吾遗。","物虽美芹微，意重生刍比。","苟为势利心，千金何足贵。"]},{"t":"和彦猷在华亭赋十题依韵 其十 三女冈","f":"楚辞体","c":["三女史无载，于何永其名。","坡传妃子逝，村记昭君生。","和戎与走蜀，为恨两莫平。","尔兮亦胡为，崇冈屹如城。"]},{"t":"和彦猷在华亭赋十题依韵 其三 吴王猎场","f":"五言律诗","c":["吴王昔用武，所乐惟干戈。","安知圣人意，祝网解其罗。","朝行数田获，暮返论战多。","千载亦何有，柔桑阴满坡。"]},{"t":"和彦猷在华亭赋十题依韵 其七 华亭谷","f":"五言律诗","c":["穹穹华亭谷，中有不竭流。","其微初滥觞，其大终载舟。","寒色皎可鉴，岚光郁如浮。","当解尘中缨，一濯潭上秋。"]},{"t":"和彦猷在华亭赋十题依韵 其八 陆机宅","f":"五言律诗","c":["出身岂明代，涉祸固以深。","一观废兴迹，可用当所箴。","高门非昔时，乔木或遗阴。","空令吊古士，感激成幽寻。"]},{"t":"和彦猷在华亭赋十题依韵 其六 陆瑁养鱼池","f":"五言律诗","c":["林塘岂如昔，尚想昔时居。","秋草自鸣鹳，寒波犹戏鱼。","纷纭钩饵底，琐碎刀匕馀。","任公有奇术，默坐岁几馀。"]},{"t":"和彦猷在华亭赋十题依韵 其九 昆山","f":"五言律诗","c":["晋衰士不竞，识者逃其名。","陆生起江湖，文藻振英声。","遂令昆丘号，长配山不倾。","君看玉就毁，孰与樗全生。"]},{"t":"和彦猷在华亭赋十题依韵 其四 柘湖","f":"五言律诗","c":["柘湖沦此地，柘山岿其濒。","复惊秦时女，化作湖上神。","世事喜反覆，孰能识涯津。","物变虽万殊，不惑固有人。"]},{"t":"和彦猷在华亭赋十题依韵 其五 秦始皇驰道","f":"五言律诗","c":["秦王骋奇观，不惮阻且脩。","万里走辙迹，八荒开囿游。","劳歌久已息，遗筑今尚留。","千载威神尽，骊山空古丘。"]},{"t":"和彦猷在华亭赋十题依韵 其一 顾林亭","f":"五言律诗","c":["昔人久尘土，问林得其居。","但传故老言，安知密与疏。","平湖无遗宇，寒烟生废墟。","风流未都尽，犹赖著书馀。"]},{"t":"和彦猷在华亭赋十题依韵 其二 寒穴","f":"五言律诗","c":["寒泉发何年，四序常自平。","上凛冰雪气，中密瑶玉声。","岂无蛇蜮潜，但见沙水清。","妄饮亦可戒，山木令人酲。"]},{"t":"和胜之弹琴","f":"五言古诗","c":["寥寥太虚内，漠然函至音。","淳源一以泄，其流播为琴。","众人玩其器，贤者识其心。","胜之明达士，于此趣已深。","发为新诗谣，如听松风吟。","钟牙久不作，谁辨雅与淫。","昭氏贵弗鼓，兹言良所钦。"]},{"t":"和胡公谨游李寺丞北园","f":"五言古诗","c":["春郊不数到，俯仰恨流景。","李侯有嘉招，滞念兹一骋。","名园带乔树，亭榭散清影。","解我尘中衣，觞行日舒永。","花团锦缬明，竹竦摇碧静。","从容方罫间，万事不关省。","善谑宁类鄱，高歌或如郢。","行遵水曲幽，望出林梢迥。","兴来非外奖，理惬有真领。","薄莫联归鞍，清风吹不醒。"]},{"t":"和原甫见送","f":"五言律诗","c":["德义良所慕，风霜轻此行。","放歌留客醉，高咏见公情。","祖帐重开席，郊原少驻旌。","还知别后意，寂寞对柴扃。"]},{"t":"和原甫去年对雪思梅今年对梅思雪","f":"七言古诗","c":["中州寒燠与南异，常恨梅花开不早。","今年朔雪冬不飞，腊月繁英似南好。","君怜芳物感时节，愁见高风冻雪扫。","苦嗟十九不称意，徒自令人颜色老。","雪迟梅早非我力，会使金樽日倾倒。"]},{"t":"和原甫盆池种蒲莲畜小鱼","f":"五言古诗","c":["江湖岂非壮，浩荡不可寻。","安知一斛水，坐得万里心。","植蒲翠节耸，种莲紫实沉。","群鱼不盈寸，泳浅安其深。","主人乐幽事，清兴生中林。","独观物性得，鹏海均牛涔。"]},{"t":"和原甫省中种菊","f":"五言古诗","c":["种菊待佳节，节至花自繁。","朝感凉风吹，夕爱清露团。","封培才几日，翠类纷珊珊。","君曹本称剧，占署无停翰。","才优顾多暇，曾不废览观。","作诗见高兴，读之起予叹。","念昔田里居，幽事颇复论。","种此黄紫杂，撩乱发墙根。","撷英泛浊酒，亲友日为欢。","一朝走京邑，连岁遭阻艰。","鬓毛将看白，泪眦荧莫乾。","时物岂不佳，感伤自有端。"]},{"t":"和原甫晓雨","f":"五言古诗","c":["喜雨濯炎夜，馀飞入晨光。","起来坐轩户，北风吹我裳。","碧折萱叶乱，翠添林笋长。","翩翩庭中燕，群飞戏清凉。","直恐烦暑尽，从此零秋霜。","欣然跨马出，一醉故人觞。"]},{"t":"和晏相公西湖","f":"五言古诗","c":["鸣蝉忽以急，夏景晏林塘。","不知何山雨，飒然送微凉。","荷茭忽翻倒，四散飘暗香。","清渠决决流，碧色浸稻秧。","零落堕林实，琐碎开水芳。","公来必乘晚，散步方徜徉。","箫鼓不从后，笔牍常在旁。","游鱼自成族，飞鸟不乱行。","周览时景佳，郁穆发新章。","何意蓬荜士，传贶谬所当。","时方苦炎暵，汗下挥其滂。","三复大雅作，清风肃衣裳。"]},{"t":"和晏相公泛南湖韦家园过西溪至许家园","f":"七言古诗","c":["湖心点点生圆荷，黄花白花满晴波。","环堤客树垂婆娑，鱼沉鹭矫各自得。","人生不乐其谓何，南塘过尽西溪绿。","上下名园依小曲，相君从容来赏瞩。","不驱大旆事喧闹，直解扁舟作幽独。","幕中宾从才且良，酒酣落笔摛文章，珠联璧叠争炜煌。","政成礼息无一事，明日复此醉华觞。"]},{"t":"和晏相公雪","f":"五言古诗","c":["去年阳气骄，不雪尽冬序。","今年未开腊，已见六花注。","矜新忽微飘，争急遂横骛。","浩荡天地和，旷爽楼观曙。","蔽日惊蛾飞，集廱纷鹭翥。","膏润通大田，光辉借前树。","萦檐鲁缟轻，委庭荆璞聚。","微生窗户明，巧作樽罍助。","相公谢朝柄，燕处均养素。","上嘉时泽滋，俯乐心赏遇。","南阁罢图史，西亭回杖屦。","步径怜缺玉，攀林看堕絮。","长吟写幽适，高隐动遐慕。","愧非右席才，莫奉梁园赋。"]},{"t":"和晏相公湖上遇雨","f":"五言古诗","c":["公堂日多暇，薄暮游清池。","孤云从西来，若与云盖期。","急雨乱荷芰，红绿左右披。","沙禽带湿起，簇簇守前坻。","烟树晦空曲，蝉声寂无遗。","残炎一洗濯，霁影开林西。","禽飞还清波，蝉噪复故枝。","晚槿扬朱华，秋草含碧滋。","篙舟出堤去，微风满平猗。","卷幔极长望，止见隗与箕。","举酒无尘情，慨然起遐思。","永怀古先训，默蹈通介宜。","乃知贤哲心，所得非游嬉。"]},{"t":"和晏相公触事成咏四首 其四","f":"五言古诗","c":["种竹患不多，既多亦为苦。","长根走地脉，凌突败垣堵。","物情有利害，为尔执挥斧。"]},{"t":"和晏相公触事成咏四首 其三","f":"五言古诗","c":["诛茅结园屋，日夕所游造。","雀来啄其茨，蚓出穴其穾。","中虚尚可托，外此非吾保。"]},{"t":"和晏相公触事成咏四首 其二","f":"五言古诗","c":["栟榈结双根，皮附若毛氄。","乘秋一剪剥，碧叶始竦竦。","岂识山中木，终年自拥肿。"]},{"t":"和晏相公触事成咏四首 其一","f":"五言古诗","c":["梧桐倾鸣凤，鸣凤邀高翔。","微虫缕众叶，玲珑秋日光。","本性苟不易，憔悴庸何伤。"]},{"t":"和崔象之颍桥观赠陈清臣太丞兼简陈","f":"七言古诗","c":["崔侯朝从西邑归，面有矜色口且咨。","云得高士陈其姓，非向可见所庶几。","尝登于朝最吏课，一旦去之心甚怡。","颍阳古观三日语，坐见月出青松枝。","深穷性命识原本，论议纯一无瑕疵。","周通旁畅未始极，曾不与道相乖违。","陈虽平生所未识，以子而誉信不疑。","向风长想日复夜，膏车秣马吾其西。"]},{"t":"和曼叔灵树相别","f":"五言古诗","c":["男儿易为别，寻尺固可轻。","今日掺子祛，悽惶不自平。","岂其道里远，要是隔音形。","春风卷行迹，车马无留征。","回首高阳峰，隐约林间明。"]},{"t":"和曼叔昆阳城","f":"五言古诗","c":["炎精灭无辉，贼莽伺天业。","帝乘馀运起，一剑无所挟。","皇天相其怒，雷电助震叠。","寻邑百万师，破碎在俄霎。","开汉中兴基，其犹取诸箧。","千载滍水上，行人指遗堞。","威灵久不泯，如与耳目接。","至今古祠上，过者犹惴詟。","荆芜起寒色，尚想战血喋。","屋瓦无遗处，秋风卷黄叶。"]},{"t":"和曼叔赋断蓬见别","f":"五言律诗","c":["霜蓬飞无根，岁暮随惊风。","翻翻走寒野，日以去故丛。","譬如远游子，飘泊从西东。","一感颍上别，慨叹发予衷。"]},{"t":"和曼叔憩永惠院","f":"五言古诗","c":["立春月在季，我时如滍皋。","惊风扬红尘，颇有行役劳。","自骇兹刹胜，愿言憩骖镳。","前对高花繁，后视万竹交。","虚堂坐閒敞，我辖忘载膏。","闻君戾止日，飞雨正萧条。","佳景忽在眼，恍如隔晨朝。","一吟竹边句，清思霭馀飘。"]},{"t":"和象之雨中见寄","f":"五言律诗","c":["沉阴子所叹，幽事我为乐。","雨沼散圆荷，风蛙乱灵药。","清凉体自正，虚静道所托。","谁识此中心，一樽成独酌。"]},{"t":"和景仁除夜","f":"五言律诗","c":["六十复过六，逐物何当足。","善恶两都忘，宁论择鱼肉。","流光速于电，至道明如烛。","孰谓吾庐卑，随时自凉燠。"]},{"t":"和曾令绰","f":"七言律诗","c":["卧病河桥与死滨，还家重喜见芳春。","辅藩行释绥安重，仁里欣闻缔构新。","危堞遍临双远岫，平湖不受一微尘。","知君雅有超然兴，香火它年作社人。"]},{"t":"和微之","f":"七言律诗","c":["庭讼萧然昼景清，每因闲暇接耆英。","言诗屡奉从容论，对酒常怀淡泊情。","解秩尚思嵩峤色，入朝还听禁钟声。","怜君壮岁多留滞，不尽鹏抟九万程。"]},{"t":"和微之喜雪","f":"七言律诗","c":["冻雨吹花六出成，高楼一见瓦□□。","已惊密势昏群岫，更想馀霖及列城。","照水□□生秀气，跳枝喜鹊弄和声。","曾陪舞蹈丰年□，□拥温貂梦帝京。"]},{"t":"夜坐有怀黎君","f":"五言古诗","c":["霜风动脩竹，寒月照广庭。","此夕南堂客，得无羁旅情。","束书万里外，徒步游上京。","岂惮行役劳，所期功与名。","高文日以丽，经义素所明。","顾我顽钝姿，无以延英声。","衔哀谢时好，守拙伏茅衡。","伫君取高第，光华慰友生。"]},{"t":"夜泊湖上","f":"五言律诗","c":["春风淡无力，池色晚更静。","人归箫鼓歇，月出楼观迥。","惊鸥啄浮星，游鲤下明镜。","谁当拿画船，彻夕纵孤泳。"]},{"t":"奉同冲卿元日雪霁朝会称觞","f":"七言古诗","c":["汉家万国朝元正，帝呵风师洒其廷。","雨寒成花皆六出，一洗天地尘埃清。","高风半天捲云去，空色绀碧惟华星。","金乌东来照宫殿，瑞气著物皆光荣。","绣衣虎士扶脩旗，皂旄绛幅纷葳蕤。","洞开重门纳冠剑，肃肃环佩来东西。","乐悬未作舞在缀，雉扇稍映宫帘垂。","黄钟独奏君德盛，赫然天日当彤墀。","群臣拜舞千万寿，四方来王敢不祗。","愚闻圣人制礼意，上崇一尊临众卑。","等威殊绝防僭慢，非止矜丽誇雄为。","仰瞻仪物固自肃，又况烜赫铺德威。","小臣不及观放仗，趋出恍惚犹惊疑。","朝廷大体安敢识，赞咏盛节形诸诗。"]},{"t":"奉同原甫郓州乐郊","f":"五言古诗","c":["诗人歌乐郊，以政不以游。","太守名是地，岂非为民谋。","下车布条教，惠爱春风柔。","丹笔平枉讼，赭衣息奸偷。","政和岁亦丰，闾里舞且讴。","及我闲暇时，驾言此淹留。","杂花艳暄朝，翠竹鲜霜秋。","有台下观渔，有堂前抗侯。","觞斝既纷错，管鼓亦喧啾。","都人从公来，小大毕休休。","施设苟异此，且为民所仇。","台高池益深，不若墟与丘。","贤而后能乐，轲言良有由。","聊书太守意，庶几来者求。"]},{"t":"奉同原甫度支厅壁许道宁画松","f":"五言古诗","c":["长松盘青冥，郁与窗户对。","许翁写生意，独得毫墨外。","年侵日昏剥，拂拭自君辈。","得非神物守，以待真赏会。","翛然簿书暇，恍若岩壑内。","举手扪紫烟，侧耳听清籁。","苍林与老石，野性旧所爱。","一从官都邑，兹游颇乖背。","慰此寤寐怀，典刑亦足赖。","幸当扫尘壁，促驾我其迈。"]},{"t":"奉同原甫赋澄心堂纸","f":"七言古诗","c":["江南国土未破前，澄心名纸世已传。","高堂久倾不复见，谁谓此物犹依然。","当时万杵捣云叶，铺出几案滑且坚。","剡溪藤骨不足数，蜀江玉屑谁复怜。","君臣嬉燕盛文采，骈章丽曲斗巧儇。","一朝零落随散地，中原箧笥生光鲜。","君安得此尚百幅，题以大句先群贤。","群贤落笔富精丽，琼琚宝玦相钩联。","嗟予材力岂当敌，虽欲强赋何能妍。","耽独玩物古所戒，崇尚浮藻政岂先。","江南可哀纸可惜，后有观者存吾篇。"]},{"t":"奉同原甫槐阴行","f":"七言古诗","c":["天门观阙双凌霞，下有驰道开平沙。","高槐左右覆朱梐，绿阴翠气相蒙遮。","朝回亘云下宝骑，游散掣电奔香车。","我惭太学官况冷，旦暮出此驱疲騧。","清风吹冷南就局，炎日转景东还家。","昏然百事不知省，空复春叶零秋华。"]},{"t":"奉和太素见诒","f":"七言绝句","c":["幸有新醪对新菊，莫叹樽前光景促。","请公更唱自为词，缓奏金丝续银烛。"]},{"t":"奉和兴宗腊日招宾浴普光","f":"五言古诗","c":["嘉腊世所用，况今以令休。","吾侪三四人，及辰为兹游。","兹游岂其远，东城大道周。","松桧寒色静，台殿香气浮。","振衣聊自洁，举觞复相酬。","淡泊顾多思，嘲谐讫无尤。","京都豪贵儿，良马轻衣裘。","飞鹰搏狐兔，驰突明星流。","归来击鲜饮，赵舞间齐讴。","岂不一时乐，此乐异我求。","愿君勤置酒，简薄非所羞。"]},{"t":"奉和象之夜饮之什","f":"词","c":["淫阴泄为雨，十日泻不停。","蓬蒿长四壁，浊潦流纵横。","嗷嗷鹤群游，阁阁蛙乱鸣。","端居积幽抱，沈郁久未平。","是时俯几望，月魄向已盈。","浮云失四顾，孤轮午亭亭。","微风濯炎热，衣巾凛馀清。","起我不暇懒，超遥步前庭。","烦忧忽以去，旷如出幽囹。","顾谓汝妻子，速具煎炮烹。","同里四五人，予期得邀迎。","随时具蔬果，饤饾甘与青。","虽无水陆珍，亦足侑杯觥。","所期在乘兴，岂问多品名。","诸君于我厚，匪貌实以情。","从容谈笑间，荡不见府城。","肴来必虚反，觞至无留行。","岂惟清言胜，或以善谑并。","高风揖巢许，旷论齐殇彭。","不知轩冕贵，直以道义荣。","置身岂非德，抚事临若惊。","上天作阴沴，降水灾吾氓。","芒芒郊野外，浩若翻沧溟。","垣庐随波尽，稼穑安有成。","所闻此害广，郡国多所更。","吾君急病民，定见宽税征。","囷廪无盖藏，何以活鳏?。","我曾不足恤，方以口腹营。","念始昔从学，潜心于六经。","颇知圣人道，要在及苍生。","胡为取自足，而不惟其赢。","顽然度岁月，如蛙守坳泓。","中而复自思，此其义所宁。","圣朝盛搜拔，列位罗群英。","晨兴朝国门，冠盖多于星。","呈材必夔稷，抗议皆颠闳。","双凫与乘雁，未足关重轻。","奈何不自量，欲以愚自呈。","退之亦有云，其犹进狶苓。","不如且饮酒，兹事未易评。"]},{"t":"奉送永州张中乐屯田","f":"七言律诗","c":["昔年曾读子厚集，梦寐彼州山水佳。","循良今慰远人望，潇洒仍惬旷士怀。","楼头打鼓散群吏，林下啼鸟眠高斋。","政閒境胜足佳句，好写大字镌苍崖。"]},{"t":"奉寄汝守仲仪舅","f":"五言古诗","c":["尝提十万师，为国捍羌寇。","严兵坐大府，诸将无与右。","旌纛俨成列，钟鼓振前后。","曰赏固自我，有诛孰敢救。","胜势前已决，威声日西走。","功名未及建，得此山城守。","捧诏顾东路，怡然引车就。","穷秋过旧许，整驾一来觏。","高谈不知疲，辄用火继昼。","卒无愠黜端，少以颜色漏。","乃知君子心，得丧不自囿。","悔非自取之，于道有不受。","徒然颂德美，洪量讵窥究。","孤城俯清汝，山势远相斗。","公庭日无事，燕坐阴华构。","林寒山雪飞，地静玉泉漱。","于兹乐天理，足使道牙茂。","时寄新诗章，穷闾慰衰疚。"]},{"t":"奉答圣俞寄鸭脚实见贻","f":"五言古诗","c":["南国有佳树，结阴君子堂。","秋风彫碧叶，素实登新尝。","缅怀朋游重，千里走绛囊。","朋游方会合，论文开酒场。","共嘉明物珍，含甘咏雕章。","章罢默不乐，为君一停觞。"]},{"t":"奉答吴殿丞见赠","f":"五言古诗","c":["势利跃谄子，声名走夸儿。","我于二无一，世固背以驰。","君从江海来，面有潇洒姿。","朝廷多旧游，绝迹不复追。","足音三及门，乃得众所遗。","长篇烂盈目，清远谬见推。","将非乐閒放，独与静者宜。","何以谢嘉况，湖山有前期。"]},{"t":"奉答张寺丞再招游薛园","f":"五言古诗","c":["名都富游践，所历多异境。","贪奇事穹览，一过不再省。","兹园独勤来，三尽昼刻永。","目清林叶净，耳快石泉冷。","如钱拾蟹壳，比针玩鱼影。","苦耽幽事乐，常使归思耿。","再招发新章，吾驾促当整。"]},{"t":"奉答原甫登契丹岭见寄","f":"五言古诗","c":["中原昔失御，幽冀不复华。","我朝示仁抚，金币岁屡加。","君恩谨宣道，使才慎推差。","翰林承命行，驱驾绝漠沙。","晨登寒山岭，回望万里家。","劲风搜貂裘，严冰断马挝。","乡心感归雁，塞泪零悲笳。","慷慨属国节，迢递博望槎。","幸古有此贤，庶足开颦嗟。","晴阳展归旗，喜气日以嘉。","入门解征衫，金樽滟流霞。","哀弦间清唱，娇鬟蔚如鸦。","一慰行役劳，期君柳初芽。"]},{"t":"奉答詹叔过澶之旧州有作","f":"五言律诗","c":["荒城岿遗堵，曙色起桑柘。","肃肃胡雁群，风急不得下。","子行感兴废，吊望一停驾。","缄诗寄故人，明灯读寒夜。"]},{"t":"奉酬乐道","f":"五言古诗","c":["故人从我游，里闬非潇湘。","文章老益壮，欲掩李杜光。","新诗来连翩，奔走获与臧。","调高岂能继，爱重如琳琅。","春风动地来，急雨催群芳。","梅蕊亦已落，坐看飞絮狂。","谁能于此时，默默但退藏。","且倾杯中物，莫顾腰下章。","缓舞金缕衣，高歌玉炉香。","白头自有乐，岂愧少年场。"]},{"t":"奉酬南陵三君别后见寄","f":"五言律诗","c":["斋居有常禁，跬步不得语。","清欢犹反思，浊酒成独抚。","野杏乱飞春，邻鸡静啼午。","寂寥正如此，坐见前山雨。"]},{"t":"官舍书事","f":"五言律诗","c":["官曹本自冷，况值秋风后。","落叶频委阶，斜光半穿牖。","幽闲夙所尚，默静颇能久。","门外声利喧，于吾竟何有。"]},{"t":"招景仁饮","f":"七言古诗","c":["红薇花拆萱草丹，万铃嘉菊重台莲。","问公此时胡不饮，乐有至理须钻研。","后夔已远师旷死，寂寞千载无其传。","公穷天数索圣作，坐使绿鬓成华颠。","屠龙绝艺岂世用，仪凤至业非公专。","洛阳有客金石坚，持议不屈难镵镌。","园收独乐会真率，以劳校逸宁非偏。","古称两忘化于道，此理岂不旷且然。","折花持酒待公醉，乐至无声方得全。"]},{"t":"放鱼","f":"五言古诗","c":["时哉清川鱼，罹此钩网牵。","稚子捧盘至，鳞采金翠骈。","一感仁者意，泳我清泠泉。","晨跳翻绿萍，暮息依白莲。","脱身刀俎间，永以终尔年。","唯昔郑国侨，亦尝叹悠然。","以方斯可欺，孟子称其贤。","永怀古人懿，屡叹春风前。"]},{"t":"服除送兄弟还都","f":"五言古诗","c":["日月忽已远，再见新谷升。","丧期有常数，吉我衣与襟。","俯仰自悲咤，泪下肝胆崩。","尚推立身报，未即泯馀生。","肃肃忠宪公，秉德辅休明。","报国有遗意，训言犹在听。","况兹世厚恩，兄弟秩王庭。","一朝出门去，事业各自营。","上当答君仁，下以为亲荣。","独此抱痾瘵，谢喧守柴荆。","扫冢奉时祭，履田课春耕。","既无公家责，聊徇狷者情。","出处虽云异，要以道为程。"]},{"t":"治圃","f":"五言古诗","c":["久雨地气泄，百草日以滋。","勃然翳我圃，积茀不可治。","遂令萧艾质，唐突兰蕙姿。","鸿鹄不肯下，跳蛙恃而嘻。","长林困缠绕，萝蔓郁四垂。","青云避蒙密，白日为蔽亏。","久与人迹绝，阴有物怪窥。","涉秋月既仲，薙人事芟夷。","援斧一挥拂，榛芜为之披。","俯怜蚁穴乱，坐听虫响移。","濯濯行树色，涓涓佳菊枝。","凉风自西来，众叶光参差。","墙堵豁已去，南亭见华榱。","却下走直道，无复蛇虺疑。","维此峙嘉堋，饮射之所施。","循玩失前秽，放怀得新怡。","如昔汉初定，礼法坏不支。","叔孙刬秦弊，树茅绝其仪。","皇皇天子庭，一旦罗尊卑。","表位肃以整，衣冠纷陆离。","圃也不足道，拔邪亦由斯。","作诗试永歌，愤涕下交颐。"]},{"t":"诗一首","f":"七言绝句","c":["鹤使晓来华表上，分明说得帝都春。","门开阊阖星河在，榜注神仙姓字新。"]},{"t":"郊居值雨","f":"五言古诗","c":["愁云覆西郊，气象凄以冽。","夜雨朝不止，冰霰相缠结。","南堂何萧条，散秩坐超忽。","颓然附炉炭，两髁冷如铁。","俯念田家苦，罹此寒事切。","北风卷平野，茅屋左右穴。","驱牛入门去，爨下火明灭。","场功始云毕，贫不具衣褐。","况无酒与羔，岁时相劳悦。","高咏七月诗，伤哉愁心折。"]},{"t":"金山寺","f":"五言律诗","c":["宝势中流起，香园此布金。","鸽栖秋殿冷，龙伏夜潭深。","水鸟衔生食，江神听梵音。","上方聊送目，天幕杳森阴。"]},{"t":"雨后之南陵点馔","f":"五言律诗","c":["斋房厌危坐，出户旷舒散。","草木雨多思，云山晚相乱。","萦回俯川陆，窈窕见楼观。","耳目久尘埃，兹辰一湔浣。"]},{"t":"监宿呈一二交游","f":"七言律诗","c":["墙根蟋蟀鸣不休，夜宿学省高梧秋。","昏灯钉壁照孤坐，悲风搅肠生百忧。","久从尘事非我意，直有烂醉为身谋。","谁能摆落世俗累，愿敝肥马同轻裘。"]},{"t":"南堂对竹怀江十邻几","f":"五言古诗","c":["端居无所聊，稍复治文字。","南堂冬日明，窗户暖可喜。","图书罗满前，意览不由次。","聊收静者趣，以乱忧人思。","亭亭当轩竹，使我长叹喟。","封植苦不早，颜色颇憔悴。","劲节亮不改，虚心如有迟。","缅怀江夫子，循道久不试。","邈然高简姿，不受世俗累。","一官才复进，左谪良何亟。","德义我所珍，轩冕安能贵。","长啸汝水滨，浊醪日自酾。","效陶有新篇，翼孔著高议。","弦琴坐虚室，默与古人值。","显晦一其心，淡然天淳粹。","思之不可见，暑谢寒已挚。","谅非对此君，兹怀何由慰。"]},{"t":"南堂席上赋得花树子","f":"五言律诗","c":["春风日暮急，薄寒生小苑。","群英不我遗，并坐慰幽蹇。","欢来引觞酌，快甚瓴水建。","才非孔文举，坐愧客常满。"]},{"t":"南溪","f":"五言古诗","c":["长林拂云根，一径绝城腹。","荆扉带翠樾，斗下地愈束。","清溪自南来，势抵北崖曲。","清平水流漫，东去入脩竹。","境幽百物遂，鱼鸟得所欲。","况依仁者居，不与钩弹触。","有如嘉宾至，相与娱听嘱。","鸟飞鸣我傍，鱼泳出深渌。","薄暮登前冈，四顾山在目。","雨滋春稼繁，风动野花馥。","达人乐天性，不待外物足。","遂令兹地胜，久不事营筑。","顾我指崖下，秋当结茅屋。","渠波环古台，辇石坐幽澳。","霜前复来观，兔肥山酒熟。"]},{"t":"哀传马","f":"五言古诗","c":["喧呼国西门，驿使通万里。","十亭传一马，日夜不得止。","枯肠嗛刍豆，瘦骨系辔箠。","力尽求未息，忽已仆泥滓。","死者既不补，存者行复尔。","闻古至治世，微物均福祉。","不壅王泽流，其先在官理。","国家富郡邑，一板万生齿。","付与有失宜，得无马之似。","投鞍坐太息，春为悲风起。"]},{"t":"春夜怀仲巽","f":"五言古诗","c":["今兹春始仲，气序忽已燠。","及此暇夜清，开轩散烦蹙。","金波丽中天，流光正穆穆。","佳树澄疏影，幽花运微馥。","浊醪时献斟，清论递往复。","诸季岂不欢，眷眷心所服。","高文炳辰宿，渊议赞化育。","匪才托游好，馀润久沾沐。","兹焉隔清赏，耿耿私恨蓄。","春芳正可乐，嘉会期昼卜。"]},{"t":"秋雨南堂即事","f":"五言律诗","c":["南堂秋雨清，竹树变愁静。","微寒病体苏，燕坐尘事屏。","高林飒已落，鸣雁去方永。","何以消沉忧，予心在箕颍。"]},{"t":"种柏寄苏子美","f":"七言律诗","c":["人皆种花我种柏，为此劲性寒不易。","三春虽怜少姿媚，岁暮方看霭颜色。","南堂之南可数到，列树六本翠磔磔。","安得驿使向姑苏，持以赠君比明德。"]},{"t":"览梅圣俞诗编","f":"五言古诗","c":["夙昔诵佳句，跂予慕高风。","何意忧艰馀，邂逅此相逢。","君初应府辟，捧檄来自东。","引车穷檐下，眷然顾微躬。","姿表穆以秀，纯德信内充。","乃知文章作，中与性情通。","煌煌新诗章，垂光照昏蒙。","启椟挹荆璞，引莛撞景钟。","高篇屡云阕，远思殊未终。","譬如巧琴师，哀弹发丝桐。","中有冲淡意，要以心志穷。","顾惟昧者听，莫辨徵与宫。","安得牙旷手，提耳发其聪。"]}]};